#[derive(Debug, Default, Clone, Copy)]
struct ChromeInputEpoch {
    window: u64,
    list: u64,
}

impl ChromeTask {
    pub fn command(self) -> ChromeCommand { self.command }
    pub fn escape_session_token(self) -> String { self.escape_session.as_simple().to_string() }
    pub fn escape_input_token(self) -> Option<String> {
        self.input_epoch.map(|epoch| format!("{:016x}{:016x}", epoch.window, epoch.list))
    }
}

impl ChromeCommand {
    fn changes_clipboard_presentation(self) -> bool {
        matches!(self, Self::Hide | Self::Show | Self::Fold | Self::Unfold
            | Self::EdgeHide | Self::RestoreEdge)
    }

    fn is_clipboard_list_input(self) -> bool {
        matches!(self, Self::RouteDigit { .. } | Self::ClipboardNavKey { .. }
            | Self::ClipboardSwitchTab { .. } | Self::ClipboardSearchBackspace
            | Self::ClipboardActivateSearch | Self::ClipboardAppendSearch(_)
            | Self::ClipboardHandleEscape)
    }

    fn input_window(self) -> Option<&'static str> {
        match self {
            Self::RouteDigit { .. } | Self::ClipboardNavKey { .. } | Self::ClipboardSwitchTab { .. }
            | Self::ClipboardSearchBackspace | Self::ClipboardKeyboardFocus
            | Self::ClipboardActivateSearch | Self::ClipboardAppendSearch(_)
            | Self::ClipboardHandleEscape => Some("clipboard"),
            Self::PanelNavKey(_) => Some("panel"),
            Self::HostKeyboardFocus(host) => Some(host),
            _ => None,
        }
    }
}

