fn qp_placement_request_error(body: &Value, current: QpPlacementIdentity) -> Option<Value> {
    let native = body.get("sessionRevision").is_some() || body.get("sourceHwnd").is_some();
    // Legacy callers may omit the revision. Native paint reports carry all
    // three identities; malformed integers must not truncate into a match.
    let revision = match body.get("stateRevision") {
        None if !native => None,
        Some(value) => match value.as_i64().and_then(|value| i32::try_from(value).ok()) {
            Some(value) if value > 0 => Some(value),
            Some(value) if value <= 0 && !native => None,
            _ => return Some(json!({"ok":false,"reason":"invalid-revision"})),
        },
        _ => return Some(json!({"ok":false,"reason":"invalid-revision"})),
    };
    if let Some(revision) = revision.filter(|revision| *revision != current.state_revision) {
        return Some(json!({"ok":false,"reason":"revision-mismatch",
            "expected":current.state_revision,"got":revision}));
    }
    if native {
        let session = body.get("sessionRevision").and_then(Value::as_i64)
            .and_then(|value| i32::try_from(value).ok()).filter(|value| *value > 0);
        let source = body.get("sourceHwnd").and_then(Value::as_i64)
            .and_then(|value| isize::try_from(value).ok()).filter(|value| *value != 0);
        let (Some(session), Some(source)) = (session, source) else {
            return Some(json!({"ok":false,"reason":"invalid-placement-identity"}));
        };
        if session != current.session_revision {
            return Some(json!({"ok":false,"reason":"session-mismatch"}));
        }
        if source != current.hwnd {
            return Some(json!({"ok":false,"reason":"source-mismatch"}));
        }
    }
    None
}

fn qp_placement_cluster(body: &Value) -> Result<Option<[f64; 4]>, &'static str> {
    let fields = ["clusterLeft", "clusterTop", "clusterWidth", "clusterHeight"];
    if fields.iter().all(|field| body.get(*field).is_none()) { return Ok(None); }
    let mut values = [0.0; 4];
    for (index, field) in fields.iter().enumerate() {
        values[index] = body.get(*field).and_then(Value::as_f64).ok_or("invalid-placement")?;
    }
    Ok(Some(values))
}

fn qp_placement_viewport(body: &Value) -> Result<Option<[f64; 2]>, &'static str> {
    if body.get("viewportWidth").is_none() && body.get("viewportHeight").is_none() {
        return Ok(None);
    }
    Ok(Some([
        body.get("viewportWidth").and_then(Value::as_f64).ok_or("invalid-placement")?,
        body.get("viewportHeight").and_then(Value::as_f64).ok_or("invalid-placement")?,
    ]))
}

