fn native_incoming_drag_for(inner: &HostInner, owner: &str) -> bool {
    inner.native_incoming_drag.is_some_and(|drag| drag.owner == owner)
}

fn native_context_menu_for(inner: &HostInner, owner: &str) -> bool {
    inner.native_context_menu.is_some_and(|menu| menu.owner == owner)
}

fn native_context_menu_root_hit(popup: isize, hit_root: isize, visible: bool, in_bounds: bool) -> bool {
    popup != 0 && hit_root == popup && visible && in_bounds
}

fn native_context_menu_owner_hwnd(inner: &HostInner, owner: &str) -> isize {
    match owner {
        "clipboard" => inner.host_hwnd,
        "panel" => inner.panel_hwnd,
        "main" => inner.main_hwnd,
        _ => 0,
    }
}

fn native_context_menu_trigger_root_hit(trigger: NativeContextMenuTrigger, current_owner: isize,
    hit_root: isize, visible: bool, x: i32, y: i32) -> bool {
    let (left, top, width, height) = trigger.rect;
    let in_bounds = width > 0 && height > 0 && x >= left && y >= top
        && left.checked_add(width).is_some_and(|right| x < right)
        && top.checked_add(height).is_some_and(|bottom| y < bottom);
    trigger.owner_hwnd == current_owner
        && native_context_menu_root_hit(current_owner, hit_root, visible, in_bounds)
}

fn native_context_menu_trigger_hit(trigger: Option<NativeContextMenuTrigger>, current_owner: isize, x: i32, y: i32) -> bool {
    let Some(trigger) = trigger.filter(|trigger| trigger.owner_hwnd != 0 && trigger.owner_hwnd == current_owner) else { return false; };
    if !native_context_menu_trigger_root_hit(trigger, current_owner, current_owner, true, x, y) { return false; }
    #[cfg(windows)]
    unsafe {
        use windows::Win32::{Foundation::{HWND, POINT}, UI::WindowsAndMessaging::{
            GetAncestor, IsWindowVisible, WindowFromPoint, GA_ROOT,
        }};
        // A window covering the button remains outside, even if its pixels
        // overlap the registered trigger or it belongs to this process.
        let hit_root = GetAncestor(WindowFromPoint(POINT { x, y }), GA_ROOT).0 as isize;
        native_context_menu_trigger_root_hit(trigger, current_owner, hit_root,
            IsWindowVisible(HWND(current_owner as *mut _)).as_bool(), x, y)
    }
    #[cfg(not(windows))]
    { let _ = (trigger, x, y); false }
}

fn native_context_menu_hit(popup: isize, x: i32, y: i32) -> bool {
    #[cfg(windows)]
    unsafe {
        use windows::Win32::{Foundation::{HWND, POINT, RECT}, UI::WindowsAndMessaging::{
            GetAncestor, GetWindowRect, IsWindowVisible, WindowFromPoint, GA_ROOT,
        }};
        let hwnd = HWND(popup as *mut _);
        let hit = WindowFromPoint(POINT { x, y });
        let mut rect = RECT::default();
        let in_bounds = GetWindowRect(hwnd, &mut rect).is_ok()
            && x >= rect.left && x < rect.right && y >= rect.top && y < rect.bottom;
        native_context_menu_root_hit(popup, GetAncestor(hit, GA_ROOT).0 as isize, IsWindowVisible(hwnd).as_bool(), in_bounds)
    }
    #[cfg(not(windows))]
    { let _ = (popup, x, y); false }
}

fn release_native_context_menu_locked(inner: &mut HostInner, id: u64) -> bool {
    let Some(menu) = inner.native_context_menu.filter(|menu| menu.id == id) else { return false; };
    inner.native_fifo_keyboard.retire_lease(id);
    inner.native_context_menu_keyboard.retire_lease(id);
    inner.native_context_menu = None;
    if menu.owner == "copy-toast" && inner.toast.visible {
        toast_arm_idle(inner, inner.toast.duration_ms);
    }
    true
}

