    pub(crate) fn quicker_rpc(&self) -> Arc<crate::quicker_rpc::Registry> {
        self.quicker_rpc.clone()
    }

    pub fn start_verb_rpc(&self) -> Result<(), String> {
        self.require_external_effects("start shared Quicker RPC")?;
        self.verb_rpc_stop.reset();
        crate::pipe_rpc::spawn_listeners(
            self.clone(),
            VERB_RPC_PIPES,
            self.verb_rpc_stop.clone(),
            self.verb_rpc_listening.clone(),
        )?;
        Ok(())
    }

    pub fn stop_verb_rpc(&self) {
        self.verb_rpc_stop.request();
        self.verb_rpc_listening.store(false, Ordering::SeqCst);
        self.quicker_rpc.disconnect_all();
    }

    pub fn request_graceful_shutdown(&self) {
        self.flush_for_shutdown();
        self.push_event("hostShutdown", json!({ "source": "verb-rpc" }));
        // Let the native runtime revoke OLE targets before COM/DLL teardown.
        self.enqueue_chrome(ChromeCommand::Exit);
    }

    pub fn health_cloud_sync_probe(&self, include_manifest: bool) -> Value {
        crate::cloud_rpc::probe(&self.quicker_rpc, include_manifest)
    }

    pub fn fa_vector(&self, spec: &str) -> Option<Value> {
        crate::fa_vector::try_get_vector(spec)
    }

    pub fn restart(&self, prefer_medium: bool) -> Value {
        if let Err(error) = self.require_external_effects("restart or replace process") {
            return json!({"ok":false,"restart":false,"error":error});
        }
        if crate::clipboard::is_headless()
            && !cfg!(all(feature = "native-acceptance", not(test))) {
            return json!({
                "ok": true,
                "restart": false,
                "message": "Headless host skips process replacement so C# ClipHost stays running.",
            });
        }
        self.restart_with_launch(prefer_medium, crate::process_restart::launch_new_instance)
    }

    fn restart_with_launch(&self, prefer_medium: bool, launch: impl FnOnce(bool) -> Result<(), String>) -> Value {
        self.flush_for_shutdown();
        if let Err(error) = launch(prefer_medium) {
            tracing::warn!(%error, "ClipHost restart failed; retaining current process");
            self.show_host_toast("重启失败，当前程序继续运行。", "error", Some("restart"), Some(4200), None);
            return json!({ "ok": false, "restart": false, "error": error });
        }
        self.enqueue_chrome(ChromeCommand::Exit);
        json!({ "ok": true })
    }

