    pub fn source_processes(&self) -> Result<Value, String> {
        Ok(json!(self.source_process_rows()))
    }

    fn source_process_rows(&self) -> Vec<Value> {
        // C# `GetDistinctSourceProcesses`: first-seen ExeName, OrderByDescending lastSeen (stable).
        let items = self.store().lock()
            .list_clips()
            .unwrap_or_default();
        let mut index: HashMap<String, usize> = HashMap::new();
        let mut rows: Vec<(String, DateTime<Utc>, i32, usize)> = Vec::new();
        for item in items {
            let norm = csharp_source_process_name(&item.source_process_name);
            if norm.is_empty() {
                continue;
            }
            let key = norm.to_ascii_lowercase();
            let last = if item.create_time > item.update_time {
                item.create_time
            } else {
                item.update_time
            };
            if let Some(&i) = index.get(&key) {
                rows[i].2 += 1;
                if last > rows[i].1 {
                    rows[i].1 = last;
                }
            } else {
                let first_seen = rows.len();
                index.insert(key, first_seen);
                rows.push((norm, last, 1, first_seen));
            }
        }
        // C# LINQ `OrderByDescending(lastSeen)` is stable (first-seen on ties).
        rows.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.3.cmp(&b.3)));
        rows.into_iter()
            .map(|(exe, last, count, _)| json!({ "exeName": exe, "lastSeen": last, "itemCount": count }))
            .collect()
    }

    pub fn clipboard_escape_session_token(&self) -> String {
        self.inner.lock().clipboard_escape_session.as_simple().to_string()
    }

    /// Page results belong to the display that issued Escape, not a later show.
    /// Native no-focus results additionally retain their list-input ownership.
    pub fn clipboard_escape_unhandled(&self, token: Option<&str>, input_token: Option<&str>) -> Value {
        {
            let mut inner = self.inner.lock();
            let epoch = inner.chrome_input_epochs[0];
            let current_input = format!("{:016x}{:016x}", epoch.window, epoch.list);
            if inner.window_visible && inner.clipboard_web_view_ready
                && token.is_some_and(|token| token == inner.clipboard_escape_session.as_simple().to_string())
                && input_token.is_none_or(|token| token == current_input)
                && !inner.spa_modal_open && !inner.spa_overlay_open && !native_context_menu_for(&inner, "clipboard")
                && !inner.ui.clipboard_editing
            {
                hide_clipboard_window_locked(&mut inner);
            }
        }
        self.window_state_dto()
    }

    pub fn window_hide(&self) -> Value {
        // C# `HandleWindowHide` → `ClipWindowManager.HideWindow()` → `{ ok: true }`.
        {
            let mut inner = self.inner.lock();
            hide_clipboard_window_locked(&mut inner);
        }
        json!({ "ok": true })
    }

    /// A native close (Alt+F4 / WM_CLOSE) must end the same input session as
    /// an in-page dismiss. Hiding only the HWND leaves invisible key handlers active.
    pub fn dismiss_native_window(&self, label: &str) {
        match label {
            "clipboard" => { self.apply_window_action("hide", true); }
            "quick-paste" => self.qp_cancel_session(),
            "copy-toast" => { self.toast_hide("dismiss"); }
            "super-menu" => self.super_menu_hide_session(),
            "panel" => self.apply_panel_hide(),
            "main" => self.apply_main_hide(),
            _ => {}
        }
    }

    pub fn fifo_preview(&self, params: &Value) -> Result<Value, String> {
        // C# `HandleFifoPreview` → `GetListDtosByIds(ResolveFifoPreviewIds)`.
        let ids = self.resolve_fifo_preview_ids(params)?;
        self.dtos_for_clip_ids(&ids)
    }

    pub fn fifo_arm(&self, params: &Value) -> Result<Value, String> {
        // C# `HandleFifoArm` / `ClipIdsRequest`: missing body → required; empty `Ids` →
        // `ids is empty.`; whitespace-only Distinct → `Unable to arm FIFO paste.`
        if params.is_null() {
            return Err("Request body is required.".into());
        }
        let Some(raw) = params.get("ids").and_then(|v| v.as_array()) else {
            return Err("ids is empty.".into());
        };
        if raw.is_empty() {
            return Err("ids is empty.".into());
        }
        let mut queue = Vec::new();
        let mut seen = HashSet::new();
        for id in raw {
            let Some(id) = id.as_str().map(str::trim).filter(|s| !s.is_empty()) else {
                continue;
            };
            if seen.insert(id.to_string()) {
                queue.push(id.to_string());
            }
        }
        if queue.is_empty() {
            return Err("Unable to arm FIFO paste.".into());
        }
        self.arm_fifo_queue(queue);
        let _ = self.window_hide();
        Ok(self.fifo_status())
    }

    fn arm_fifo_queue(&self, queue: Vec<String>) -> u64 {
        let generation = {
            let mut inner = self.inner.lock();
            Self::qp_retire_fifo_session_locked(&mut inner);
            inner.fifo_generation = inner.fifo_generation.wrapping_add(1);
            inner.fifo_total = queue.len() as i32;
            inner.fifo = Some(queue);
            inner.fifo_last_activity = Some(Instant::now());
            inner.keyboard_wakeup.notify_one();
            inner.fifo_generation
        };
        self.fifo_show_armed_hud();
        generation
    }

    fn qp_retire_fifo_session_locked(inner: &mut HostInner) {
        if inner.qp.fifo_generation == Some(inner.fifo_generation) {
            Self::qp_end_session_locked(inner, true, None);
        }
    }

    fn resolve_fifo_preview_ids(&self, params: &Value) -> Result<Vec<String>, String> {
        let selected = param_ids(params);
        if selected.len() > 1 {
            return Ok(order_selected_ascending(&self.fifo_candidates_for_ids(&selected)));
        }
        let end_id = params
            .get("endId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .or_else(|| selected.first().cloned())
            .or_else(|| req_id(params).ok());
        let Some(end_id) = end_id.filter(|s| !s.trim().is_empty()) else {
            return Ok(Vec::new());
        };
        let visible = {
            let listed = params
                .get("visibleIds")
                .and_then(|v| v.as_array())
                .map(|a| {
                    a.iter()
                        .filter_map(|v| v.as_str())
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_string())
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            if !listed.is_empty() {
                listed
            } else if selected.len() == 1 {
                selected
            } else {
                vec![end_id.clone()]
            }
        };
        let (burst, max_len) = {
            let cfg = &self.inner.lock().qp_config;
            (cfg.burst_gap_seconds.max(0) as u32, cfg.max_queue_length.max(1) as usize)
        };
        Ok(infer_from_endpoint(
            &self.fifo_candidates_for_ids(&visible),
            &end_id,
            burst,
            max_len,
            true,
        ))
    }

    fn fifo_candidates_for_ids(&self, ids: &[String]) -> Vec<FifoCandidate> {
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        ids.iter()
            .filter_map(|id| db.get_clip(id).ok())
            .map(|item| fifo_candidate(&item))
            .collect()
    }

    fn dtos_for_clip_ids(&self, ids: &[String]) -> Result<Value, String> {
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        let items: Vec<_> = get_items_by_ids(&db, ids)
            .into_iter()
            .map(|item| clip_to_dto(&item, None))
            .collect();
        Ok(serde_json::to_value(items).unwrap_or(json!([])))
    }

    pub fn fifo_cancel(&self) -> Value {
        self.fifo_cancel_with_reason("api")
    }

    fn fifo_cancel_with_reason(&self, reason: &str) -> Value {
        self.fifo_cancel_with_reason_if_current(reason, None);
        self.fifo_status()
    }

    fn fifo_cancel_with_reason_if_current(&self, reason: &str, expected_generation: Option<u64>) {
        let was_armed = {
            let mut inner = self.inner.lock();
            if expected_generation.is_some_and(|generation| generation != inner.fifo_generation) {
                return;
            }
            let armed = inner.fifo.as_ref().is_some_and(|ids| !ids.is_empty());
            Self::qp_retire_fifo_session_locked(&mut inner);
            inner.fifo_generation = inner.fifo_generation.wrapping_add(1);
            inner.fifo = None;
            inner.fifo_total = 0;
            inner.fifo_last_activity = None;
            armed
        };
        if was_armed {
            let message = match reason {
                "new-copy" => "连续粘贴已取消（有新复制）",
                "timeout" => "连续粘贴已取消（超时）",
                "host-window" => "连续粘贴已取消",
                _ => "连续粘贴已取消",
            };
            self.show_overlay_toast(
                message,
                "warning",
                Some("连续粘贴"),
                Some(2200),
                "bottom-center",
                None,
            );
        }
    }

    pub fn fifo_status(&self) -> Value {
        self.compact_fifo();
        let (store, ids, total) = {
            let inner = self.inner.lock();
            (inner.store.clone(), inner.fifo.clone().unwrap_or_default(), inner.fifo_total)
        };
        let next_id = ids.first().cloned();
        let next_summary = next_id.as_ref().and_then(|id| {
            store.lock().get_clip(id).ok().and_then(|item| {
                let dto = clip_to_dto(&item, None);
                crate::fifo::hud_preview_text(&dto.summary, &dto.display_text, &dto.title)
            })
        });
        json!({
            "armed": !ids.is_empty(),
            "ids": ids,
            "remainingIds": ids,
            "remainingCount": ids.len(),
            "totalCount": total,
            "nextId": next_id,
            "nextSummary": next_summary,
        })
    }

    fn compact_fifo(&self) {
        let (store, ids, generation) = {
            let inner = self.inner.lock();
            let Some(ids) = inner.fifo.clone() else { return; };
            (inner.store.clone(), ids, inner.fifo_generation)
        };
        let kept: Vec<String> = {
            let db = store.lock();
            let mut kept = Vec::new();
            for id in &ids {
                match db.get_clip(id) {
                    Ok(_) => kept.push(id.clone()),
                    Err(StoreError::NotFound(_)) => {},
                    // A temporarily unavailable database does not mean the item
                    // was deleted. Leave the queue intact for the next attempt.
                    Err(_) => return,
                }
            }
            kept
        };
        let completed = {
            let mut inner = self.inner.lock();
            // A cancel/rearm changes the generation; a paste changes the head.
            // Neither may be overwritten by an older database snapshot.
            if inner.fifo_generation != generation || inner.fifo.as_ref() != Some(&ids) {
                return;
            }
            if kept.is_empty() {
                let had_total = inner.fifo_total > 0;
                inner.fifo = None;
                inner.fifo_total = 0;
                inner.fifo_last_activity = None;
                had_total
            } else {
                inner.fifo = Some(kept);
                false
            }
        };
        if completed {
            self.fifo_show_complete_toast();
        }
    }

    /// A successful paste consumes only the matching head of the same armed queue.
    fn fifo_mark_pasted(&self, id: &str, generation: u64) -> bool {
        let remaining = {
            let mut inner = self.inner.lock();
            if inner.fifo_generation != generation
                || inner.fifo.as_ref().and_then(|ids| ids.first()).map(String::as_str) != Some(id)
            {
                return false;
            }
            if let Some(ids) = inner.fifo.as_mut() {
                ids.remove(0);
                if ids.is_empty() {
                    inner.fifo = None;
                    inner.fifo_total = 0;
                    inner.fifo_last_activity = None;
                } else {
                    inner.fifo_last_activity = Some(Instant::now());
                }
            }
            inner.fifo.as_ref().map(|ids| ids.len()).unwrap_or(0)
        };
        if remaining == 0 {
            self.fifo_show_complete_toast();
        } else {
            self.fifo_show_armed_hud();
        }
        true
    }

    pub fn favorite_from_clip(&self, params: &Value) -> Result<Value, String> {
        // C# `FavoriteById` / `TryAddFromClipboardItem`: clone + Favorite() + Title + SourceProcessName.
        let id = req_id(params)?;
        let (store, library) = {
            let inner = self.inner.lock();
            (inner.store.clone(), inner.paths.image_library.clone())
        };
        let mut clip = store.lock().get_clip(&id).map_err(item_not_found)?;
        let source_revision = clip.storage_revision.clone();
        apply_favorite_to_clip(&mut clip, &library)?;
        let favor = FavorRecord::from_clip(&clip, None);
        self.store().lock()
            .insert_favor_from_source(&favor, "clip_item", &id, source_revision.as_deref())
            .map_err(|e| e.to_string())?;
        self.emit_favorites_changed(&[favor.id.clone()], &[]);
        Ok(json!({ "ok": true }))
    }

    pub fn favor_tree(&self) -> Result<Value, String> {
        let _operation = self.settings_operation.lock();
        let (store, paths, mut favor) = {
            let inner = self.inner.lock();
            (inner.store.clone(), inner.paths.clone(), inner.extras.favor.clone())
        };
        let db = store.lock();
        if db.document_recovery_status().map_err(|e| e.to_string())?["readOnly"] != true {
            favorites_drag::recover_pending(&db, &paths, &mut favor)?;
        }
        let favor: crate::extra_settings::FavorSettings = crate::config_compat::load(&paths.configs.join("FavorConfig.json"))?;
        let root_order = favor.root_children;
        let items = db.list_favors().map_err(|e| e.to_string())?;
        drop(db);
        let drag_revision = favorites_drag::snapshot_revision(&items, &root_order)?;
        // Keep the existing Bridge roots/rows unchanged. Native tree views also
        // need ordered, possibly shared Children edges; ParentId alone loses
        // those occurrences. This projection never repairs stored relationships.
        let mut root_items: Vec<String> = items
            .iter()
            .filter(|i| i.parent_id.as_ref().map(|p| p.is_empty()).unwrap_or(true))
            .map(|i| i.id.clone())
            .collect();
        root_items.sort();
        let children_by_id = crate::panel::effective_children(&items);
        // Older rows may have only ParentId. Append these missing edges after
        // raw Children in stable order, retaining explicit/shared/missing/cycle
        // references exactly as read. Every row has an authoritative adjacency.
        let mut fallback: Vec<_> = items.iter().collect();
        fallback.sort_by(|a, b| {
            a.sub_index
                .cmp(&b.sub_index)
                .then(a.create_time.cmp(&b.create_time))
                .then(a.id.cmp(&b.id))
        });
        let referenced: HashSet<_> = children_by_id.values().flatten().map(String::as_str).collect();
        let mut ordered_root_items = normalized_root_order(&items, &root_order);
        ordered_root_items.retain(|id| !referenced.contains(id.as_str()));
        for item in fallback {
            if item.parent_id.as_ref().is_none_or(String::is_empty)
                && !referenced.contains(item.id.as_str())
                && !ordered_root_items.contains(&item.id)
            {
                ordered_root_items.push(item.id.clone());
            }
        }
        let mut child_counts: HashMap<&str, i32> = HashMap::new();
        for parent in items.iter().filter_map(|item| item.parent_id.as_deref()) {
            *child_counts.entry(parent).or_default() += 1;
        }
        let map: serde_json::Map<String, Value> = items
            .iter()
            .map(|item| {
                // ParentId child count, computed in one pass.
                let count = child_counts.get(item.id.as_str()).copied().unwrap_or(0);
                (
                    item.id.clone(),
                    serde_json::to_value(favor_to_list_dto(item, count)).unwrap(),
                )
            })
            .collect();
        Ok(json!({
            "rootItems": root_items,
            "items": map,
            "orderedRootItems": ordered_root_items,
            "childrenById": children_by_id,
            "dragRevision": drag_revision,
        }))
    }

    pub fn favor_search(&self, params: &Value) -> Result<Value, String> {
        // C# `ClipHostFavoritesFromFavorDataService.Search`: skip<0→0, take<=0→100, take>500→500.
        let query = params
            .get("query")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim()
            .to_string();
        let skip = params.get("skip").and_then(|v| v.as_i64()).unwrap_or(0).max(0) as usize;
        let take_raw = params.get("take").and_then(|v| v.as_i64()).unwrap_or(100);
        let take = if take_raw <= 0 { 100 } else { take_raw.min(500) } as usize;
        let parent_id = params
            .get("parentId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let ids_match = params
            .get("projection")
            .and_then(|v| v.as_str())
            .is_some_and(|p| p.eq_ignore_ascii_case("idsMatch"));
        let items = self.store().lock().list_favors().map_err(|e| e.to_string())?;
        let mut filtered: Vec<FavorRecord> = items
            .into_iter()
            .filter(|i| !i.is_folder)
            .filter(|i| parent_id.as_ref().map(|p| i.parent_id.as_deref() == Some(p)).unwrap_or(true))
            .filter(|i| matches_favor_query(i, &query))
            .collect();
        filtered.sort_by(|a, b| {
            // C# Search: OrderByDescending UpdateTime, ThenByDescending CreateTime, ThenBy SubIndex.
            b.update_time
                .cmp(&a.update_time)
                .then_with(|| b.create_time.cmp(&a.create_time))
                .then_with(|| a.sub_index.cmp(&b.sub_index))
        });
        let total = filtered.len() as i32;
        let page: Vec<FavorRecord> = filtered.into_iter().skip(skip).take(take).collect();
        let next_skip = skip + page.len();
        if ids_match {
            return Ok(json!({
                "items": [],
                "hits": page.iter().map(|i| json!({ "id": i.id })).collect::<Vec<_>>(),
                "total": total,
                "skip": skip as i32,
                "take": take as i32,
                "hasMore": (next_skip as i32) < total,
                "nextSkip": next_skip as i32,
            }));
        }
        Ok(json!({
            "items": page.iter().map(favor_to_dto).collect::<Vec<_>>(),
            "hits": [],
            "total": total,
            "skip": skip as i32,
            "take": take as i32,
            "hasMore": (next_skip as i32) < total,
            "nextSkip": next_skip as i32,
        }))
    }

    pub fn favor_get(&self, params: &Value) -> Result<Value, String> {
        let id = req_id(params)?;
        let item = self.store().lock()
            .get_favor(&id)
            .map_err(favorite_not_found)?;
        Ok(favor_to_detail(&item))
    }

    pub fn favor_get_by_ids(&self, params: &Value) -> Result<Value, String> {
        // C# `GetListByIds`: skip missing, OrderBy first-occurrence index (stable → cluster dupes).
        if params.is_null() {
            return Err("Request body is required.".into());
        }
        let ids = param_ids(params);
        let store = self.store();
        let db = store.lock();
        let mut first_index = HashMap::new();
        for (i, id) in ids.iter().enumerate() {
            first_index.entry(id.clone()).or_insert(i);
        }
        let mut items: Vec<(usize, usize, FavorRecord)> = ids
            .iter()
            .enumerate()
            .filter_map(|(orig, id)| {
                let item = db.get_favor(id).ok()?;
                let idx = *first_index.get(&item.id)?;
                Some((idx, orig, item))
            })
            .collect();
        items.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
        let dtos: Vec<_> = items.into_iter().map(|(_, _, item)| favor_to_dto(&item)).collect();
        Ok(serde_json::to_value(dtos).unwrap_or(json!([])))
    }

    pub fn favor_copy(&self, params: &Value) -> Result<Value, String> {
        let id = req_id(params)?;
        let item = self.store().lock()
            .get_favor(&id)
            .map_err(item_not_found)?;
        let clip = favor_as_clip(&item).map_err(|_| "Item not found.".to_string())?;
        let clip = self.project_output_clip(&clip)?;
        let opts = paste_options_from_config(&self.inner.lock().config);
        self.run_clipboard_write(move || crate::paste::prepare_copy_record(&clip, &opts))?;
        Ok(json!({ "ok": true }))
    }

    pub fn favor_paste(&self, params: &Value) -> Result<Value, String> {
        let id = req_id(params)?;
        let item = self.store().lock()
            .get_favor(&id)
            .map_err(item_not_found)?;
        let clip = favor_as_clip(&item).map_err(|_| "Item not found.".to_string())?;
        let clip = self.project_output_clip(&clip)?;
        let mut opts = paste_options_from_config(&self.inner.lock().config);
        opts.expected_target = Some(self.prepare_window_for_paste_from(self.resolve_paste_sender(params))?);
        let copy_opts = opts.clone();
        self.paste_via_clipboard(opts, move || crate::paste::prepare_copy_record(&clip, &copy_opts))?;
        Ok(json!({ "ok": true }))
    }

    /// Native favorites in the clipboard window retain the target and input
    /// lifecycle accepted by the UI, including a second check after DB reads.
    pub fn favor_paste_native(&self, params: &Value, request: &NativePasteRequest) -> Result<Value, String> {
        self.favor_paste_native_for_foreground(params, request, native_paste_foreground)
    }

    fn favor_paste_native_for_foreground(&self, params: &Value, request: &NativePasteRequest,
        mut foreground: impl FnMut() -> isize) -> Result<Value, String> {
        self.verify_native_paste_request(request, foreground())?;
        let id = req_id(params)?;
        let (store, mut opts) = {
            let inner = self.inner.lock();
            (inner.store.clone(), paste_options_from_config(&inner.config))
        };
        let item = store.lock().get_favor(&id).map_err(item_not_found)?;
        let clip = favor_as_clip(&item).map_err(|_| "Item not found.".to_string())?;
        let clip = self.project_output_clip(&clip)?;
        self.verify_native_paste_request(request, foreground())?;
        opts.expected_target = Some(request.target);
        self.qp_tuck_host_for_paste();
        let target = request.target;
        self.run_input(move || target.activate_for_paste())?;
        let copy_opts = opts.clone();
        self.paste_via_clipboard(opts, move || crate::paste::prepare_copy_record(&clip, &copy_opts))?;
        Ok(json!({ "ok": true }))
    }

    pub fn favor_delete(&self, params: &Value) -> Result<Value, String> {
        let id = req_id(params)?;
        if self.delete_favor_ids(&[id.clone()])?.is_empty() {
            return Err("Item not found.".into());
        }
        self.emit_favorites_changed(&[], &[id]);
        Ok(json!({ "ok": true }))
    }

    /// Remove one broken `Children` edge from one folder. Refuses an existing
    /// child, so it can never detach a real item (tree views list such edges
    /// as "missing favorite reference" and never repair them on their own).
    pub fn favor_remove_missing_reference(&self, params: &Value) -> Result<Value, String> {
        self.require_writable_document_view()?;
        let text = |key: &str| {
            params
                .get(key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned)
                .ok_or_else(|| format!("Missing {key}."))
        };
        let (parent_id, child_id) = (text("parentId")?, text("childId")?);
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        match db.get_favor(&child_id) {
            Ok(_) => return Err("The favorite still exists; it is not a missing reference.".into()),
            Err(StoreError::NotFound(_)) => {}
            Err(error) => return Err(error.to_string()),
        }
        let mut folder = db.get_favor(&parent_id).map_err(favorite_not_found)?;
        let before = folder.children.len();
        folder.children.retain(|child| child != &child_id);
        if folder.children.len() == before {
            return Ok(json!({ "ok": true, "removed": false }));
        }
        db.save_favor(&folder).map_err(|e| e.to_string())?;
        drop(db);
        self.emit_favorites_changed(&[parent_id], &[]);
        Ok(json!({ "ok": true, "removed": true }))
    }

    pub fn favor_update(&self, params: &Value) -> Result<Value, String> {
        let id = req_id(params)?;
        let library = self.inner.lock().paths.image_library.clone();
        let store = self.inner.lock().store.clone();
        let prepared_qq = if let Some(raw) = params.get("qqRichText").and_then(Value::as_str) {
            let item = store.lock().get_favor(&id).map_err(favorite_not_found)?;
            validate_edit_revision(params, &item, item.storage_revision.as_deref())?;
            (!item.is_folder && item.kind == ClipKind::QQRichTextItem)
                .then(|| prepare_qq_update(&item.source_process_name, raw, &library,
                    item.storage_revision.as_deref().is_some_and(|r| r.starts_with("core2:"))))
                .transpose()?
        } else { None };
        let db = store.lock();
        let mut item = db.get_favor(&id).map_err(favorite_not_found)?;
        // The SPA exposes folder rename through this method. C# currently
        // rejects that path; keep the existing dialog usable in the Rust host.
        let is_folder = item.is_folder || item.kind == ClipKind::FavoriteClipItem;
        validate_edit_revision(params, &item, item.storage_revision.as_deref())?;
        if let Some(name) = params
            .get("title")
            .or_else(|| params.get("name"))
            .and_then(|v| if v.is_null() { None } else { v.as_str() })
        {
            // C# `ApplyUpdate`: whitespace Title becomes null.
            item.name = if name.trim().is_empty() {
                String::new()
            } else {
                name.trim().to_string()
            };
        }
        if !is_folder {
            let body = params
                .get("bodyText")
                .or_else(|| params.get("content"))
                .and_then(|v| v.as_str());
            if let Some(body) = body {
                if is_text_clip_item(item.kind) {
                    item.body_text = Some(body.to_string());
                }
            }
            if is_html_clip_item(item.kind) {
                apply_html_update(
                    &mut item.html_data,
                    &mut item.html_source_url,
                    params.get("htmlData").and_then(|v| v.as_str()),
                    params.get("htmlSourceUrl").and_then(|v| v.as_str()),
                );
            }
            if item.kind == ClipKind::QQRichTextItem {
                if let Some(prepared) = prepared_qq {
                    prepared.apply(&mut item.qq_rich_text, &mut item.body_text);
                }
            }
            if let Some(paths) = params.get("filePaths").and_then(|v| v.as_array()) {
                if item.kind == ClipKind::FileClipItem {
                    item.file_paths = paths
                        .iter()
                        .filter_map(|v| v.as_str().map(str::trim).filter(|s| !s.is_empty()).map(|s| s.to_string()))
                        .collect();
                }
            }
            if let Some(step) = params.get("stepData").and_then(|v| v.as_str()) {
                if item.kind == ClipKind::StepClipItem {
                    item.body_text = Some(step.to_string());
                }
            }
            if let Some(command) = params.get("command").and_then(|v| v.as_str()) {
                if item.kind == ClipKind::CmdClipItem {
                    item.body_text = Some(command.to_string());
                }
            }
            if item.kind == ClipKind::ActionClipItem {
                if let Some(p) = params.get("executeParam").and_then(|v| v.as_str()) {
                    item.execute_param = p.to_string();
                }
            }
            if item.kind == ClipKind::LinkClipItem {
                if let Some(url) = params.get("linkUrl").and_then(|v| v.as_str()) {
                    item.body_text = Some(url.trim().to_string());
                }
                if let Some(title) = params.get("linkTitle").and_then(|v| v.as_str()) {
                    item.name = title.trim().to_string();
                }
            }
        }
        item.update_time = Utc::now();
        let title_value = if item.kind == ClipKind::LinkClipItem {
            params.get("linkTitle").or_else(|| params.get("title")).or_else(|| params.get("name"))
        } else {
            params.get("title").or_else(|| params.get("name"))
        };
        let title_override = if item.storage_revision.as_deref().is_some_and(|r| r.starts_with("core2:")) {
            submitted_title_override(title_value, true)?
        } else { None };
        db.save_favor_edit(&item, title_override).map_err(|e| e.to_string())?;
        // SQLite stores favorite timestamps in milliseconds; hashing the in-memory
        // nanoseconds would make the next save conflict with its own previous write.
        let item = db.get_favor(&id).map_err(|e| e.to_string())?;
        drop(db);
        self.emit_favorites_changed(&[item.id.clone()], &[]);
        Ok(favor_to_detail(&item))
    }

    pub fn favor_folder_create(&self, params: &Value) -> Result<Value, String> {
        let name = params
            .get("title")
            .or_else(|| params.get("name"))
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .unwrap_or("")
            .to_string();
        let parent_raw = params
            .get("parentId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        // C# `AddFavoriteFolder`: empty/`root` → top-level; else `TryResolveFavoriteParent`.
        let parent = match parent_raw {
            None => None,
            Some(raw) if raw.eq_ignore_ascii_case(crate::panel::ROOT_FOLDER_ID) => None,
            Some(raw) => self.resolve_optional_favor_parent(Some(raw))?,
        };
        let favor = FavorRecord {
            storage_revision: None,
            id: Uuid::new_v4().simple().to_string(),
            parent_id: parent,
            is_folder: true,
            name,
            kind: ClipKind::FavoriteClipItem,
            body_text: None,
            file_paths: Vec::new(),
            image_path: None,
            children: Vec::new(),
            create_time: Utc::now(),
            update_time: Utc::now(),
            source_clip_id: None,
            html_data: None,
            html_source_url: None,
            qq_rich_text: None,
            source_process_name: String::new(),
            sub_index: 0,
            icon: String::new(),
            execute_param: String::new(),
        };
        let store = self.inner.lock().store.clone();
        store.lock().insert_favor_checked_at(&favor, favor_insert_index_from_params(params)).map_err(|e| e.to_string())?;
        if favor.parent_id.is_none() {
            let favors = self.store().lock().list_favors().map_err(|e| e.to_string())?;
            self.ensure_root_children_order(&favors);
        }
        self.emit_favorites_changed(&[favor.id.clone()], &[]);
        // C# `HandleFavorFolderCreate` returns `BuildDetail`.
        Ok(favor_to_detail(&favor))
    }

    pub fn favor_add_paths(&self, params: &Value) -> Result<Value, String> {
        let paths = params
            .get("paths")
            .and_then(|v| v.as_array())
            .map(|a| a.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect::<Vec<_>>())
            .unwrap_or_default();
        let parent = params
            .get("parentId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let parent_id = self.resolve_optional_favor_parent(parent)?;
        let insert_index = favor_insert_index_from_params(params);
        let mut seen = HashSet::new();
        let mut created = Vec::new();
        for path in paths {
            if created.len() >= 50 {
                break;
            }
            let path = path.trim();
            if path.is_empty() {
                continue;
            }
            let key = path.to_ascii_lowercase();
            if !seen.insert(key) {
                continue;
            }
            // C# `CreateAutoFromPath`: existing file/dir → `FileClipItem.FromPath`, else `TextClipItem`.
            let favor = favor_from_path(path, parent_id.clone());
            created.push(favor);
        }
        self.insert_favors_indexed(&created, insert_index)?;
        Ok(json!({
            "ok": !created.is_empty(),
            "count": created.len(),
            "createdIds": created.iter().map(|item| &item.id).collect::<Vec<_>>()
        }))
    }

    pub fn favor_add_text_items(&self, params: &Value) -> Result<Value, String> {
        let parent = params
            .get("parentId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let parent_id = self.resolve_optional_favor_parent(parent)?;
        let texts = favor_add_text_payload(params);
        let insert_index = favor_insert_index_from_params(params);
        let mut created = Vec::new();
        for text in texts {
            let favor = FavorRecord {
                storage_revision: None,
                id: Uuid::new_v4().simple().to_string(),
                parent_id: parent_id.clone(),
                is_folder: false,
                name: text.chars().take(40).collect(),
                kind: ClipKind::TextClipItem,
                body_text: Some(text),
                file_paths: Vec::new(),
                image_path: None,
                children: Vec::new(),
                create_time: Utc::now(),
                update_time: Utc::now(),
                source_clip_id: None,
            html_data: None,
            html_source_url: None,
            qq_rich_text: None,
            source_process_name: String::new(),
            sub_index: 0,
            icon: String::new(),
            execute_param: String::new(),
            };
            created.push(favor);
        }
        self.insert_favors_indexed(&created, insert_index)?;
        Ok(json!({ "ok": !created.is_empty(), "count": created.len(), "createdIds": created.iter().map(|item| &item.id).collect::<Vec<_>>() }))
    }

    pub fn favor_add_link(&self, params: &Value) -> Result<Value, String> {
        let parent = params
            .get("parentId")
            .or_else(|| params.get("favorId"))
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let parent_id = self.resolve_optional_favor_parent(parent)?;
        let url = params
            .get("url")
            .or_else(|| params.get("href"))
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let tab = match url {
            Some(url) => crate::browser::BrowserTab::from_rpc(&json!({
                "url": url, "title": params.get("title"), "icon": params.get("icon")
            })).unwrap(),
            None => {
                let value = self.quicker_browser_call("quicker.getCurrentBrowserTab")?;
                crate::browser::BrowserTab::from_rpc(&value)
                    .ok_or_else(|| crate::browser::UNAVAILABLE.to_string())?
            }
        };
        // The folder may have been removed while the extension was responding.
        self.resolve_optional_favor_parent(parent_id.as_deref())?;
        let favor = FavorRecord {
            storage_revision: None,
            id: Uuid::new_v4().simple().to_string(),
            parent_id,
            is_folder: false,
            name: tab.title,
            kind: ClipKind::LinkClipItem,
            body_text: Some(tab.url),
            file_paths: Vec::new(),
            image_path: None,
            children: Vec::new(),
            create_time: Utc::now(),
            update_time: Utc::now(),
            source_clip_id: None,
            html_data: None,
            html_source_url: None,
            qq_rich_text: None,
            source_process_name: String::new(),
            sub_index: 0,
            icon: tab.icon,
            execute_param: String::new(),
        };
        let mut insert_index = favor_insert_index_from_params(params);
        self.insert_favor_indexed(&favor, &mut insert_index)?;
        // C# `HandleFavorLinkAddAsync` returns `BuildDetail` (`GetType().Name`).
        Ok(favor_to_detail(&favor))
    }

    pub fn favor_clipboard_options(&self) -> Value {
        self.favor_clipboard_options_with_snapshot(peek_snapshot)
    }

    fn favor_clipboard_options_with_snapshot(
        &self,
        reader: impl FnOnce() -> Option<ClipboardSnapshot>,
    ) -> Value {
        // Opening a paste-options menu must not read the user's clipboard in
        // an isolated core copy, even though this native process is not headless.
        if self.require_external_effects("inspect system clipboard options").is_err() {
            return favor_clipboard_options_from(&ClipboardSnapshot::default());
        }
        favor_clipboard_options_from(&reader().unwrap_or_default())
    }

    pub fn favor_from_clipboard(&self, params: &Value) -> Result<Value, String> {
        self.require_external_effects("collect the system clipboard")?;
        self.favor_from_snapshot(params, peek_snapshot().unwrap_or_default())
    }

    fn favor_from_snapshot(&self, params: &Value, snap: ClipboardSnapshot) -> Result<Value, String> {
        let parent = params
            .get("parentId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let key = params
            .get("optionKey")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim()
            .to_ascii_lowercase();
        let parent_id = self.resolve_optional_favor_parent(parent)?;
        let mut insert_index = favor_insert_index_from_params(params);
        let any_key = key.is_empty();

        if any_key || key == "action" {
            if let Some(action) = snap.quicker_action.as_deref().filter(|s| !s.is_empty()) {
                let title = action_clipboard_title(action);
                let favor = FavorRecord {
                    storage_revision: None,
                    id: Uuid::new_v4().simple().to_string(),
                    parent_id: parent_id.clone(),
                    is_folder: false,
                    name: if title.is_empty() { "动作".into() } else { title },
                    kind: ClipKind::ActionClipItem,
                    body_text: Some(action.to_string()),
                    file_paths: Vec::new(),
                    image_path: None,
                    children: Vec::new(),
                    create_time: Utc::now(),
                    update_time: Utc::now(),
                    source_clip_id: None,
            html_data: None,
            html_source_url: None,
            qq_rich_text: None,
            source_process_name: String::new(),
            sub_index: 0,
            icon: String::new(),
            execute_param: String::new(),
                };
                self.insert_favor_indexed(&favor, &mut insert_index)?;
                return Ok(json!({ "ok": true, "count": 1 }));
            }
            if !any_key {
                return Ok(json!({ "ok": false, "count": 0 }));
            }
        }

        if any_key || key == "files" {
            if !snap.files.is_empty() {
                let favors: Vec<_> = snap.files.iter().take(50)
                    .map(|path| favor_from_path(path, parent_id.clone())).collect();
                self.insert_favors_indexed(&favors, insert_index)?;
                let count = favors.len();
                return Ok(json!({ "ok": count > 0, "count": count }));
            }
            if !any_key {
                return Ok(json!({ "ok": false, "count": 0 }));
            }
        }

        if any_key || key == "text" {
            if let Some(text) = snap.text.as_deref().map(str::trim).filter(|s| !s.is_empty()) {
                if text.len() < 10 * 1024 {
                    let favor = FavorRecord {
                        storage_revision: None,
                        id: Uuid::new_v4().simple().to_string(),
                        parent_id: parent_id.clone(),
                        is_folder: false,
                        name: text.chars().take(40).collect(),
                        kind: ClipKind::TextClipItem,
                        body_text: Some(text.to_string()),
                        file_paths: Vec::new(),
                        image_path: None,
                        children: Vec::new(),
                        create_time: Utc::now(),
                        update_time: Utc::now(),
                        source_clip_id: None,
            html_data: None,
            html_source_url: None,
            qq_rich_text: None,
            source_process_name: String::new(),
            sub_index: 0,
            icon: String::new(),
            execute_param: String::new(),
                    };
                    self.insert_favor_indexed(&favor, &mut insert_index)?;
                    return Ok(json!({ "ok": true, "count": 1 }));
                }
            }
            if !any_key {
                return Ok(json!({ "ok": false, "count": 0 }));
            }
        }

        if any_key {
            let (data_root, ignore_ws, collect_quicker, expression) = {
                let inner = self.inner.lock();
                (
                    inner.paths.data_root.clone(),
                    inner.ignore_ws.load(Ordering::Relaxed),
                    inner.collect_quicker.load(Ordering::Relaxed),
                    inner.config.text_process_expression.clone(),
                )
            };
            if let Some(clip) = crate::clipboard::item_from_snapshot_with_transform(
                snap,
                &data_root,
                "",
                ignore_ws,
                collect_quicker,
                &expression,
                &|text, expression| crate::quicker_expression::transform_capture(&self.quicker_rpc, text, expression),
            ) {
                let favor = FavorRecord::from_clip(&clip, parent_id);
                self.insert_favor_indexed(&favor, &mut insert_index)?;
                return Ok(json!({ "ok": true, "count": 1 }));
            }
        }

        Ok(json!({ "ok": false, "count": 0 }))
    }

    fn resolve_optional_favor_parent(&self, parent: Option<&str>) -> Result<Option<String>, String> {
        let Some(raw) = parent.map(str::trim).filter(|s| !s.is_empty()) else {
            return Ok(None);
        };
        if raw.eq_ignore_ascii_case(crate::panel::ROOT_FOLDER_ID) {
            return Err("Use AddFavoriteFolder with root parent for top-level panels.".into());
        }
        if raw == crate::panel::DETACHED_ORPHANS_FOLDER_ID {
            return Ok(None);
        }
        let store = self.inner.lock().store.clone();
        let folder = store.lock().get_favor(raw).ok();
        if folder.as_ref().is_some_and(|f| f.is_folder) {
            Ok(Some(raw.to_string()))
        } else {
            Err(format!("Favorite folder not found: {raw}"))
        }
    }

    pub fn favor_batch_delete(&self, params: &Value) -> Result<Value, String> {
        let ids = param_ids(params);
        let removed = self.delete_favor_ids(&ids)?;
        if !removed.is_empty() {
            self.emit_favorites_changed(&[], &removed);
        }
        Ok(json!({ "ok": true, "count": removed.len() }))
    }

    /// C# `TryDeleteCore`: missing item or `GetFirstFavorites()` → false (`RequireItemFound` → `Item not found.`).
    fn delete_favor_ids(&self, ids: &[String]) -> Result<Vec<String>, String> {
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        let items = db.list_favors().map_err(|e| e.to_string())?;
        let protected = crate::favor_menu::first_favorites(&items).map(|root| root.id.as_str());
        let eligible = ids.iter().filter(|id| Some(id.as_str()) != protected).cloned().collect::<Vec<_>>();
        db.delete_favors(&eligible).map_err(|e| e.to_string())
    }

    pub fn favor_add_text(&self, params: &Value) -> Result<Value, String> {
        // C# `HandleFavorAddText` inserts clipboard history via `AddClipText`.
        self.add_text(params)
    }

    pub fn settings_catalog(&self) -> Value {
        settings_form::catalog()
    }

    pub fn settings_form_get(&self, params: &Value) -> Result<Value, String> {
        let id = req_config_id(params)?;
        let root = if id == "dataLocation" {
            let location = self.inner.lock().data_location.clone();
            location.override_path()?.map(|p| p.display().to_string()).unwrap_or_default()
        } else { String::new() };
        let inner = self.inner.lock();
        Ok(settings_form::build_form(
            &id,
            &inner.config,
            &inner.qp_config,
            &inner.hotkeys,
            &root,
            &inner.extras,
            &inner.filters,
        ))
    }

    pub fn settings_form_update(&self, params: &Value) -> Result<Value, String> {
        let _operation = self.settings_operation.lock();
        let id = req_config_id(params)?;
        let values = params.get("values").cloned().unwrap_or(Value::Null);
        let mut hotkey_changed: Vec<String> = Vec::new();
        let mut location_result = None;
        let mut restart_request = None;
        match id.as_str() {
            "clip" => {
                let filters = values.get("FilterItems").map(crate::clip_filter::parse_form_value);
                let files = filters.as_ref().map(|filters| vec![(self.inner.lock().paths.configs.join("ClipFilterConfig.json"), json!({ "FilterItems": filters, "RustUrlFilterDefaultAdded": true }))]).unwrap_or_default();
                self.apply_clip_config_with_files(&values, ClipConfigApply::Settings, files)?;
                if let Some(filters) = filters { self.inner.lock().filters = filters; }
            }
            "global" | "homeGlobal" => {
                let previous_run_as = self.inner.lock().extras.global.run_as_administrator;
                let mut extras = self.inner.lock().extras.clone();
                crate::extra_settings::apply_global(&mut extras.global, &values);
                {
                    let current = self.inner.lock().extras.global.clone();
                    if extras.global.launch_at_startup != current.launch_at_startup
                        || extras.global.run_as_administrator != current.run_as_administrator {
                        self.require_external_effects("change sign-in or elevation integration")?;
                    }
                }
                let paths = self.inner.lock().paths.clone();
                let mut cfg = self.inner.lock().config.clone();
                crate::extra_settings::sync_clip_from_global(&mut cfg, &extras.global);
                crate::config_file::save_values(&[
                    (paths.configs.join("GlobalConfig.json"), serde_json::to_value(&extras.global).map_err(|e| e.to_string())?),
                    (paths.configs.join("ClipConfig.json"), persisted_clip_config(&cfg)?),
                ])?;
                let launch = extras.global.launch_at_startup;
                let next_run_as = extras.global.run_as_administrator;
                let hwnd = self.inner.lock().host_hwnd;
                let config_event = {
                    let mut inner = self.inner.lock();
                    cfg.clip_monitor_on = inner.config.clip_monitor_on;
                    let event = serde_json::to_value(&cfg).map_err(|e| e.to_string())?;
                    inner.config = cfg;
                    inner.extras.global = extras.global;
                    event
                };
                self.push_event("clipConfigChanged", config_event);
                if self.require_external_effects("update sign-in registration").is_ok() {
                    crate::startup::apply(launch);
                }
                // C# `ClipHostRunAsAdministratorRestartUi` after persist (global + homeGlobal).
                restart_request = if self.require_external_effects("update elevation integration").is_ok() { crate::elevation::try_prompt_after_persisted_run_as_administrator(
                    previous_run_as,
                    next_run_as,
                    hwnd,
                ) } else { None };
            }
            "quickPaste" | "trigger" => {
                let (prev_hotkeys, prev_win_v) = {
                    let inner = self.inner.lock();
                    (inner.hotkeys.clone(), inner.config.use_win_v_shortcut)
                };
                let mut qp = self.inner.lock().qp_config.clone();
                let mut hotkeys = prev_hotkeys.clone();
                settings_form::apply_quick_paste(&mut qp, &values);
                settings_form::apply_hotkeys(&mut hotkeys, &values);
                let paths = self.inner.lock().paths.clone();
                let mut files = vec![
                    (paths.configs.join("QuickPasteConfig.json"), serde_json::to_value(&qp).map_err(|e| e.to_string())?),
                    (paths.configs.join("GlobalHotkeys.json"), serde_json::to_value(&hotkeys).map_err(|e| e.to_string())?),
                ];
                if paths.configs.join("GlobalConfig.json").exists() {
                    // C# stores these in GlobalConfig, not the Rust-only sidecar.
                    files.push((paths.configs.join("GlobalConfig.json"), json!({
                        "HotkeyClipToggle": hotkeys.hotkey_show_clipboard,
                        "HotkeyFavorToggle": hotkeys.hotkey_favor_toggle,
                        "HotkeyQuickPaste": hotkeys.hotkey_quick_paste,
                        "HotkeySuperMenu": hotkeys.hotkey_super_menu,
                    })));
                }
                if id == "trigger" {
                    self.apply_clip_config_with_files(&values, ClipConfigApply::Settings, files)?;
                } else {
                    crate::config_file::save_values(&files)?;
                }
                self.inner.lock().qp_config = qp;
                self.inner.lock().hotkeys = hotkeys.clone();
                self.refresh_global_hotkeys();
                let next_win_v = self.inner.lock().config.use_win_v_shortcut;
                hotkey_changed = crate::global_hotkey::changed_config_keys(
                    &prev_hotkeys.hotkey_show_clipboard,
                    &hotkeys.hotkey_show_clipboard,
                    &prev_hotkeys.hotkey_favor_toggle,
                    &hotkeys.hotkey_favor_toggle,
                    &prev_hotkeys.hotkey_quick_paste,
                    &hotkeys.hotkey_quick_paste,
                    &prev_hotkeys.hotkey_super_menu,
                    &hotkeys.hotkey_super_menu,
                    prev_win_v,
                    next_win_v,
                    &id,
                );
            }
            "panel" => {
                let mut extras = self.inner.lock().extras.clone();
                crate::extra_settings::apply_panel(&mut extras.panel, &values);
                let path = self.inner.lock().paths.configs.join("PanelConfig.json");
                save_json(&path, &extras.panel)?;
                self.inner.lock().extras.panel = extras.panel;
                self.enqueue_chrome(ChromeCommand::PanelRefresh);
            }
            "user" => {
                let mut extras = self.inner.lock().extras.clone();
                crate::extra_settings::apply_user(&mut extras.user, &values);
                let path = self.inner.lock().paths.configs.join("UserConfig.json");
                save_json(&path, &extras.user)?;
                let mut inner = self.inner.lock();
                inner.save_reopen.store(extras.user.save_re_open_history, Ordering::Relaxed);
                inner.reopen_history_limit.store(extras.user.re_open_history_limit as usize, Ordering::Relaxed);
                inner.extras.user = extras.user;
            }
            "menu_global" => {
                let mut extras = self.inner.lock().extras.clone();
                crate::extra_settings::apply_menu_global(&mut extras.menu_global, &values);
                let path = self.inner.lock().paths.configs.join("GlobalMenuConfig.json");
                save_json(&path, &extras.menu_global)?;
                self.inner.lock().extras.menu_global = extras.menu_global;
            }
            "menu_file" => {
                self.file_menu_update_saving(|paths, settings| {
                    crate::extra_settings::apply_file_menu(settings, &values);
                    paths.replace_all(settings.files.lines().map(str::to_string).collect());
                }, crate::file_menu::save_config)?;
            }
            "dataLocation" => {
                self.require_external_effects("change data location")?;
                let (location, owner, current_root) = {
                    let inner = self.inner.lock();
                    (inner.data_location.clone(), inner.main_hwnd, inner.paths.data_root.clone())
                };
                location_result = Some(location.apply_for_current(&values, Some(&current_root),
                    || crate::data_location::confirm_change(owner),
                    || {
                        let result = self.restart(false);
                        if result["ok"] == true {
                            Ok(result.get("restart").and_then(Value::as_bool).unwrap_or(true))
                        } else {
                            Err(result["error"].as_str().unwrap_or("无法启动新实例。").to_string())
                        }
                    })?);
            }
            _ => {}
        }
        let mut form = self.settings_form_get(&json!({ "configId": id }))?;
        let mut messages: Vec<Value> = Vec::new();
        // C# Win+V uses `ClipHostWinVShortcutRestartUi` MessageBox, not settings form messages.
        if matches!(id.as_str(), "quickPaste" | "trigger") {
            let statuses = self.inner.lock().hotkey_statuses.clone();
            messages.extend(crate::global_hotkey::form_messages(&statuses, &hotkey_changed));
        }
        if let Some(outcome) = location_result {
            let text = match outcome {
                crate::data_location::ApplyResult::Unchanged => tr("数据位置未更改。", "Data location unchanged."),
                crate::data_location::ApplyResult::Cancelled => tr("已取消数据位置更改。", "Data location change canceled."),
                crate::data_location::ApplyResult::Saved { restart_requested: true } => tr("数据位置已保存，正在重启；不会自动迁移已有数据。", "Data location saved; restarting. Existing data is kept in its current folder."),
                crate::data_location::ApplyResult::Saved { restart_requested: false } => tr("数据位置已保存，当前运行环境未执行重启；下次启动生效，不会自动迁移已有数据。", "Data location saved; applies on the next launch. Existing data is kept in its current folder."),
            };
            messages.push(json!({
                "level": "info",
                "text": text,
                "fieldKey": "dataFolder"
            }));
        }
        if !messages.is_empty() {
            form["messages"] = json!(messages);
        }
        drop(_operation);
        // Some independent settings categories do not change ClipConfig. Let
        // retained native forms reread their values after a successful commit,
        // without publishing user values or pretending the history changed.
        if matches!(id.as_str(), "clip" | "global" | "homeGlobal" | "quickPaste" | "trigger" | "panel" | "user" | "menu_global") {
            self.push_event("nativeSettingsChanged", json!({ "configId": id }));
        }
        if let Some(prefer_medium) = restart_request {
            self.restart(prefer_medium);
        }
        Ok(form)
    }

    pub fn process_options(&self, params: &Value) -> Result<Value, String> {
        // C# `ClipSourceProcessCatalogService.SearchSourceProcesses`.
        let needle = params
            .get("q")
            .or_else(|| params.get("query"))
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim()
            .to_string();
        let limit = params.get("limit").and_then(|v| v.as_i64()).unwrap_or(50);
        let limit = if limit <= 0 { 50 } else { limit.min(200) } as usize;
        let all = self.source_process_rows();
        let mut results = Vec::new();
        let mut seen = HashSet::new();
        for row in all {
            let exe = row
                .get("exeName")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string();
            if exe.is_empty() {
                continue;
            }
            if !needle.is_empty() && !contains_ignore_ascii(&exe, &needle) {
                continue;
            }
            if !seen.insert(exe.to_ascii_lowercase()) {
                continue;
            }
            results.push(row);
            if results.len() >= limit {
                return Ok(json!(results));
            }
        }
        if needle.is_empty() {
            return Ok(json!(results));
        }
        const SUGGESTED: &[&str] = &[
            "cmd.exe",
            "conhost.exe",
            "powershell.exe",
            "pwsh.exe",
            "WindowsTerminal.exe",
        ];
        for suggested in SUGGESTED {
            if !contains_ignore_ascii(suggested, &needle) {
                continue;
            }
            let norm = csharp_source_process_name(suggested);
            if !seen.insert(norm.to_ascii_lowercase()) {
                continue;
            }
            results.push(json!({
                "exeName": norm,
                "lastSeen": "0001-01-01T00:00:00",
                "itemCount": 0
            }));
            if results.len() >= limit {
                break;
            }
        }
        Ok(json!(results))
    }

    /// Capture the displayed destination on the UI thread before dispatching drop persistence.
    pub fn panel_quicker_drop_parent(&self) -> Option<String> {
        self.inner.lock().ui.panel_folder_id.clone()
    }

    pub fn panel_drop_quicker_action(&self, payload: &str, parent: Option<&str>) -> Result<String, String> {
        let action = crate::quicker_action::ActionReference::parse(payload)?;
        action.require_id()?;
        let parent = parent.map(str::trim).filter(|s| !s.is_empty());
        if parent.is_some_and(crate::panel::is_root_folder_id) {
            return Err("Use AddFavoriteFolder with root parent for top-level panels.".into());
        }
        let mut clip = ClipRecord::new_text(payload, "");
        clip.kind = ClipKind::ActionClipItem;
        let mut favor = FavorRecord::from_clip(&clip, parent.map(str::to_string));
        favor.source_clip_id = None;
        favor.name = action.title.filter(|s| !s.is_empty()).unwrap_or_else(|| "动作".into());
        let store = self.inner.lock().store.clone();
        store.lock().insert_favor_checked(&favor).map_err(|e| e.to_string())?;
        self.emit_favorites_changed(&[favor.id.clone()], &[]);
        self.enqueue_chrome(ChromeCommand::PanelRefresh);
        Ok(favor.id)
    }

    pub fn panel_catalog(&self) -> Result<Value, String> {
        let items = self.store().lock().list_favors().map_err(|e| e.to_string())?;
        let ordered = self.ensure_root_children_order(&items);
        let user_icon = self.inner.lock().extras.favor.user_icon.clone();
        Ok(crate::panel::catalog(&items, &ordered, &user_icon))
    }

    pub fn panel_layout(&self) -> Result<Value, String> {
        let (store, default_id) = {
            let inner = self.inner.lock();
            (
                inner.store.clone(),
                inner.extras.panel.default_panel_favor_id.clone(),
            )
        };
        let items = store.lock().list_favors().map_err(|e| e.to_string())?;
        let ordered = self.ensure_root_children_order(&items);
        let user_icon = self.inner.lock().extras.favor.user_icon.clone();
        let layout = crate::panel::layout(&items, &ordered, &default_id, &user_icon)
            .ok_or_else(|| "Panel layout not found.".to_string())?;
        self.inner.lock().panel_layout = layout.clone();
        Ok(layout)
    }

    pub fn panel_page(&self, params: &Value) -> Result<Value, String> {
        let favor_id = params
            .get("favorId")
            .or_else(|| params.get("folderId"))
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let folder_id = params.get("folderId").and_then(|v| v.as_str());
        let (store, appearance) = {
            let inner = self.inner.lock();
            (
                inner.store.clone(),
                crate::panel::appearance(&inner.extras.panel),
            )
        };
        let items = store.lock().list_favors().map_err(|e| e.to_string())?;
        let user_icon = self.inner.lock().extras.favor.user_icon.clone();
        crate::panel::page(&items, favor_id, folder_id, appearance, &user_icon)
    }

    pub fn panel_invoke(&self, params: &Value) -> Result<Value, String> {
        let _favor_id = req_str(params, "favorId")?;
        let id = req_str(params, "itemId")?;
        let store = self.inner.lock().store.clone();
        let item = store
            .lock()
            .get_favor(&id)
            .map_err(panel_item_not_found)?;
        let (folder_click, file_click) = {
            let extras = &self.inner.lock().extras.panel;
            (
                extras.folder_default_click_action.clone(),
                extras.file_default_click_action.clone(),
            )
        };
        let source = window_handle_param(
            params,
            &["sourceWindowHandle", "SourceWindowHandle", "sourceHandle"],
        );
        if item.is_folder {
            if panel_click_is_copy(&folder_click) {
                self.favor_copy(&json!({ "id": id }))?;
                return Ok(json!({ "action": "executed", "navigateFolderId": Value::Null }));
            }
            return Ok(json!({ "action": "navigate", "navigateFolderId": item.id }));
        }
        if panel_click_is_copy(&file_click) {
            self.favor_copy(&json!({ "id": id }))?;
            return Ok(json!({ "action": "executed", "navigateFolderId": Value::Null }));
        }
        if panel_click_is_paste(&file_click) {
            self.favor_paste(&json!({ "id": id, "sourceHandle": source }))?;
            return Ok(json!({ "action": "executed", "navigateFolderId": Value::Null }));
        }
        self.favor_execute_menu_item(&id, 0, source)?;
        Ok(json!({ "action": "executed", "navigateFolderId": Value::Null }))
    }

    pub fn panel_reorder(&self, params: &Value) -> Result<Value, String> {
        let folder_id = req_str(params, "folderId")?;
        let ordered: Vec<String> = params
            .get("orderedChildIds")
            .and_then(|v| v.as_array())
            .map(|a| {
                a.iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()))
                    .collect()
            })
            .unwrap_or_default();
        if crate::panel::is_orphans_folder_id(&folder_id) || ordered.is_empty() {
            return Err("Operation failed.".into());
        }
        if crate::panel::is_root_folder_id(&folder_id) {
            return self.try_reorder_root_children(&ordered);
        }
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        let mut folder = db.get_favor(&folder_id).map_err(panel_folder_not_found)?;
        if !folder.is_folder
            || crate::panel::is_root_folder_id(&folder.id)
            || crate::panel::is_orphans_folder_id(&folder.id)
        {
            return Err("Operation failed.".into());
        }
        let existing: HashSet<_> = folder.children.iter().cloned().collect();
        let mut next: Vec<String> = Vec::new();
        for id in &ordered {
            if existing.contains(id) && !next.contains(id) {
                next.push(id.clone());
            }
        }
        if next.is_empty() {
            return Err("Operation failed.".into());
        }
        for id in &folder.children {
            if !next.contains(id) {
                next.push(id.clone());
            }
        }
        folder.children = next;
        db.save_favor(&folder).map_err(|e| e.to_string())?;
        drop(db);
        self.emit_favorites_changed(&[folder.id], &[]);
        Ok(json!({ "ok": true }))
    }

    pub fn panel_move(&self, params: &Value) -> Result<Value, String> {
        let id = req_str(params, "itemId")?;
        let target_id = req_str(params, "targetFolderId")
            .or_else(|_| req_str(params, "parentId"))?;
        if crate::panel::is_root_folder_id(&target_id) || crate::panel::is_orphans_folder_id(&target_id)
        {
            return Err("Operation failed.".into());
        }
        let before = params
            .get("beforeItemId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string());
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        let mut item = db.get_favor(&id).map_err(panel_item_not_found)?;
        let mut target = db.get_favor(&target_id).map_err(panel_folder_not_found)?;
        if !target.is_folder
            || crate::panel::is_root_folder_id(&target.id)
            || crate::panel::is_orphans_folder_id(&target.id)
        {
            return Err("Operation failed.".into());
        }
        if item.is_folder {
            let mut ancestor = Some(target.id.clone());
            let mut visited = HashSet::new();
            while let Some(parent_id) = ancestor {
                if parent_id == item.id {
                    return Err("不能将收藏夹移动到自身或子文件夹中。".into());
                }
                if !visited.insert(parent_id.clone()) {
                    return Err("目标收藏夹结构存在循环，无法移动。".into());
                }
                ancestor = db.get_favor(&parent_id).map_err(|e| e.to_string())?.parent_id;
            }
        }
        let old_parent = item.parent_id.clone();
        let mut changes = Vec::new();
        if old_parent.as_deref() != Some(target_id.as_str()) {
            if let Some(pid) = old_parent.as_ref() {
                match db.get_favor(pid) {
                    Ok(mut old) => {
                        old.children.retain(|c| c != &id);
                        changes.push(old);
                    }
                    Err(StoreError::NotFound(_)) => {}
                    Err(error) => return Err(error.to_string()),
                }
            }
        }
        crate::panel::insert_child_id(&mut target.children, &id, before.as_deref());
        item.parent_id = Some(target_id);
        changes.extend([target, item]);
        db.save_favors_atomic(&changes).map_err(|e| e.to_string())?;
        drop(db);
        if old_parent.is_none() {
            let favors = self.store().lock().list_favors().map_err(|e| e.to_string())?;
            self.ensure_root_children_order(&favors);
        }
        self.emit_favorites_changed(&changes.iter().map(|item| item.id.clone()).collect::<Vec<_>>(), &[]);
        Ok(json!({ "ok": true }))
    }

    pub fn panel_show(&self, params: &Value) -> Result<Value, String> {
        self.panel_show_guarded(params, &|_| Ok(()))
    }

    fn panel_show_guarded(&self, params: &Value, verify: &dyn Fn(&HostInner) -> Result<(), String>) -> Result<Value, String> {
        let favor_id = params
            .get("favorId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let folder_id = params
            .get("folderId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let items = self.store().lock().list_favors().map_err(|e| e.to_string())?;
        let ordered = self.ensure_root_children_order(&items);
        let route = resolve_panel_show_route(&items, &ordered, favor_id, folder_id)
            .ok_or_else(|| "Panel not found.".to_string())?;
        {
            let mut inner = self.inner.lock();
            verify(&inner)?;
            drop_queued_window_input(&mut inner, "panel");
            cancel_window_presentation(&mut inner, "panel");
            inner.ui.panel_visible = true;
            inner.ui.panel_folder_id = Some(route.current_id.clone());
            inner.ui.panel_no_focus_session = true;
            inner.ui.panel_fake_focus = true;
            inner.ui.last_command = Some("openPanel".into());
            inner.ui.pending_nav.insert("panel", panel_spa_route(Some(&route.current_id)));
            if inner.ui.pending_panel_show_loc.is_none() {
                inner.ui.pending_panel_show_loc = Some(inner.extras.panel.show_window_location1.clone());
            }
            push_chrome(&mut inner, ChromeCommand::ShowPanel);
        }
        Ok(json!({
            "ok": true,
            "shown": true,
            "favorId": route.panel_id,
            "folderId": route.current_id
        }))
    }

    fn panel_show_folder(&self, id: &str) {
        if self
            .panel_show(&json!({ "favorId": id, "folderId": id }))
            .is_ok()
        {
            self.push_event("hostShow", json!({ "tab": "panel", "id": id }));
        } else {
            // C# `IPanelService.ShowPanel` / `ClipHostPanelService` toast.
            self.popup_warning("页面不存在");
        }
    }

    fn panel_show_for_id(&self, id: &str) -> Result<Value, String> {
        let resolved = self.resolve_panel_favor_id(id);
        match self.panel_show(&json!({ "favorId": resolved, "folderId": resolved })) {
            Ok(shown) => Ok(shown),
            Err(_) => {
                // C# `ClipHostPanelService.ShowPanel` toast, ExecuteLine does not throw.
                self.popup_warning("页面不存在");
                Ok(json!({ "ok": true, "shown": false }))
            }
        }
    }

    /// C# `PanelHostExecutor`: integer ids go through `MapId`; miss → `""` → `GetFirstFavorites()`.
    fn resolve_panel_favor_id(&self, id: &str) -> String {
        let trimmed = id.trim();
        let looked_up = if trimmed.parse::<i32>().is_ok() {
            let store = self.inner.lock().store.clone();
            if store.lock().get_favor(trimmed).is_ok() {
                trimmed.to_string()
            } else {
                String::new()
            }
        } else {
            trimmed.to_string()
        };
        if !looked_up.is_empty() {
            return looked_up;
        }
        let items = match self.store().lock().list_favors() {
            Ok(items) => items,
            Err(_) => return String::new(),
        };
        crate::favor_menu::first_favorites(&items)
            .map(|item| item.id.clone())
            .unwrap_or_default()
    }

    /// C# `IPanelService.IsPanelOpenForFavorItem` on the single Tauri panel window.
    fn panel_is_open_for(&self, favor_id: &str) -> bool {
        let inner = self.inner.lock();
        if !inner.ui.panel_visible {
            return false;
        }
        if favor_id.is_empty() {
            return true;
        }
        inner.ui.panel_folder_id.as_deref() == Some(favor_id)
    }

    fn apply_panel_hide(&self) {
        let mut inner = self.inner.lock();
        drop_queued_window_input(&mut inner, "panel");
        cancel_window_presentation(&mut inner, "panel");
        inner.ui.panel_visible = false;
        inner.ui.panel_no_focus_session = false;
        inner.ui.panel_fake_focus = false;
        push_chrome(&mut inner, ChromeCommand::HidePanel);
    }

    /// C# `OnDefaultWindowAction` hide on MainHost: `HideInstant`, not clipboard dismiss.
    fn apply_main_hide(&self) {
        let mut inner = self.inner.lock();
        drop_queued_window_input(&mut inner, "main");
        cancel_window_presentation(&mut inner, "main");
        inner.ui.main_visible = false;
        push_chrome(&mut inner, ChromeCommand::HideMain);
    }

    /// C# `PanelHostWindowWebView` `SwallowEscapeToHideInNoFocusSession` (does not check pin).


    /// C# `PanelHostExecutor` + `PanelManager.ShowOrHide`.
    fn execute_panel_verb(
        &self,
        action: crate::verb::VerbAction,
        id: String,
        ctx: Option<&crate::verb::VerbRunContext>,
    ) -> Result<Value, String> {
        use crate::verb::{verb_ok, VerbAction};
        let automatic = ctx.map(|c| c.is_automatic_run).unwrap_or(false);
        let resolved = self.resolve_panel_favor_id(&id);
        match action {
            VerbAction::Hide | VerbAction::Close => {
                if resolved.is_empty() || self.panel_is_open_for(&resolved) {
                    self.apply_panel_hide();
                }
                Ok(verb_ok(json!({
                    "action": action.as_str(),
                    "id": id,
                    "visible": self.inner.lock().ui.panel_visible,
                })))
            }
            VerbAction::Toggle | VerbAction::ShowOrHide => {
                // C# `ShowOrHidePanel`: hide only when *that* favor window is open.
                if automatic || !self.panel_is_open_for(&resolved) {
                    self.queue_panel_show_loc(ctx);
                    let shown = self.panel_show_for_id(&id)?;
                    self.push_event("hostShow", json!({ "tab": "panel", "id": id }));
                    Ok(verb_ok(json!({ "action": action.as_str(), "id": id, "shown": shown["shown"] })))
                } else {
                    self.apply_panel_hide();
                    Ok(verb_ok(json!({ "action": action.as_str(), "id": id, "visible": false })))
                }
            }
            _ => {
                self.queue_panel_show_loc(ctx);
                let shown = self.panel_show_for_id(&id)?;
                self.push_event("hostShow", json!({ "tab": "panel", "id": id }));
                Ok(verb_ok(json!({ "action": action.as_str(), "id": id, "shown": shown["shown"] })))
            }
        }
    }

    fn ensure_root_children_order(&self, favors: &[FavorRecord]) -> Vec<String> {
        let _operation = self.settings_operation.lock();
        let (path, mut favor) = {
            let inner = self.inner.lock();
            (inner.paths.configs.join("FavorConfig.json"), inner.extras.favor.clone())
        };
        let next = normalized_root_order(favors, &favor.root_children);
        // Derive a usable display order from valid rows, but preserve every
        // persisted reference until the complete graph is available again.
        if self.require_writable_document_view().is_err() {
            return next;
        }
        if next != favor.root_children {
            favor.root_children = next.clone();
            match save_json(&path, &favor) {
                Ok(()) => self.inner.lock().extras.favor = favor,
                // Rendering can derive missing root IDs without losing access to
                // already committed favorites when configuration is read-only.
                Err(error) => tracing::warn!(%error, "could not save derived panel root order"),
            }
        }
        next
    }

    fn try_reorder_root_children(&self, ordered: &[String]) -> Result<Value, String> {
        let _operation = self.settings_operation.lock();
        self.require_writable_document_view()?;
        let (store, path, mut favor) = {
            let inner = self.inner.lock();
            (inner.store.clone(), inner.paths.configs.join("FavorConfig.json"), inner.extras.favor.clone())
        };
        let items = store.lock().list_favors().map_err(|e| e.to_string())?;
        // list_favors can discover a newly invalid row written by another
        // process after the entry guard. Recheck before changing the root file.
        self.require_writable_document_view()?;
        let roots = crate::panel::root_panel_folders(&items);
        if roots.is_empty() || ordered.is_empty() {
            return Err("Operation failed.".into());
        }
        let root_ids: HashSet<String> = roots.iter().map(|i| i.id.clone()).collect();
        let mut next = Vec::new();
        for id in ordered {
            if root_ids.contains(id) && !next.contains(id) {
                next.push(id.clone());
            }
        }
        if next.is_empty() {
            return Err("Operation failed.".into());
        }
        for id in normalized_root_order(&items, &favor.root_children) {
            if !next.contains(&id) {
                next.push(id);
            }
        }
        favor.root_children = next;
        save_json(&path, &favor)?;
        self.inner.lock().extras.favor = favor;
        self.emit_favorites_changed(ordered, &[]);
        Ok(json!({ "ok": true }))
    }

    fn resolve_favor_folder(&self, id: &str) -> Result<FavorRecord, String> {
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        if let Ok(item) = db.get_favor(id) {
            if item.is_folder {
                return Ok(item);
            }
            return Err("Invalid parent folder.".into());
        }
        let items = db.list_favors().map_err(|e| e.to_string())?;
        items
            .into_iter()
            .find(|item| item.is_folder && item.id.eq_ignore_ascii_case(id))
            .ok_or_else(|| "Invalid parent folder.".into())
    }

