    // Keep the earlier folder engine as a test fixture, never a product cloud backend.
    #[cfg(test)]
    fn cloud_execute_folder_fixture(
        &self,
        action: &str,
        slot: Option<&str>,
        all: bool,
        force: bool,
        slot_refs: &[String],
    ) -> Value {
        let device = self.lan.lock().identity.device_id.clone();
        let (root, store) = {
            let inner = self.inner.lock();
            (inner.paths.data_root.clone(), inner.store.clone())
        };
        let folder = crate::cloud_sync::CloudFolder::open(&root, device);
        let favors = store.lock().list_favors().unwrap_or_default();
        self.begin_cloud_op(action, "prepare", "正在准备云同步…", favors.len() as i32);
        let result = match action.to_ascii_lowercase().as_str() {
            "check" => folder.check(slot, all, &favors),
            "list" => folder.list_slots(&favors),
            "probe" => folder.probe(),
            "pull" => match folder.pull(slot, all, force, &favors) {
                Ok((value, applies, report)) => {
                    self.apply_favor_cloud(applies);
                    self.append_cloud_log("info", "pull", &report.summary());
                    value
                }
                Err(err) => self.cloud_fail(&err),
            },
            "push" => match folder.push(slot, all, force, &favors) {
                Ok((value, report)) => {
                    self.append_cloud_log("info", "push", &report.summary());
                    value
                }
                Err(err) => self.cloud_fail(&err),
            },
            "run" | "sync" => match folder.pull(None, true, force, &favors) {
                Ok((pull_value, applies, pull_report)) => {
                    self.apply_favor_cloud(applies);
                    let favors = store.lock().list_favors().unwrap_or_default();
                    match folder.push(None, true, force, &favors) {
                        Ok((push_value, push_report)) => {
                            let summary = format!("{}\n{}", pull_report.summary(), push_report.summary());
                            self.append_cloud_log("info", "run", summary.trim());
                            json!({
                                "slotId": crate::cloud_sync::FAVOR_SLOT,
                                "success": true,
                                "status": push_value.get("status").cloned().or_else(|| pull_value.get("status").cloned()).unwrap_or(Value::Null),
                                "changeReport": {
                                    "pulledDeletions": pull_report.to_json()["pulledDeletions"],
                                    "pulledItems": pull_report.to_json()["pulledItems"],
                                    "pushedDeletions": push_report.to_json()["pushedDeletions"],
                                    "pushedItems": push_report.to_json()["pushedItems"],
                                    "summary": summary.trim(),
                                    "hasChanges": pull_report.has_changes() || push_report.has_changes(),
                                },
                                "message": summary.trim(),
                            })
                        }
                        Err(err) => self.cloud_fail(&err),
                    }
                }
                Err(err) => self.cloud_fail(&err),
            },
            "cleanup" | "cleanup-favor" => match folder.cleanup() {
                Ok(value) => {
                    self.append_cloud_log("info", "cleanup", value["message"].as_str().unwrap_or("cleanup"));
                    value
                }
                Err(err) => self.cloud_fail(&err),
            },
            "purge" | "purge-favor-cloud" => match folder.purge() {
                Ok(value) => {
                    self.append_cloud_log("info", "purge", value["message"].as_str().unwrap_or("purge"));
                    value
                }
                Err(err) => self.cloud_fail(&err),
            },
            "purge-legacy-favor" => folder
                .purge_legacy_aggregate()
                .unwrap_or_else(|err| self.cloud_fail(&err)),
            "purge-orphan-favor-data" => {
                let mut refs = slot_refs.to_vec();
                if let Some(slot) = slot {
                    if !refs.iter().any(|item| item == slot) {
                        refs.push(slot.to_string());
                    }
                }
                folder
                    .purge_orphan_slots(&refs)
                    .unwrap_or_else(|err| self.cloud_fail(&err))
            }
            other => json!({
                "success": false,
                "slotId": crate::cloud_sync::FAVOR_SLOT,
                "message": format!(
                    "用法: sync check <cea.slot>|--all | sync pull|push <cea.slot>|--all [--force]\n未知动作: {other}"
                ),
            }),
        };
        self.end_cloud_op();
        result
    }

    #[cfg(test)]
    fn begin_cloud_op(&self, operation: &str, phase: &str, message: &str, total: i32) {
        let mut inner = self.inner.lock();
        inner.cloud_op = CloudOpProgress {
            active: true,
            operation: operation.into(),
            phase: phase.into(),
            message: message.into(),
            current: 0,
            total,
            started: Some(Instant::now()),
        };
    }

    #[cfg(test)]
    fn end_cloud_op(&self) {
        let mut inner = self.inner.lock();
        inner.cloud_op.active = false;
        inner.cloud_op.phase = "done".into();
    }

    #[cfg(test)]
    fn cloud_fail(&self, err: &str) -> Value {
        self.append_cloud_log("error", "run", err);
        json!({
            "slotId": crate::cloud_sync::FAVOR_SLOT,
            "success": false,
            "status": { "slotId": crate::cloud_sync::FAVOR_SLOT, "status": "Unavailable", "message": err },
            "message": err,
        })
    }

    #[cfg(test)]
    fn apply_favor_cloud(&self, applies: Vec<crate::cloud_sync::FavorApply>) {
        if applies.is_empty() {
            return;
        }
        let store = self.inner.lock().store.clone();
        let db = store.lock();
        for apply in applies {
            match apply {
                crate::cloud_sync::FavorApply::ReplaceAll(items) => {
                    let _ = db.replace_favors(&items);
                }
                crate::cloud_sync::FavorApply::Upsert(item) => {
                    let _ = db.upsert_favor(&item);
                }
                crate::cloud_sync::FavorApply::Delete(id) => {
                    let _ = db.delete_favor(&id);
                }
            }
        }
    }

    #[cfg(test)]
    fn append_cloud_log(&self, level: &str, phase: &str, message: &str) {
        let entry = json!({
            "utc": Utc::now(),
            "level": level,
            "phase": phase,
            "message": message,
            "slotId": crate::cloud_sync::FAVOR_SLOT,
        });
        let path = {
            let mut inner = self.inner.lock();
            inner.cloud_logs.push(entry.clone());
            if inner.cloud_logs.len() > 500 {
                let extra = inner.cloud_logs.len() - 500;
                inner.cloud_logs.drain(0..extra);
            }
            inner.paths.logs.join("cloud-sync.jsonl")
        };
        if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
            use std::io::Write;
            let _ = writeln!(file, "{entry}");
        }
    }

