    pub fn pick_image_file_native_guarded(
        &self, params: &Value, source_hwnd: isize, still_current: impl Fn() -> bool,
    ) -> Result<Value, String> {
        self.require_external_effects("import an external image")?;
        let verify = self.native_main_picker_guard(source_hwnd, still_current)?;
        let initial = initial_path(params);
        verify()?;
        let path = crate::file_dialog_pick::pick_image_file_guarded(initial.as_deref(), source_hwnd as i64, &verify)?;
        verify()?;
        let Some(path) = path else { return Ok(json!({"path":Value::Null,"cancelled":true})); };
        let root = self.inner.lock().paths.data_root.clone();
        verify()?;
        let staged = crate::window_background::stage_copy_guarded(&root, Path::new(&path), &verify);
        verify()?;
        let staged = staged?;
        Ok(json!({"path":staged.to_string_lossy(),"cancelled":false}))
    }

