    fn native_main_picker_guard<'a>(
        &'a self, source_hwnd: isize, still_current: impl Fn() -> bool + 'a,
    ) -> Result<impl Fn() -> Result<(), String> + 'a, String> {
        let retired = || crate::file_dialog_pick::NATIVE_PICKER_RETIRED.to_string();
        // UI leases may call native_caption_drag_allowed, which locks inner.
        // Invoke this external predicate only outside any HostInner lock.
        if !still_current() { return Err(retired()); }
        let (window_generation, presentation_generation) = {
            let inner = self.inner.lock();
            if source_hwnd == 0 || source_hwnd != inner.main_hwnd
                || source_hwnd == inner.host_hwnd || !inner.ui.main_visible
                || !inner.window_runtime_ready {
                return Err(retired());
            }
            (inner.chrome_input_epochs[2].window, inner.chrome_presentation_epochs[2])
        };
        Ok(move || {
            if !still_current() { return Err(retired()); }
            let core_current = {
                let inner = self.inner.lock();
                source_hwnd == inner.main_hwnd && source_hwnd != inner.host_hwnd
                    && inner.ui.main_visible && inner.window_runtime_ready
                    && inner.chrome_input_epochs[2].window == window_generation
                    && inner.chrome_presentation_epochs[2] == presentation_generation
            };
            if !core_current || !still_current() { return Err(retired()); }
            Ok(())
        })
    }

    pub fn stage_window_background_bytes(&self, bytes: &[u8], file_name: &str) -> Result<Value, String> {
        if bytes.is_empty() {
            return Ok(json!({ "path": Value::Null, "cancelled": true }));
        }
        let ext = std::path::Path::new(file_name)
            .extension()
            .and_then(|e| e.to_str())
            .unwrap_or("");
        let root = self.inner.lock().paths.data_root.clone();
        let staged = crate::window_background::stage_bytes(&root, bytes, ext)?;
        Ok(json!({ "path": staged.to_string_lossy(), "cancelled": false }))
    }

    pub fn stage_window_background_path(&self, path: &str) -> Result<Value, String> {
        if path.trim().is_empty() {
            return Ok(json!({ "path": Value::Null, "cancelled": true }));
        }
        let root = self.inner.lock().paths.data_root.clone();
        let path = self.project_output_path(path)?;
        let staged = crate::window_background::stage_copy(&root, std::path::Path::new(&path))?;
        Ok(json!({ "path": staged.to_string_lossy(), "cancelled": false }))
    }

    pub fn register_collect_draft(&self, item: FavorRecord) -> String {
        let id = Uuid::new_v4().as_simple().to_string();
        self.collect_drafts.lock().insert(
            id.clone(),
            CollectDraftEntry {
                item,
                expires: Instant::now() + COLLECT_DRAFT_TTL,
            },
        );
        id
    }

    pub fn collect_get(&self, params: &Value) -> Result<Value, String> {
        let id = req_str(params, "draftId").or_else(|_| req_id(params))?;
        let mut drafts = self.collect_drafts.lock();
        prune_collect_drafts(&mut drafts);
        let entry = drafts
            .get_mut(&id)
            .ok_or_else(|| "Draft not found or expired.".to_string())?;
        entry.expires = Instant::now() + COLLECT_DRAFT_TTL;
        let item = entry.item.clone();
        drop(drafts);
        let store = self.inner.lock().store.clone();
        let folders = store.lock().list_favors().map_err(|e| e.to_string())?;
        Ok(json!({
            "detail": favor_to_detail(&item),
            "folderChoices": folder_choices(&folders),
        }))
    }

    pub fn collect_commit(&self, params: &Value) -> Result<Value, String> {
        // C# `HandleFavorCollectDraftCommit` requires parentId; Commit only rewrites TextClipItem text.
        let id = req_str(params, "draftId").or_else(|_| req_id(params))?;
        let parent_raw = params
            .get("parentId")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .ok_or_else(|| "parentId is required.".to_string())?;
        let insert_index = params
            .get("insertIndex")
            .or_else(|| params.get("InsertIndex"))
            .and_then(|v| v.as_i64())
            .unwrap_or(0) as i32;
        // Serialize commit/discard without holding the host's window-state lock.
        // Keep the original draft until the item and its parent link both commit.
        let mut drafts = self.collect_drafts.lock();
        prune_collect_drafts(&mut drafts);
        let entry = drafts.get_mut(&id)
            .ok_or_else(|| "Draft not found or expired.".to_string())?;
        entry.expires = Instant::now() + COLLECT_DRAFT_TTL;
        let mut item = entry.item.clone();
        // C# `CollectDraftAppService.Commit`: Title whitespace → null; TextClipItem.Text = Content ?? "".
        item.name = params
            .get("title")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .unwrap_or("")
            .to_string();
        // C# `CollectDraftAppService.Commit`: `if (body.Icon != null) item.Icon = body.Icon`.
        if let Some(icon) = params.get("icon") {
            if !icon.is_null() {
                item.icon = icon.as_str().unwrap_or("").to_string();
            }
        }
        if matches!(
            item.kind,
            ClipKind::TextClipItem | ClipKind::HtmlClipItem | ClipKind::QQRichTextItem
        ) {
            item.body_text = Some(
                params
                    .get("content")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string(),
            );
        }
        let parent = self.resolve_favor_folder(parent_raw)?;
        item.parent_id = Some(parent.id);
        let store = self.inner.lock().store.clone();
        store.lock().insert_favor_checked_at(&item, insert_index).map_err(|e| e.to_string())?;
        drafts.remove(&id);
        drop(drafts);
        self.emit_favorites_changed(&[item.id.clone()], &[]);
        Ok(json!({ "ok": true }))
    }

    pub fn collect_discard(&self, params: &Value) -> Result<Value, String> {
        let id = req_str(params, "draftId").or_else(|_| req_id(params))?;
        self.collect_drafts.lock().remove(&id);
        Ok(json!({ "ok": true }))
    }

