    fn quicker_browser_call(&self, method: &str) -> Result<Value, String> {
        let session = self.quicker_rpc.select().ok_or(crate::browser::UNAVAILABLE)?;
        session.call(method, Value::Null, crate::quicker_rpc::BROWSER_TIMEOUT)
    }

    fn quicker_browser_tabs(&self) -> Result<Vec<crate::browser::BrowserTab>, String> {
        let result = self.quicker_browser_call("quicker.getAllBrowserTabs")?;
        let values = result.as_array().ok_or(crate::browser::UNAVAILABLE)?;
        Ok(values.iter().filter_map(crate::browser::BrowserTab::from_rpc).collect())
    }

    fn quicker_presentation_call(&self, method: &str, params: Value) -> Option<Value> {
        let session = self.quicker_rpc.select()?;
        match session.call(method, params, crate::quicker_rpc::INTERACTIVE_TIMEOUT) {
            Ok(value) if !value.is_null() => Some(crate::quicker_rpc::presentation_json(value)),
            Ok(_) => None,
            Err(error) => {
                tracing::debug!(%method, %error, "Quicker presentation unavailable; using offline data");
                None
            }
        }
    }

