    #[test]
    fn native_ui_poll_hint_covers_secondary_surfaces_and_settles_when_hidden() {
        crate::clipboard::force_headless(true);
        let root = tempdir().unwrap();
        // The regular core starts shown and launches background services. Use
        // the service-free fixture so an unrelated startup worker cannot make
        // this nonblocking hint conservatively return true during assertions.
        let host = HostState::open_with_store_services(
            AppPaths::from_data_root(root.path().join("BetterClipTauri")),
            29065, AppStore::open_unprojected, true,
        ).unwrap();
        host.window_hide();
        host.inner.lock().chrome.clear();
        assert!(!host.needs_native_ui_poll());
        let surfaces: [fn(&mut HostInner, bool); 10] = [
            |inner, value| inner.window_visible = value,
            |inner, value| inner.ui.panel_visible = value,
            |inner, value| inner.ui.main_visible = value,
            |inner, value| inner.qp.overlay_visible = value,
            |inner, value| inner.toast.visible = value,
            |inner, value| inner.super_menu.visible = value,
            |inner, value| inner.ceabox.visible = value,
            |inner, value| inner.reopen.visible = value,
            |inner, value| inner.file_browser.visible = value,
            |inner, value| inner.native_context_menu = value.then_some(NativeContextMenuLease {
                id: 1, owner: "clipboard", popup_hwnd: 0, text_input: false, trigger: None,
            }),
        ];
        for set_visible in surfaces {
            set_visible(&mut host.inner.lock(), true);
            assert!(host.needs_native_ui_poll());
            set_visible(&mut host.inner.lock(), false);
            assert!(!host.needs_native_ui_poll());
        }
        push_chrome(&mut host.inner.lock(), ChromeCommand::Hide);
        assert!(host.needs_native_ui_poll());
        host.inner.lock().chrome.clear();
        assert!(!host.needs_native_ui_poll());
        let at = Instant::now();
        {
            let mut inner = host.inner.lock();
            inner.fifo = Some(vec!["fixture".into()]);
            inner.fifo_last_activity = Some(at);
            inner.qp_config.session_idle_seconds = 10;
        }
        assert!(!host.needs_native_ui_poll(), "hidden FIFO uses its expiry deadline");
        assert_eq!(host.next_native_ui_deadline(), Some(at + Duration::from_secs(10)));
        host.inner.lock().fifo = None;
        assert_eq!(host.next_native_ui_deadline(), None);
        let _busy = host.inner.lock();
        assert!(host.needs_native_ui_poll(), "contention must schedule conservatively without blocking");
    }

