    #[test]
    fn native_context_menu_text_input_escape_drain_protects_owner_until_keyup() {
        crate::clipboard::force_headless(true);
        let root = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(root.path().to_path_buf()), 28965).unwrap();
        {
            let mut inner = host.inner.lock();
            inner.window_visible = true;
            inner.host_hwnd = 101;
            inner.config.enable_no_focus_mode = true;
            inner.config.dismiss_behavior = "Hide".into();
        }
        assert!(host.acquire_native_context_menu(1, "clipboard"));
        assert!(host.set_native_context_menu_hwnd(1, 102));
        assert!(host.request_native_context_menu_text_input(1));
        let down = KeyEvent { vk: 0x1B, down: true, ctrl: false, alt: false, shift: false, win: false, now_ms: 0 };
        assert!(!host.dispatch_low_level_key_for_foreground(down, 102), "the first Escape reaches the real input/IME");
        assert!(!host.begin_native_context_menu_escape_drain(2), "an old UI callback cannot arm another lease");
        assert!(!host.inner.lock().native_context_menu_escape_down);
        assert!(host.begin_native_context_menu_escape_drain(1));
        assert!(host.release_native_context_menu(1));
        // Restore ordinary no-focus owner browsing as the popup disappears.
        // A repeat would otherwise be a valid Escape-hide in this session.
        host.begin_no_focus_session_if_enabled();
        assert!(host.dispatch_low_level_key_for_foreground(down, 101));
        assert!(host.dispatch_low_level_key_for_foreground(down, 101));
        assert!(host.inner.lock().window_visible);
        assert!(!host.inner.lock().chrome.iter().any(|command| *command == ChromeCommand::ClipboardHandleEscape),
            "held repeats cannot even queue owner dismissal behind the closing popup");
        assert!(!host.begin_native_context_menu_escape_drain(1));
        assert!(host.dispatch_low_level_key_for_foreground(KeyEvent { down: false, ..down }, 101));
        assert!(!host.inner.lock().native_context_menu_escape_down);
        assert!(host.dispatch_low_level_key_for_foreground(down, 101));
        assert_eq!(host.inner.lock().chrome.iter().filter(|command| **command == ChromeCommand::ClipboardHandleEscape).count(), 1);
        // Ordinary no-focus Escape first asks the UI about its own layers.
        // Only its current unhandled reply may hide the owner.
        let task = std::iter::from_fn(|| host.take_chrome_task())
            .find(|task| task.command() == ChromeCommand::ClipboardHandleEscape).unwrap();
        assert!(host.prepare_chrome_task(task));
        assert!(host.inner.lock().window_visible);
        host.clipboard_escape_unhandled(Some(&task.escape_session_token()), task.escape_input_token().as_deref());
        assert!(!host.inner.lock().window_visible, "a fresh press can dismiss the owner normally");
    }

