        host.toast_web_action(&json!({"action":"unhover"}));
        assert!(!host.inner.lock().toast.hovered);
        assert_eq!(host.toast_web_action(&json!({"action":"idle"}))["deferred"], true);
        let generation = {
            let mut inner = host.inner.lock();
            inner.toast.idle_deadline = Some(Instant::now() - Duration::from_millis(1));
            inner.toast.generation
        };
        assert!(!host.toast_collapse_expired(generation));
        assert!(host.release_native_context_menu(1));
        assert!(host.inner.lock().toast.idle_deadline.is_some());
