    #[test]
    fn legacy_config_invalid_retention_stops_host_before_database_or_config_write() {
        let dir = tempdir().unwrap();
        let paths = AppPaths::from_data_root(dir.path().join("Ceastld"));
        std::fs::create_dir_all(&paths.configs).unwrap();
        let config = paths.configs.join("ClipConfig.json");
        let original = b"\xef\xbb\xbf{\"MaxItemSize\":\"invalid\",\"Future\":123}";
        std::fs::write(&config, original).unwrap();
        let database = b"untouched database sentinel";
        std::fs::write(&paths.db, database).unwrap();
        let error = HostState::open(paths.clone(), 28965).err().expect("invalid old limit must stop startup");
        assert!(error.contains("配置"), "{error}");
        assert_eq!(std::fs::read(&config).unwrap(), original);
        assert_eq!(std::fs::read(&paths.db).unwrap(), database);
    }

    #[test]
    fn inbound_text_commits_after_pair() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        let pair = host
            .lan_accept_inbound_pair(&json!({
                "deviceId": "peerA",
                "alias": "desk",
                "baseUrl": "https://10.0.0.2:29766",
                "certificateFingerprint": "a".repeat(64),
                "pairingCode": code,
                "tokenForReceiver": crate::lan::create_token(),
            }))
            .unwrap();
        assert!(pair["baseUrl"].as_str().unwrap().starts_with("https://"));
        assert!(!pair["baseUrl"].as_str().unwrap().contains("/cliplink"));
        assert_eq!(
            pair["baseUrl"].as_str().unwrap(),
            crate::lan::preferred_local_base_url(host.lan_port())
        );
        crate::lan::validate_token(pair["tokenForRequester"].as_str().unwrap()).unwrap();
        let token = pair["tokenForRequester"].as_str().unwrap().to_string();
        host.lan_authenticate(Some("peerA"), Some(&format!("Bearer {token}")))
            .unwrap();
        let delivered = host
            .lan_receive_text(
                "peerA",
                &json!({
                    "id": "msg1",
                    "senderDeviceId": "peerA",
                    "senderAlias": "desk",
                    "targetKind": "direct",
                    "text": "hello-lan",
                    "createdAtUtc": Utc::now(),
                    "attachments": [],
                }),
            )
            .unwrap();
        assert_eq!(delivered["delivered"], true);
        let messages = host.lan_messages(&json!({ "conversationId": "dm:peerA" })).unwrap();
        assert_eq!(messages[0]["text"], "hello-lan");
        assert_eq!(messages[0]["status"], "received");
    }

    #[test]
    fn lan_listener_status_tracks_errors_and_ignores_stale_ports() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("host")), 28965).unwrap();
        host.lan_config_update(&json!({"enabled": true, "port": 29767})).unwrap();
        host.drain_push_events();
        host.lan_set_listener_error(29767, "port occupied".into());
        assert_eq!(host.lan_status()["error"], "port occupied");
        assert_eq!(host.drain_push_events().len(), 1);
        host.lan_set_listener_error(29767, "port occupied".into());
        assert!(host.drain_push_events().is_empty(), "unchanged errors should not flood the page");
        host.lan_config_update(&json!({"deviceAlias": "renamed"})).unwrap();
        assert_eq!(host.lan_status()["error"], "port occupied");
        host.lan_config_update(&json!({"enabled": false})).unwrap();
        host.lan_set_listener_error(29767, "late failure".into());
        assert_eq!(host.lan_status()["error"], "");
        host.lan_config_update(&json!({"enabled": true, "port": 29768})).unwrap();
        host.lan_set_listener_error(29767, "old port failure".into());
        assert_eq!(host.lan_status()["error"], "");
        host.lan_set_listener_error(29768, "new port failure".into());
        assert_eq!(host.lan_status()["error"], "new port failure");
        host.lan_config_update(&json!({"port": 29769})).unwrap();
        assert_eq!(host.lan_status()["error"], "");
        host.lan_set_listener_error(29769, "retrying".into());
        host.lan_set_listener_error(29769, String::new());
        host.lan_set_running(true);
        assert_eq!(host.lan_status()["error"], "");
        assert_eq!(host.lan_status()["running"], true);
        host.lan_set_running(false);
        assert_eq!(host.lan_status()["running"], false);
    }

