    #[test]
    fn inbound_pair_rewrites_host_and_rejects_bad_token() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let err = host
            .lan_accept_inbound_pair(&json!({
                "deviceId": "peerBadToken",
                "alias": "desk",
                "baseUrl": "https://10.0.0.2:29766",
                "certificateFingerprint": "a".repeat(64),
                "pairingCode": host.lan_status()["pairingCode"]["code"].as_str().unwrap(),
                "tokenForReceiver": "recv-token",
            }))
            .unwrap_err();
        assert_eq!(err, "配对令牌格式无效。");
        let expired = host
            .lan_accept_inbound_pair(&json!({
                "deviceId": "peerBadCode",
                "alias": "desk",
                "baseUrl": "https://10.0.0.2:29766",
                "certificateFingerprint": "a".repeat(64),
                "pairingCode": "000000",
                "tokenForReceiver": crate::lan::create_token(),
            }))
            .unwrap_err();
        assert_eq!(expired, "配对码无效或已过期。");
        assert_eq!(crate::lan::pair_http_status(&expired), 403);
        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        host.lan_accept_inbound_pair_from(
            &json!({
                "deviceId": "peerRewrite",
                "alias": "desk",
                "baseUrl": "https://10.0.0.2:29766",
                "certificateFingerprint": "a".repeat(64),
                "pairingCode": code,
                "tokenForReceiver": crate::lan::create_token(),
            }),
            Some("10.0.0.9"),
        )
        .unwrap();
        assert_eq!(host.lan_peers()[0]["baseUrl"], "https://10.0.0.9:29766");
    }

    #[test]
    fn inbound_attachment_rejects_bad_hash_then_commits() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        host.lan_accept_inbound_pair(&json!({
            "deviceId": "peerB",
            "alias": "desk",
            "baseUrl": "https://10.0.0.2:29766",
            "certificateFingerprint": "c".repeat(64),
            "pairingCode": code,
            "tokenForReceiver": crate::lan::create_token(),
        }))
        .unwrap();
        let bytes = b"hello-file";
        let sha = crate::lan::sha256_hex(bytes);
        host.lan_prepare_inbound(
            "peerB",
            &json!({
                "id": "filemsg",
                "senderDeviceId": "peerB",
                "senderAlias": "desk",
                "targetKind": "direct",
                "text": "",
                "createdAtUtc": Utc::now(),
                "attachments": [{
                    "id": "att1",
                    "name": "note.txt",
                    "mimeType": "text/plain",
                    "sizeBytes": bytes.len(),
                    "sha256": sha,
                }],
            }),
        )
        .unwrap();
        assert_eq!(
            host.lan_upload_inbound("peerB", "filemsg", "att1", b"wrong", 5)
                .unwrap_err(),
            "附件长度与声明不一致。"
        );
        assert_eq!(
            host.lan_upload_inbound("peerB", "filemsg", "att1", b"hello", bytes.len() as i64)
                .unwrap_err(),
            "附件内容不完整。"
        );
        host.lan_upload_inbound("peerB", "filemsg", "att1", bytes, bytes.len() as i64).unwrap();
        let committed = host.lan_commit_inbound("peerB", "filemsg").unwrap();
        assert_eq!(committed["delivered"], true);
        let messages = host.lan_messages(&json!({ "conversationId": "dm:peerB" })).unwrap();
        assert_eq!(messages[0]["attachments"][0]["name"], "note.txt");
        let opened = host.lan_attachment_open(&json!({ "attachmentId": "att1" })).unwrap();
        assert_eq!(opened["ok"], true);
        assert_eq!(
            host.lan_attachment_open(&json!({ "attachmentId": "missing" }))
                .unwrap_err(),
            "附件记录不存在。"
        );
    }

    #[test]
    fn paired_peers_reload_from_disk() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let root = dir.path().join("BetterClipTauri");
        let host = HostState::open(AppPaths::from_data_root(root.clone()), 28965).unwrap();
        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        host.lan_accept_inbound_pair(&json!({
            "deviceId": "peerPersist",
            "alias": "desk",
            "baseUrl": "https://10.0.0.2:29766",
            "certificateFingerprint": "b".repeat(64),
            "pairingCode": code,
            "tokenForReceiver": crate::lan::create_token(),
        }))
        .unwrap();
        drop(host);
        let host = HostState::open(AppPaths::from_data_root(root), 28965).unwrap();
        let peers = host.lan_peers();
        assert_eq!(peers[0]["deviceId"], "peerPersist");
        assert_eq!(peers[0]["paired"], true);
        // C# `ListPeers`: lastSeen within 35s stays online even without UDP this process.
        assert_eq!(peers[0]["online"], true);
        host.lan
            .lock()
            .discovered
            .get_mut("peerPersist")
            .unwrap()
            .last_seen_at_utc = Utc::now() - chrono::Duration::seconds(40);
        assert_eq!(host.lan_peers()[0]["online"], false);
    }

