    #[test]
    fn search_filters_usage_and_ids_match() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let created = host.create_session();
        let session = created
            .get("sessionId")
            .and_then(|value| value.as_str())
            .or_else(|| created.get("webSessionId").and_then(|value| value.as_str()))
            .unwrap_or_else(|| panic!("create_session returned {created}"))
            .to_string();
        host.add_text(&json!({ "text": "alpha" })).unwrap();
        host.add_text(&json!({ "text": "beta" })).unwrap();
        let unused = host.search_items(&json!({
            "webSessionId": session,
            "usageFilter": 2,
            "take": 50
        }))
        .unwrap();
        assert!(unused["total"].as_i64().unwrap() >= 2);
        let ids = host.search_items(&json!({
            "webSessionId": session,
            "query": "alpha",
            "projection": "idsMatch",
            "take": 50
        }))
        .unwrap();
        assert!(ids["items"].as_array().unwrap().is_empty());
        assert!(!ids["hits"].as_array().unwrap().is_empty());
        assert!(ids["hits"][0].get("highlightedText").is_some());
        let empty_query = host
            .search_items(&json!({
                "webSessionId": session,
                "projection": "idsMatch",
                "take": 50
            }))
            .unwrap();
        assert!(empty_query["hits"][0].get("highlightedText").is_none());
        assert!(empty_query["hits"][0].get("id").is_some());
        let last = host
            .search_items(&json!({
                "webSessionId": session,
                "skip": 1,
                "take": 50
            }))
            .unwrap();
        let last_count = last["items"].as_array().unwrap().len() as i64;
        assert_eq!(last["nextSkip"], 1 + last_count);
        assert_eq!(last["hasMore"], false);
        assert_eq!(
            host.search_items(&Value::Null).unwrap_err(),
            "Request body is required."
        );
        let plain = host
            .search_items(&json!({
                "webSessionId": session,
                "filterItem": { "type": "plain" },
                "take": 50
            }))
            .unwrap();
        assert!(plain["total"].as_i64().unwrap() >= 2);
        let today = Local::now().format("%Y-%m-%d").to_string();
        let dated = host
            .search_items(&json!({
                "webSessionId": session,
                "query": "alpha",
                "createTimeFilter": -2,
                "createTimeFilterDate": today,
                "take": 50
            }))
            .unwrap();
        assert!(dated["total"].as_i64().unwrap() >= 1);
        let old = host
            .search_items(&json!({
                "webSessionId": session,
                "query": "alpha",
                "createTimeFilter": -2,
                "createTimeFilterDate": "1999-01-01",
                "take": 50
            }))
            .unwrap();
        assert_eq!(old["total"], 0);
    }

    #[test]
    fn search_process_filter_matches_csharp_exe_suffix() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let created = host.create_session();
        let session = created["sessionId"].as_str().unwrap().to_string();
        let mut chrome = ClipRecord::new_text("from-chrome", "chrome");
        chrome.source_process_name = "chrome".into();
        let mut notepad = ClipRecord::new_text("from-notepad", "notepad.exe");
        notepad.source_process_name = "notepad.exe".into();
        host.inner.lock().store.lock().insert_clip(&chrome, true).unwrap();
        host.inner.lock().store.lock().insert_clip(&notepad, true).unwrap();
        let by_stem = host
            .search_items(&json!({
                "webSessionId": session,
                "processFilter": { "includeExeNames": ["chrome"] },
                "take": 50
            }))
            .unwrap();
        let texts: Vec<String> = by_stem["items"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|row| row["summary"].as_str().map(str::to_string))
            .collect();
        assert!(texts.iter().any(|t| t == "from-chrome"), "{by_stem}");
        assert!(!texts.iter().any(|t| t == "from-notepad"), "{by_stem}");
        let blank = host
            .search_items(&json!({
                "webSessionId": session,
                "processFilter": { "includeExeNames": ["  ", ""] },
                "take": 50
            }))
            .unwrap();
        let blank_texts: Vec<String> = blank["items"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|row| row["summary"].as_str().map(str::to_string))
            .collect();
        assert!(blank_texts.iter().any(|t| t == "from-chrome"), "{blank}");
        assert!(blank_texts.iter().any(|t| t == "from-notepad"), "{blank}");
        let mixed = host
            .search_items(&json!({
                "webSessionId": session,
                "processFilter": { "includeExeNames": [" Chrome.EXE ", "notepad"] },
                "take": 50
            }))
            .unwrap();
        assert!(mixed["total"].as_i64().unwrap() >= 2, "{mixed}");
    }

