    #[test]
    fn lan_send_all_requires_paired_and_records_deliveries() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        assert_eq!(host.lan_discover().unwrap_err(), "请先启用局域网互传。");
        let err = host.lan_send(&json!({ "text": "nobody" })).unwrap_err();
        assert!(err.contains("请先启用局域网互传"), "{err}");
        host.lan_config_update(&json!({ "enabled": true })).unwrap();
        assert_eq!(host.lan_discover().unwrap_err(), "请先启用局域网互传。");
        let err = host.lan_send(&json!({ "text": "nobody" })).unwrap_err();
        assert!(err.contains("还没有已配对设备"), "{err}");

        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        host.lan_accept_inbound_pair(&json!({
            "deviceId": "peerAll",
            "alias": "desk",
            "baseUrl": "https://127.0.0.1:1",
            "certificateFingerprint": "b".repeat(64),
            "pairingCode": code,
            "tokenForReceiver": crate::lan::create_token(),
        }))
        .unwrap();
        let sent = host
            .lan_send(&json!({ "conversationId": ALL_CONVERSATION_ID, "text": "hello-all" }))
            .unwrap();
        assert_eq!(sent["targetKind"], "group");
        assert_eq!(sent["status"], "queued");
        assert_eq!(sent["deliveries"][0]["targetDeviceId"], "peerAll");
        assert_eq!(sent["deliveries"][0]["id"], format!("{}:peerAll", sent["id"].as_str().unwrap()));
        let listed = wait_lan_message(&host, ALL_CONVERSATION_ID, |item| {
            item["status"] == "failed"
                && item["deliveries"][0]["attemptCount"].as_i64().unwrap_or(0) >= 1
        });
        let first_attempts = listed[0]["deliveries"][0]["attemptCount"].as_i64().unwrap();
        let last_error = listed[0]["deliveries"][0]["lastError"].as_str().unwrap();
        assert!(!last_error.is_empty(), "{listed}");
        assert!(!last_error.contains("headless"), "{listed}");
        assert_eq!(listed[0]["text"], "hello-all");
        let delivery_id = sent["deliveries"][0]["id"].as_str().unwrap().to_string();
        let mut saw_delivery = false;
        for _ in 0..100 {
            let events = host.drain_push_events();
            if events.iter().any(|(name, data)| {
                name == crate::lan::SHARE_CHANGED_EVENT
                    && data.get("deliveryId").and_then(|v| v.as_str()) == Some(delivery_id.as_str())
                    && data.get("message").is_some()
            }) {
                saw_delivery = true;
                break;
            }
            std::thread::sleep(Duration::from_millis(20));
        }
        assert!(saw_delivery, "missing lan.share.changed deliveryId event");
        assert_eq!(
            host.lan_retry(&json!({ "messageId": sent["id"] })).unwrap()["ok"],
            true
        );
        let retried = wait_lan_message(&host, ALL_CONVERSATION_ID, |item| {
            item["status"] == "failed"
                && item["deliveries"][0]["attemptCount"].as_i64().unwrap_or(0) > first_attempts
        });
        assert_eq!(retried[0]["status"], "failed");
        assert_eq!(
            host.lan_cancel(&json!({ "messageId": sent["id"] })).unwrap()["ok"],
            true
        );
        let canceled = host
            .lan_messages(&json!({ "conversationId": ALL_CONVERSATION_ID }))
            .unwrap();
        assert_eq!(canceled[0]["status"], "canceled");
        assert_eq!(canceled[0]["deliveries"][0]["status"], "canceled");
        assert_eq!(
            host.lan_send(&json!({ "conversationId": "dm:missing", "text": "x" }))
                .unwrap_err(),
            "目标设备尚未配对。"
        );
        let discovered_at = Instant::now();
        host.lan_set_running(true);
        let discovered = host.lan_discover().unwrap();
        assert!(discovered.as_array().is_some());
        assert!(discovered_at.elapsed() >= crate::lan::DISCOVER_REPLY_WAIT);
        let pairing = host.lan_refresh_code();
        assert!(pairing.get("code").is_some());
        assert!(pairing.get("attemptsRemaining").is_some());
        assert!(pairing.get("enabled").is_none());
    }

    #[test]
    fn lan_clip_file_probe_does_not_block_window_or_database_operations() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let path = dir.path().join("slow-file.txt");
        std::fs::write(&path, b"file").unwrap();
        let mut clip = ClipRecord::new_text("", "lan-fixture");
        clip.kind = ClipKind::FileClipItem;
        clip.file_paths = vec![path.to_string_lossy().into_owned()];
        host.inner.lock().store.lock().insert_clip(&clip, true).unwrap();

        let (entered_tx, entered_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let sending = host.clone();
        let id = clip.id.clone();
        let send = thread::spawn(move || sending.lan_send_clips_with_metadata(&json!({"ids":[id]}), |path| {
            entered_tx.send(()).unwrap();
            release_rx.recv_timeout(Duration::from_secs(15)).unwrap();
            std::fs::metadata(path)
        }));
        entered_rx.recv_timeout(Duration::from_secs(5)).expect("metadata probe did not start");
        let (ready_tx, ready_rx) = mpsc::channel();
        let responsive = host.clone();
        let operations = thread::spawn(move || {
            let pinned = responsive.apply_window_action("setPinned", true);
            let added = responsive.add_text(&json!({"text":"search stays responsive"}));
            // The database must also remain writable while the old selection's
            // file metadata is pending.
            let deleted = responsive.delete_item(&json!({"id":clip.id}));
            ready_tx.send((pinned, added, deleted)).unwrap();
        });
        let result = ready_rx.recv_timeout(Duration::from_secs(5));
        release_tx.send(()).unwrap();
        let sent = send.join().unwrap();
        operations.join().unwrap();
        let (pinned, added, deleted) = result.expect("file metadata held a host or database lock");
        assert_eq!(pinned["isPinned"], true);
        assert!(added.is_ok());
        assert!(deleted.is_ok());
        // This fixture does not enable LAN or start any network listener.
        assert_eq!(sent.unwrap_err(), "请先启用局域网互传。");
    }

    #[test]
    fn lan_send_clips_packs_text_files_and_folder_note() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        assert_eq!(host.lan_send_clips(&json!({})).unwrap_err(), "ids is required.");
        assert_eq!(
            host.lan_send_clips(&json!({ "ids": [] })).unwrap_err(),
            "At least one clip item is required."
        );
        assert_eq!(
            host.lan_send_clips(&json!({ "ids": ["missing-clip"] })).unwrap_err(),
            "Clipboard item missing-clip was not found."
        );

        host.lan_config_update(&json!({ "enabled": true })).unwrap();
        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        host.lan_accept_inbound_pair(&json!({
            "deviceId": "peerClips",
            "alias": "desk",
            "baseUrl": "https://127.0.0.1:1",
            "certificateFingerprint": "e".repeat(64),
            "pairingCode": code,
            "tokenForReceiver": crate::lan::create_token(),
        }))
        .unwrap();

        let a = host.add_text(&json!({ "text": "hello-clip" })).unwrap();
        let b = host.add_text(&json!({ "text": "world-clip" })).unwrap();
        let a_id = a["createdIds"][0].as_str().unwrap().to_string();
        let b_id = b["createdIds"][0].as_str().unwrap().to_string();
        let file_path = dir.path().join("note.txt");
        std::fs::write(&file_path, b"hi").unwrap();
        let folder_path = dir.path().join("not-sent");
        std::fs::create_dir(&folder_path).unwrap();
        let mut file_clip = ClipRecord::new_text("files", "lan");
        file_clip.kind = ClipKind::FileClipItem;
        file_clip.file_paths = vec![
            file_path.to_string_lossy().into_owned(),
            folder_path.to_string_lossy().into_owned(),
        ];
        let file_id = file_clip.id.clone();
        host.inner
            .lock()
            .store
            .lock()
            .insert_clip(&file_clip, true)
            .unwrap();

        let sent = host
            .lan_send_clips(&json!({
                "ids": [a_id, b_id, file_id, a_id],
                "conversationId": ALL_CONVERSATION_ID
            }))
            .unwrap();
        let text = sent["text"].as_str().unwrap();
        assert!(text.contains("hello-clip\n\nworld-clip"), "{text}");
        assert!(text.contains("[文件夹未自动发送]"), "{text}");
        assert_eq!(sent["attachments"].as_array().unwrap().len(), 1);
        assert_eq!(sent["attachments"][0]["name"], "note.txt");
        assert_eq!(sent["attachments"][0]["mimeType"], "text/plain");
    }

    #[test]
    fn lan_read_preserves_already_read_payload_and_unknown_fields() {
        crate::clipboard::force_headless(true);
        let temporary_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../.tmp/lan-perf-20261018");
        std::fs::create_dir_all(&temporary_root).unwrap();
        let dir = tempfile::Builder::new().prefix("core-read-").tempdir_in(temporary_root).unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("data")), 29065).unwrap();
        let already_read = r#"{ "id": "read", "direction": "incoming", "isRead": true, "future": { "field": 7 } }"#;
        let outgoing = r#"{ "id": "outgoing", "direction": "outgoing", "isRead": false }"#;
        {
            let store = host.store();
            let db = store.lock();
            db.insert_lan_message("read", "dm:fixture", already_read).unwrap();
            db.insert_lan_message("outgoing", "dm:fixture", outgoing).unwrap();
            db.insert_lan_message("unread", "dm:fixture", r#"{"id":"unread","direction":"incoming","isRead":false,"future":{"field":9}}"#).unwrap();
            db.insert_lan_message("missing-flag", "dm:fixture", r#"{"id":"missing-flag","direction":"incoming"}"#).unwrap();
            db.insert_lan_message("invalid", "dm:fixture", "{invalid").unwrap();
        }
        host.lan_read(&json!({"conversationId":"dm:fixture"})).unwrap();
        let store = host.store();
        let db = store.lock();
        assert_eq!(db.get_lan_message("read").unwrap(), already_read, "already-read rows must not be reserialized or rewritten");
        assert_eq!(db.get_lan_message("outgoing").unwrap(), outgoing);
        assert_eq!(db.get_lan_message("invalid").unwrap(), "{invalid");
        let unread: Value = serde_json::from_str(&db.get_lan_message("unread").unwrap()).unwrap();
        assert_eq!(unread["isRead"], true);
        assert_eq!(unread["future"]["field"], 9);
        let missing_flag: Value = serde_json::from_str(&db.get_lan_message("missing-flag").unwrap()).unwrap();
        assert_eq!(missing_flag["isRead"], true, "missing flags retain the existing normalization behavior");
    }

    #[test]
    fn lan_messages_keeps_default_and_clamped_limits() {
        crate::clipboard::force_headless(true);
        let temporary_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../.tmp/lan-perf-20261018");
        std::fs::create_dir_all(&temporary_root).unwrap();
        let dir = tempfile::Builder::new().prefix("core-limit-").tempdir_in(temporary_root).unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("data")), 29065).unwrap();
        {
            let store = host.store();
            let db = store.lock();
            for index in 0..501 {
                db.insert_lan_message(&format!("message-{index:03}"), "dm:fixture", &json!({"id":index}).to_string()).unwrap();
            }
        }
        for (limit, count) in [(None, 200), (Some(0), 1), (Some(-1), 1), (Some(501), 500)] {
            let mut params = json!({"conversationId":"dm:fixture"});
            if let Some(limit) = limit { params["limit"] = json!(limit); }
            let result = host.lan_messages(&params).unwrap();
            let items = result.as_array().unwrap();
            assert_eq!(items.len(), count);
            assert_eq!(items.last().unwrap()["id"], 500);
            assert_eq!(items.first().unwrap()["id"], 501 - count);
        }
    }

    #[test]
    fn lan_read_clears_incoming_unread() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let code = host.lan_status()["pairingCode"]["code"].as_str().unwrap().to_string();
        let pair = host
            .lan_accept_inbound_pair(&json!({
                "deviceId": "peerRead",
                "alias": "desk",
                "baseUrl": "https://10.0.0.3:29766",
                "certificateFingerprint": "d".repeat(64),
                "pairingCode": code,
                "tokenForReceiver": crate::lan::create_token(),
            }))
            .unwrap();
        let token = pair["tokenForRequester"].as_str().unwrap().to_string();
        host.lan_authenticate(Some("peerRead"), Some(&format!("Bearer {token}")))
            .unwrap();
        host.lan_receive_text(
            "peerRead",
            &json!({
                "id": "unread1",
                "senderDeviceId": "peerRead",
                "senderAlias": "desk",
                "targetKind": "direct",
                "text": "please-read",
                "createdAtUtc": Utc::now(),
                "attachments": [],
            }),
        )
        .unwrap();
        let conv = host.lan_conversations();
        let dm = conv
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["id"] == "dm:peerRead")
            .unwrap();
        assert_eq!(dm["unreadCount"], 1);
        assert_eq!(dm["lastMessage"], "please-read");
        host.lan_read(&json!({ "conversationId": "dm:peerRead" })).unwrap();
        let after = host.lan_conversations();
        let dm_after = after
            .as_array()
            .unwrap()
            .iter()
            .find(|item| item["id"] == "dm:peerRead")
            .unwrap();
        assert_eq!(dm_after["unreadCount"], 0);
        host.lan_forget(&json!({ "deviceId": "peerRead" })).unwrap();
        let leftover = host.lan_conversations();
        assert!(
            leftover
                .as_array()
                .unwrap()
                .iter()
                .any(|item| item["id"] == "dm:peerRead" && item["title"] == "desk"),
            "{leftover}"
        );
    }

