    #[test]
    fn health_and_app_info_match_csharp_keys() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let health = host.health();
        assert_eq!(health["ok"], true);
        assert_eq!(health["service"], crate::paths::HEALTH_SERVICE_ID);
        assert_eq!(health["processId"], std::process::id());
        assert!(health.get("processElevated").is_some());
        assert!(health.get("runAsAdministrator").is_some());
        assert!(health.get("runAsAdministratorEffective").is_some());
        assert!(health.get("coldStartElevationSuppressed").is_some());
        assert!(health.get("isDebugConfiguration").is_some());
        let ping = host.ping();
        assert_eq!(ping["bridge"], true);
        assert_eq!(ping["apiPort"], 28965);
        assert_eq!(ping["rpcUrl"], "http://127.0.0.1:28965/api/rpc");
        #[cfg(debug_assertions)]
        assert_eq!(
            ping["legacyDevRpcPort"],
            crate::paths::resolve_legacy_dev_rpc_port(28965)
        );
        #[cfg(not(debug_assertions))]
        assert!(ping.get("legacyDevRpcPort").is_none());
        let info = host.app_info();
        assert_eq!(info["clipHost"]["runtime"], "tauri+rust");
        assert_eq!(info["quicker"]["connected"], false);
        assert_eq!(info["quicker"]["pipes"][0], crate::paths::VERB_RPC_PIPE_V1);
        assert_eq!(info["quicker"]["pipe"], crate::paths::VERB_RPC_PIPE_V1);
        assert_eq!(
            info["quicker"]["hint"],
            "Start IntelliTools in Quicker and wait for the verb-pipe connection."
        );
        assert_eq!(
            host.quicker_status()["hint"],
            "Start IntelliTools in Quicker so the Quicker-side pipe RPC session can connect."
        );
        assert!(host.quicker_status().get("listening").is_none());
        assert!(host.quicker_status().get("optional").is_none());
        assert!(info["quicker"].get("listening").is_none());
        assert!(info["quicker"].get("optional").is_none());
        assert_ne!(info["quicker"]["pipes"][0], crate::paths::CSHARP_VERB_RPC_PIPE_V1);
        let probe = host.health_cloud_sync_probe(false);
        assert_eq!(probe["rpcConnected"], false);
        assert_eq!(probe["ok"], false);
        let paths = host.data_paths();
        assert_eq!(paths["envOverrideActive"], std::env::var(crate::paths::DATA_ROOT_ENV).is_ok());
        assert!(paths.get("sidecarFilePath").is_some());
        assert!(paths.get("sidecarOverridePath").is_some());
        assert!(paths["isolatedFromCsharp"].as_bool().unwrap());
        let restart = host.restart(true);
        assert_eq!(restart["ok"], true);
        assert_eq!(restart["restart"], false);
        let missing = host.latest_log().unwrap_err();
        assert!(missing.starts_with("未找到日志文件。目录："), "{missing}");
        std::fs::write(
            host.data_root().join("logs").join("cloud-sync.jsonl"),
            "not-a-host-log",
        )
        .unwrap();
        let still_missing = host.latest_log().unwrap_err();
        assert!(still_missing.starts_with("未找到日志文件。目录："), "{still_missing}");
        std::fs::write(
            host.data_root().join("logs").join("cliphost-tauri.log"),
            "host-log-body",
        )
        .unwrap();
        let latest = host.latest_log().unwrap();
        assert_eq!(latest["truncated"], false);
        let text = latest["text"].as_str().unwrap();
        assert!(text.contains("// Log file:"));
        assert!(text.contains("// Exported:"));
        assert!(text.contains("host-log-body"));
    }

    #[test]
    fn execute_verb_clip_hide_and_collect_text() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let hide = host.execute_verb("clip hide").unwrap();
        assert_eq!(hide["ok"], true);
        let setting = host.execute_verb("setting clip").unwrap();
        assert_eq!(setting["route"], "/main/settings/clip");
        assert_eq!(host.take_pending_nav("main").as_deref(), Some("/main/settings/clip"));
        // Valid lifecycle commands for different windows remain in their original order.
        assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::Hide)));
        assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::ShowMain)));
        assert!(host.take_chrome_command().is_none());
        host.favor_folder_create(&json!({ "title": "面板" })).unwrap();
        let panel = host.execute_verb("panel show").unwrap();
        assert_eq!(panel["shown"], true);
        assert_eq!(host.inner.lock().ui.panel_visible, true);
        let hidden = host.execute_verb("panel hide").unwrap();
        assert_eq!(hidden["visible"], false);
        assert_eq!(host.inner.lock().ui.panel_visible, false);
        let collect = host.execute_verb(r#"collect text --title "草稿" --data hello"#).unwrap();
        assert_eq!(collect["ok"], true);
        let draft_id = collect["draftId"].as_str().unwrap();
        let expected_nav = format!("/favorites/new?draftId={draft_id}");
        assert_eq!(host.take_pending_nav("clipboard").as_deref(), Some(expected_nav.as_str()));
        let shown = host.collect_get(&json!({ "draftId": draft_id })).unwrap();
        assert_eq!(shown["detail"]["title"], "草稿");
        let menu = host.execute_verb("menu favor").unwrap();
        assert_eq!(menu["ok"], true);
        assert_eq!(menu["executed"], true);
        assert_eq!(host.super_menu_state_detail()["visible"], true);
        let bare_menu = host.execute_verb("menu").unwrap();
        assert_eq!(bare_menu["ok"], true);
        assert_eq!(bare_menu["action"], "favor");
        let bad_menu = host.execute_verb("menu nope").unwrap();
        assert_eq!(bad_menu["ok"], true);
        assert_eq!(bad_menu["executed"], false);
        let menu_toast = host.take_toast_push().expect("menu parse toast");
        assert!(
            menu_toast["message"]
                .as_str()
                .unwrap()
                .contains("菜单命令参数无效"),
            "{menu_toast}"
        );
        assert_eq!(host.execute_verb("panel nope").unwrap()["ok"], true);
        let paste = host.execute_verb("paste -n 1").unwrap();
        assert_eq!(paste["ok"], true);
        assert_eq!(paste["executed"], false);
        let unknown = host.execute_verb("nope line").unwrap();
        assert_eq!(unknown["ok"], true);
        assert!(unknown.get("stub").is_none());
        let blank_setting = host.execute_verb("setting").unwrap();
        assert_eq!(blank_setting["ok"], true);
        assert!(blank_setting.get("stub").is_none());
        let icon = host.execute_verb("collect icon").unwrap();
        assert_eq!(icon["ok"], true);
        let icon_toast = host.take_toast_push().expect("collect icon toast");
        assert_eq!(
            icon_toast["message"],
            "图标收藏请在 Quicker 插件（IntelliTools）内执行 collect icon。"
        );
        assert_eq!(icon_toast["title"], "collect icon");
        assert_eq!(icon_toast["kind"], "info");
        let file = host.execute_verb("collect file").unwrap();
        assert_eq!(file["ok"], true);
        let file_toast = host.take_toast_push().expect("collect file toast");
        assert_eq!(file_toast["message"], "collect file 尚未实现。");
        assert_eq!(file_toast["title"], "collect file");
    }

    #[test]
    fn paste_verb_index_matches_csharp_items_by_time() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let t0 = Utc::now();
        let mut oldest = ClipRecord::new_text("oldest-pinned", "paste");
        oldest.create_time = t0;
        oldest.is_top = true;
        let mut mid = ClipRecord::new_text("mid", "paste");
        mid.create_time = t0 + chrono::Duration::seconds(1);
        let mut newest = ClipRecord::new_text("newest", "paste");
        newest.create_time = t0 + chrono::Duration::seconds(2);
        let oldest_id = oldest.id.clone();
        let newest_id = newest.id.clone();
        let store = host.inner.lock().store.clone();
        store.lock().insert_clip(&oldest, true).unwrap();
        store.lock().insert_clip(&mid, true).unwrap();
        store.lock().insert_clip(&newest, true).unwrap();
        let by_time = host.execute_verb("paste -n 1").unwrap();
        assert_eq!(by_time["id"], newest_id);
        let pinned_first = host.execute_verb("paste -n 1 --pinned-first").unwrap();
        assert_eq!(pinned_first["id"], oldest_id);
        let selected = host.execute_verb("paste --pinned-first").unwrap();
        assert_eq!(selected["id"], newest_id);
        assert_eq!(host.execute_verb("paste -n 99").unwrap()["executed"], false);
    }

    #[test]
    fn clip_start_stop_verb_is_live_only_like_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.config_update(&json!({ "showCopyMessage": false })).unwrap();
        let path = host.inner.lock().paths.configs.join("ClipConfig.json");
        let before: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        assert!(
            before.get("clipMonitorOn").is_none(),
            "C# ClipConfig.json has no ClipMonitorOn: {before}"
        );
        let stop = host.execute_verb("clip stop").unwrap();
        assert_eq!(stop["ok"], true);
        assert_eq!(stop["clipMonitorOn"], false);
        assert_eq!(host.inner.lock().config.clip_monitor_on, false);
        assert!(!host.inner.lock().monitor_on.load(Ordering::Relaxed));
        let after_stop: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        assert_eq!(after_stop, before, "C# start/stop must not rewrite ClipConfig.json");
        let start = host.execute_verb("clip start").unwrap();
        assert_eq!(start["clipMonitorOn"], true);
        assert!(host.inner.lock().monitor_on.load(Ordering::Relaxed));
        let after_start: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        assert_eq!(after_start, before);
        let toggled = host.execute_verb("clip start_or_stop").unwrap();
        assert_eq!(toggled["clipMonitorOn"], false);
        let after_toggle: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        assert_eq!(after_toggle, before);
    }

