    #[test]
    fn clip_pin_fold_and_favor_folder_open_panel() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let shown = host.execute_verb("clip show -s -f --loc m2").unwrap();
        assert_eq!(shown["ok"], true);
        assert_eq!(shown["fold"], true);
        assert_eq!(host.inner.lock().window_pinned, true);
        // C# `ShowOrHideWindow(hide: false)` always expands (`IsWindowToggle = false`).
        // `--fold` only changes the hide-path of toggle/show_or_hide.
        assert_eq!(host.inner.lock().is_collapsed, false);
        assert_eq!(host.take_pending_nav("clipboard").as_deref(), Some("/clipboard"));
        assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::Show)));
        assert!(host.take_chrome_command().is_none());
        let folder = host.favor_folder_create(&json!({ "name": "panel-root" })).unwrap();
        let id = folder["id"].as_str().unwrap();
        let favor = host.execute_verb(&format!("favor show {id}")).unwrap();
        assert_eq!(favor["tab"], "panel");
        assert_eq!(host.inner.lock().ui.panel_visible, true);
        assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::ShowPanel)));
        let leaf = host.favor_add_text_items(&json!({ "text": "not-folder" })).unwrap();
        let leaf_id = leaf["createdIds"][0].as_str().unwrap();
        let skipped = host.execute_verb(&format!("favor show {leaf_id}")).unwrap();
        assert_eq!(skipped["skipped"], true);
    }

