    #[test]
    fn runtime_alignment_pin_change_saves_without_move_and_survives_main_reopen() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let paths = AppPaths::from_data_root(dir.path().join("BetterClipTauri"));
        let host = HostState::open(paths.clone(), 28965).unwrap();
        for (label, name, width, height) in [
            ("clipboard", crate::window_state::CLIP_WINDOW, 420.0, 760.0),
            ("panel", crate::window_state::PANEL_WINDOW, 420.0, 520.0),
            ("main", crate::window_state::MAIN_WINDOW, 760.0, 580.0),
        ] {
            // Native creation captures geometry once, then successful flush
            // clears dirty entries. A later pin click has no geometry event.
            host.remember_host_window_rect(label, 20.0, 30.0, width, height);
            host.window_states.flush(&paths.data_root, true).unwrap();
            host.apply_window_action_for("setPinned", true, label);
            assert_eq!(host.saved_host_window_size("main"),
                if label == "main" { Some((760, 580)) } else { None });
            host.window_states.flush(&paths.data_root, true).unwrap();
            let saved = crate::window_state::load(&paths.data_root, name).unwrap();
            assert_eq!(crate::window_state::property_bool(&saved, "IsPinned"), Some(true));
            assert_eq!((saved.left, saved.top, saved.width, saved.height), (20.0, 30.0, width, height));
        }
        // ShowMain only reads the latest saved size; stale startup properties
        // must not be reapplied while the user is changing the current pin.
        host.apply_window_action_for("setPinned", false, "main");
        assert_eq!(host.saved_host_window_size("main"), Some((760, 580)));
        assert!(!host.inner.lock().ui.main_pinned);
        host.window_states.flush(&paths.data_root, true).unwrap();
        let reopened = HostState::open(paths.clone(), 28965).unwrap();
        reopened.restored_host_window_rect("panel").unwrap();
        reopened.restored_host_window_rect("main").unwrap();
        assert!(reopened.inner.lock().ui.panel_pinned);
        assert!(!reopened.inner.lock().ui.main_pinned);
    }

    #[test]
    fn runtime_alignment_pin_and_geometry_update_during_flush_keep_latest_state() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.remember_host_window_rect("main", 20.0, 30.0, 760.0, 580.0);
        let name = crate::window_state::MAIN_WINDOW;
        host.window_states.flush_with(Instant::now(), true, |saved| {
            assert_eq!(crate::window_state::property_bool(saved, "IsPinned"), Some(false));
            host.apply_window_action_for("setPinned", true, "main");
            host.remember_host_window_rect("main", 40.0, 50.0, 800.0, 600.0);
            Ok(())
        }).unwrap();
        let latest = host.window_states.latest(name).unwrap();
        assert_eq!((latest.left, latest.top, latest.width, latest.height), (40.0, 50.0, 800.0, 600.0));
        assert_eq!(crate::window_state::property_bool(&latest, "IsPinned"), Some(true));
        let mut writes = 0;
        host.window_states.flush_with(Instant::now(), true, |saved| {
            writes += 1;
            assert_eq!(saved, &latest);
            Ok(())
        }).unwrap();
        assert_eq!(writes, 1, "in-flight older save cannot clear the new property/geometry update");
        assert_eq!(host.window_states.latest(name), Some(latest));
    }

