    #[test]
    fn deferred_clear_matches_csharp_dto_and_hides_from_search() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let session = host.create_session();
        host.add_text(&json!({ "text": "keep-me" })).unwrap();
        host.add_text(&json!({ "text": "drop-me" })).unwrap();
        let scheduled = host.clear_all(false).unwrap();
        assert!(!scheduled["clearId"].as_str().unwrap().is_empty());
        assert_eq!(scheduled["mode"], "all");
        assert_eq!(scheduled["itemCount"], 2);
        assert_eq!(scheduled["delayMs"], 5000);
        assert!(scheduled["expiresAtUnixMs"].as_i64().unwrap() > 0);
        let listed = host
            .search_items(&json!({
                "webSessionId": session["sessionId"],
                "query": "",
                "take": 20
            }))
            .unwrap();
        assert_eq!(listed["total"], 0);
        let pending = host.clear_pending();
        assert_eq!(pending["clearId"], scheduled["clearId"]);
        assert_eq!(pending["expiresAtUnixMs"], scheduled["expiresAtUnixMs"]);
        let events = host.drain_push_events();
        assert!(events.iter().any(|(name, data)| {
            name == "clipChanged"
                && data.get("ts").and_then(|v| v.as_i64()).is_some()
                && data.get("reason").is_none()
                && data.get("op").is_none()
        }));
        assert_eq!(
            host.clear_cancel(&json!({ "clearId": "other" })).unwrap_err(),
            "Operation failed."
        );
        let cancelled = host.clear_cancel(&json!({ "clearId": scheduled["clearId"] })).unwrap();
        assert_eq!(cancelled["ok"], true);
        assert_eq!(
            host.clear_cancel(&json!({ "clearId": scheduled["clearId"] })).unwrap_err(),
            "Operation failed."
        );
        let listed = host
            .search_items(&json!({
                "webSessionId": session["sessionId"],
                "query": "",
                "take": 20
            }))
            .unwrap();
        assert_eq!(listed["total"], 2);
    }

    #[test]
    fn distinct_normalizes_plain_text_and_preserves_html_payloads() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.add_text(&json!({ "text": "Hello\r\n" })).unwrap();
        host.add_text(&json!({ "text": "Hello" })).unwrap();
        let mut html = ClipRecord::new_text("Hello", "chrome");
        html.kind = ClipKind::HtmlClipItem;
        html.html_data = Some("<p>Hello</p>".into());
        host.inner.lock().store.lock().insert_clip(&html, true).unwrap();
        let result = host.distinct(&json!({ "scope": "all" })).unwrap();
        assert_eq!(result["count"], 1);
        assert_eq!(host.inner.lock().store.lock().get_clip(&html.id).unwrap().html_data, html.html_data);
        let extra = ClipRecord::new_text("Hello", "chrome");
        host.inner.lock().store.lock().insert_clip(&extra, true).unwrap();
        assert_eq!(
            host.distinct(&json!({ "scope": "selected", "ids": [] })).unwrap()["count"],
            1
        );
    }

