    #[test]
    fn slow_menu_session_does_not_block_search_pin_or_close() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let item = host.add_text(&json!({"text": "menu responsiveness"})).unwrap();
        let web_session = host.create_session();
        let id = item["createdIds"][0].as_str().unwrap();
        let menu = host.menu_create_session("text");
        let session = menu["sessionId"].as_str().unwrap().to_string();
        let worker = host.clone();
        let worker_session = session.clone();
        let (entered, started) = mpsc::channel();
        let (release, blocked) = mpsc::channel();
        let loader = thread::spawn(move || worker.menus.with_session(&worker_session, |_| {
            entered.send(()).unwrap();
            blocked.recv_timeout(Duration::from_secs(10)).unwrap();
            Ok(())
        }));
        started.recv_timeout(Duration::from_secs(5)).unwrap();
        host.search_items(&json!({"webSessionId": web_session["sessionId"], "take": 10})).unwrap();
        assert!(host.toggle_pin(&json!({"id": id})).is_ok());
        assert!(host.menu_close_session(&session));
        assert!(!host.inner.lock().super_menu.visible);
        assert!(host.menu_sessions()["sessions"].as_array().unwrap().is_empty());
        release.send(()).unwrap();
        assert_eq!(loader.join().unwrap().unwrap_err(), "Session not found");
    }

    #[test]
    fn late_menu_root_cannot_reopen_after_close_or_replace_a_newer_root() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        for replace in [false, true] {
            let mut newer_id = None;
            let old = host.menu_create_session_loading("favor", "", 0, 0, |host, _| {
                assert!(host.inner.try_lock().is_some());
                if replace {
                    let newer = host.menu_create_session("text");
                    newer_id = Some(newer["sessionId"].as_str().unwrap().to_string());
                } else {
                    host.super_menu_hide_session();
                }
                crate::menu_api::MenuBuildContext::default()
            });
            assert!(host.menu_nodes(old["sessionId"].as_str().unwrap(), "root").is_err());
            let inner = host.inner.lock();
            assert_eq!(inner.super_menu.visible, replace);
            assert_eq!(inner.super_menu.session_id, newer_id);
            assert_eq!(host.menu_sessions()["sessions"].as_array().unwrap().len(), usize::from(replace));
        }
    }

