    #[test]
    fn file_menu_settings_save_failure_keeps_paths_and_display_options_together() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let paths = AppPaths::from_data_root(dir.path().join("BetterClipTauri"));
        let config = paths.configs.join("FileMenuConfig.json");
        let backup = paths.configs.join("FileMenuConfig.saved.json");
        let host = HostState::open(paths.clone(), 28965).unwrap();
        host.settings_form_update(&json!({"configId":"menu_file","values":{"Files":"before","ShowExtension":true}})).unwrap();
        let before_paths = host.file_menu_snapshot();
        let before_form = host.settings_form_get(&json!({"configId":"menu_file"})).unwrap();
        let before_bytes = std::fs::read(&config).unwrap();
        std::fs::rename(&config, &backup).unwrap();
        std::fs::create_dir(&config).unwrap();
        let update = json!({"configId":"menu_file","values":{"Files":"after","ShowExtension":false}});
        assert!(host.settings_form_update(&update).is_err());
        assert_eq!(host.file_menu_snapshot(), before_paths);
        assert_eq!(host.settings_form_get(&json!({"configId":"menu_file"})).unwrap(), before_form);
        assert_eq!(std::fs::read(&backup).unwrap(), before_bytes);
        std::fs::remove_dir(&config).unwrap();
        std::fs::rename(&backup, &config).unwrap();
        host.settings_form_update(&update).unwrap();
        let saved: Value = serde_json::from_slice(&std::fs::read(&config).unwrap()).unwrap();
        assert_eq!(saved["Files"], "after");
        assert_eq!(saved["ShowExtension"], false);
        drop(host);
        let reopened = HostState::open(paths, 28965).unwrap();
        assert_eq!(reopened.file_menu_snapshot()["paths"], json!(["after"]));
        assert!(!reopened.inner.lock().extras.file_menu.show_extension);
    }

    #[test]
    fn file_menu_pending_save_leaves_window_search_and_snapshots_responsive() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.file_menu_replace(vec!["committed".into()]).unwrap();
        let web_session = host.create_session();
        host.add_text(&json!({"text":"while saving"})).unwrap();
        let (entered_tx, entered_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let saving = host.clone();
        let writer = thread::spawn(move || saving.file_menu_update_saving(
            |paths, _| paths.try_add("pending"),
            |paths, settings, path| {
                entered_tx.send(()).unwrap();
                release_rx.recv_timeout(Duration::from_secs(15)).unwrap();
                crate::file_menu::save_config(paths, settings, path)
            },
        ));
        entered_rx.recv_timeout(Duration::from_secs(5)).expect("save did not start");
        let (ready_tx, ready_rx) = mpsc::channel();
        let responsive = host.clone();
        let reader = thread::spawn(move || {
            let pinned = responsive.apply_window_action("setPinned", true);
            let search = responsive.search_items(&json!({"query":"while saving", "webSessionId":web_session["sessionId"]}));
            ready_tx.send((pinned, search, responsive.file_menu_snapshot())).unwrap();
        });
        let result = ready_rx.recv_timeout(Duration::from_secs(5));
        release_tx.send(()).unwrap();
        let saved = writer.join().unwrap().unwrap();
        reader.join().unwrap();
        let (pinned, search, snapshot) = result.expect("file-menu save blocked host operations");
        assert_eq!(pinned["isPinned"], true);
        assert_eq!(search.unwrap()["total"], 1);
        assert_eq!(snapshot["paths"], json!(["committed"]));
        assert!(saved.0);
        assert_eq!(host.file_menu_snapshot()["paths"], json!(["committed", "pending"]));
    }

    #[test]
    fn file_menu_concurrent_adds_preserve_all_committed_paths() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let data_root = dir.path().join("BetterClipTauri");
        let host = HostState::open(AppPaths::from_data_root(data_root.clone()), 28965).unwrap();
        let paths: Vec<_> = (0..8).map(|i| {
            let path = dir.path().join(format!("folder-{i}"));
            std::fs::create_dir(&path).unwrap();
            path.to_string_lossy().into_owned()
        }).collect();
        let gate = Arc::new(std::sync::Barrier::new(paths.len() + 1));
        let writers: Vec<_> = paths.iter().map(|path| {
            let host = host.clone();
            let gate = gate.clone();
            let path = path.clone();
            thread::spawn(move || -> Result<Value, String> {
                gate.wait();
                let added = host.file_menu_add(&path)?;
                host.settings_form_update(&json!({"configId":"menu_file","values":{"ShowHiddenFiles":true}}))?;
                Ok(added)
            })
        }).collect();
        gate.wait();
        for writer in writers { assert_eq!(writer.join().unwrap().unwrap()["ok"], true); }
        let snapshot = host.file_menu_snapshot();
        let saved = snapshot["paths"].as_array().unwrap();
        assert_eq!(saved.len(), paths.len());
        for path in paths { assert!(saved.contains(&json!(path))); }
        drop(host);
        let reopened = HostState::open(AppPaths::from_data_root(data_root), 28965).unwrap();
        assert_eq!(reopened.file_menu_snapshot(), snapshot);
        assert!(reopened.inner.lock().extras.file_menu.show_hidden_files);
    }

