        let config = paths.configs.join("FileMenuConfig.json");
        let backup = paths.configs.join("FileMenuConfig.saved.json");
        let host = HostState::open(paths, 28965).unwrap();
        let _clipboard = crate::clipboard::install_test_snapshot(ClipboardSnapshot {
            text: Some(dir.path().to_string_lossy().into_owned()),
            ..ClipboardSnapshot::default()
        });
        let menu = host.menu_create_session_loading("file", "", 0, 0, |host, files| {
            host.menu_build_context_with("file", files, |ctx| {
                ctx.clipboard_path = Some(dir.path().to_string_lossy().into_owned());
            })
        });
        let session = menu["sessionId"].as_str().unwrap();
        let add = menu["root"]["items"].as_array().unwrap().iter()
            .find(|item| item["role"] == "file-add-clipboard").unwrap()["id"].as_str().unwrap();
