    #[test]
    fn keyboard_poll_hint_dispatches_without_waiting_for_busy_host() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let worker = host.clone();
        let (send, receive) = std::sync::mpsc::channel();
        let guard = host.inner.lock();
        let thread = std::thread::spawn(move || {
            let _ = send.send(worker.needs_keyboard_work_poll());
        });
        let result = receive.recv_timeout(Duration::from_secs(2));
        drop(guard);
        thread.join().unwrap();
        assert_eq!(result.unwrap(), true, "a busy host must be delegated to the blocking worker");
    }

    #[test]
    fn maintenance_deadlines_retire_when_cleanup_and_clear_are_finished() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        {
            let mut inner = host.inner.lock();
            inner.window_visible = false;
            inner.cleanup_pending = false;
        }
        assert_eq!(host.maintenance_delay(), None);
        host.trigger_cleanup();
        assert!(host.maintenance_delay().is_some_and(|delay| delay <= CLEANUP_SAMPLE));
        host.inner.lock().last_cleanup_at = Instant::now() - CLEANUP_SAMPLE;
        assert_eq!(host.maintenance_delay(), Some(Duration::ZERO));
        host.poll_history_cleanup();
        assert_eq!(host.maintenance_delay(), None);

        host.add_text(&json!({"text":"maintenance deadline fixture"})).unwrap();
        host.inner.lock().cleanup_pending = false;
        let pending = host.clear_all(true).unwrap();
        assert!(host.maintenance_delay().is_some_and(|delay| delay <= Duration::from_millis(DEFERRED_CLEAR_DELAY_MS as u64)));
        host.clear_cancel(&json!({"clearId":pending["clearId"]})).unwrap();
        assert_eq!(host.maintenance_delay(), None);

        let ids = vec!["viewport-only-fixture".to_owned()];
        host.report_visible_file_history(&ids);
        assert_eq!(host.maintenance_delay(), None, "hidden viewport work does not schedule a timer");
        host.inner.lock().window_visible = true;
        assert_eq!(host.maintenance_delay(), Some(Duration::ZERO));
        host.report_visible_file_history(&[]);
        assert_eq!(host.maintenance_delay(), None);
    }

    #[test]
    fn idle_keyboard_wait_has_no_deadline_and_busy_input_wakes_without_locking() {
        use std::future::Future;
        use std::task::{Context, Waker};
        let _input = crate::hooks::input_globals_test::exclusive();
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        assert_eq!(host.keyboard_work_delay(), None);
        let wakeup = host.keyboard_work_notifier();
        let worker = host.clone();
        let (send, receive) = std::sync::mpsc::channel();
        let guard = host.inner.lock();
        let thread = std::thread::spawn(move || {
            // This is the production input path, while another thread owns
            // HostInner. Neither looking up the notifier nor input may block.
            let same = Arc::ptr_eq(&worker.keyboard_work_notifier(), &worker.keyboard_wakeup);
            let consumed = worker.dispatch_low_level_wheel(120, 0, 0);
            let _ = send.send((same, consumed));
        });
        let result = receive.recv_timeout(Duration::from_secs(2));
        drop(guard);
        thread.join().unwrap();
        assert_eq!(result.unwrap(), (true, false));
        let mut context = Context::from_waker(Waker::noop());
        assert!(std::pin::pin!(wakeup.notified()).as_mut().poll(&mut context).is_ready());
        assert!(host.needs_keyboard_work_poll());
    }

    #[test]
    fn native_clipboard_overlay_sync_reconciles_live_guards_without_repeated_input_retirement() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.apply_window_action("setSpaModalOpen", false);
        host.apply_window_action("setSpaOverlayOpen", false);
        let initial_epoch = host.inner.lock().chrome_input_epochs[0].list;
        host.sync_native_clipboard_overlay(false, true);
        let first_escape = host.inner.lock().clipboard_escape_session;
        assert_eq!(host.inner.lock().chrome_input_epochs[0].list, initial_epoch + 1);
        host.sync_native_clipboard_overlay(false, true);
        assert_eq!(host.inner.lock().chrome_input_epochs[0].list, initial_epoch + 1);
        assert_eq!(host.inner.lock().clipboard_escape_session, first_escape);

        // Core lifecycle paths can clear the guard independently of the view.
        host.apply_window_action("setSpaOverlayOpen", false);
        host.sync_native_clipboard_overlay(false, true);
        assert!(host.inner.lock().spa_overlay_open);
        assert_eq!(host.inner.lock().chrome_input_epochs[0].list, initial_epoch + 2);
        assert_ne!(host.inner.lock().clipboard_escape_session, first_escape);

        host.sync_native_clipboard_overlay(true, true);
        assert!(host.inner.lock().spa_modal_open);
        assert!(host.inner.lock().has_open_host_overlay);
        let modal_epoch = host.inner.lock().chrome_input_epochs[0].list;
        host.sync_native_clipboard_overlay(true, true);
        assert_eq!(host.inner.lock().chrome_input_epochs[0].list, modal_epoch);
        host.sync_native_clipboard_overlay(false, false);
        assert!(!host.inner.lock().spa_overlay_open);
        assert!(host.inner.lock().spa_modal_open, "the existing modal owner releases its own guard");
        assert!(host.inner.lock().has_open_host_overlay);
        host.apply_window_action("setSpaModalOpen", false);
        assert!(!host.hide_snapshot().spa_modal_open);
    }

    #[test]
    fn visible_spa_overlay_blocks_auto_hide_and_releases_after_close() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        for behavior in ["Hide", "Fold", "EdgeHide"] {
            {
                let mut inner = host.inner.lock();
                inner.config.dismiss_behavior = behavior.into();
                inner.window_visible = true;
                inner.window_pinned = false;
                inner.no_focus_session_active = true;
                inner.has_host_fake_focus = false;
                inner.pointer_in_host = false;
                inner.is_layout_busy = false;
                inner.expand_grace_until_ms = 0;
                inner.is_collapsed = false;
                inner.foreground_is_host_related = false;
            }
            host.apply_window_action_for("setSpaOverlayOpen", true, "clipboard");
            for trigger in [HostHideTrigger::Poll, HostHideTrigger::Pointer,
                HostHideTrigger::OutsideClick, HostHideTrigger::ForegroundChange] {
                let decision = evaluate(trigger, &host.hide_snapshot());
                assert_eq!(decision.window_action, crate::hide_policy::HostDismissAction::None,
                    "{behavior}/{trigger:?}: a visible editor/menu must protect its host");
                assert!(decision.path.iter().any(|p| p == "spa-modal"));
            }
            host.apply_window_action_for("setSpaOverlayOpen", false, "clipboard");
            let decision = evaluate(HostHideTrigger::OutsideClick, &host.hide_snapshot());
            assert_ne!(decision.window_action, crate::hide_policy::HostDismissAction::None,
                "{behavior}: closing the last layer must restore dismiss behavior");
        }
    }

