    #[test]
    fn clipboard_chrome_keyboard_exits_no_focus_session() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let snap = host.hide_snapshot();
        assert!(snap.no_focus_session_active);
        assert!(snap.has_fake_focus);
        while host.take_chrome_command().is_some() {}
        host.chrome_web_action(&json!({
            "kind": "clipboardHostChrome",
            "route": "/clipboard",
            "isClipboardEditing": false,
            "requestHostKeyboardFocus": true,
        }));
        let snap = host.hide_snapshot();
        assert!(!snap.no_focus_session_active);
        assert!(snap.has_fake_focus);
        assert!(snap.visible);
        assert!(host.clipboard_keyboard_focus_allowed());
        assert!(!host.clipboard_no_activate());
        assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::ClipboardKeyboardFocus)));
        // Repeated DOM focusin messages must not repeatedly move native focus.
        host.exit_no_focus_session_for_keyboard();
        assert!(host.take_chrome_command().is_none());
        // Once a real text field owns keyboard input, candidate-selection and
        // composition keys must reach WebView/IME without host navigation.
        for vk in [0x31, 0x0D, 0x20, 0x1B, 0x09, 0x25, 0x26, 0x27, 0x28, 0xE5] {
            for down in [true, false] {
                assert!(!host.dispatch_low_level_key(KeyEvent {
                    vk, down, alt: false, ctrl: false, shift: false, win: false, now_ms: 1,
                }), "text input key {vk:x} was consumed");
            }
        }
        assert!(host.hide_snapshot().visible);
        assert!(host.take_chrome_command().is_none());
        host.window_hide();
        assert!(!host.clipboard_keyboard_focus_allowed());
        host.request_show();
        assert!(!host.clipboard_keyboard_focus_allowed());
        assert!(host.clipboard_no_activate());
    }

    #[test]
    fn hide_ends_no_focus_session_and_show_restores_it() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        while host.take_chrome_command().is_some() {}
        let _ = host.window_hide();
        let snap = host.hide_snapshot();
        assert!(!snap.visible);
        assert!(!snap.no_focus_session_active);
        assert!(!snap.has_fake_focus);
        host.request_show();
        let snap = host.hide_snapshot();
        assert!(snap.visible);
        assert!(snap.no_focus_session_active);
        assert!(snap.has_fake_focus);
    }

    #[test]
    fn quick_paste_hook_defers_work_and_preserves_fast_trigger_order() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        for text in ["older", "newer"] { host.add_text(&json!({ "text": text })).unwrap(); }
        host.window_hide();
        let key = |vk, down, alt, now_ms| KeyEvent { vk, down, alt, ctrl: false, shift: false, win: false, now_ms };
        for event in [key(0xc0, true, true, 1), key(0xc0, false, true, 2), key(0xc0, true, true, 3)] {
            assert!(host.dispatch_low_level_key(event));
        }
        assert!(!host.qp_debug_status()["overlayVisible"].as_bool().unwrap());
        assert!(host.needs_keyboard_work_poll(), "queued work wakes polling even with all windows hidden");
        host.poll_quick_paste();
        assert_eq!(host.inner.lock().qp.active_index, 1, "second press advances only once");
        let id = host.inner.lock().qp.items[1].id.clone();
        assert_eq!(host.qp_web_action(&json!({ "action": "placementReady" }))["ok"], true);

        let calls = Arc::new(AtomicUsize::new(0));
        let seen = calls.clone();
        host.set_clipboard_ui_runner(move |job| {
            seen.fetch_add(1, Ordering::Relaxed);
            job()
        });
        assert!(!host.dispatch_low_level_key(key(0x12, false, false, 4)), "Alt-up must pass through");
        assert_eq!(calls.load(Ordering::Relaxed), 0, "hook must not wait for clipboard/UI execution");
        host.poll_quick_paste();
        assert_eq!(calls.load(Ordering::Relaxed), 1);
        assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 1);
    }

    #[test]
    fn quick_paste_queued_commit_preserves_next_chord_and_early_release() {
        crate::clipboard::force_headless(true);
        for armed in [false, true] {
            let dir = tempdir().unwrap();
            let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
            let id = host.add_text(&json!({ "text": "two separate chords" })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
            let key = |vk, down, alt, now_ms| KeyEvent { vk, down, alt, ctrl: false, shift: false, win: false, now_ms };
            assert!(host.dispatch_low_level_key(key(0xc0, true, true, 1)));
            host.poll_quick_paste();
            host.qp_web_action(&json!({ "action": "placementReady" }));
            if armed {
                assert_eq!(host.qp_web_action(&json!({ "action": "armedAction", "itemId": id,
                    "armedKind": "simulate" }))["ok"], true);
            }
            assert!(host.dispatch_low_level_key(key(0xc0, false, true, 2)));
            assert!(!host.dispatch_low_level_key(key(0x12, false, false, 3)));
            // The second chord arrives before the first queued paste is executed.
            assert!(host.dispatch_low_level_key(key(0xc0, true, true, 4)));
            assert!(host.dispatch_low_level_key(key(0xc0, false, true, 5)));
            assert!(!host.dispatch_low_level_key(key(0x12, false, false, 6)));
            host.poll_quick_paste();
            assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 2,
                "both queued chords must commit without another placement callback (armed={armed})");
            assert!(!host.inner.lock().qp.machine.commit_when_session_opens);
            assert_eq!(host.qp_web_action(&json!({ "action": "placementReady" }))["reason"], "session-inactive");
            assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 2);
            assert!(!host.inner.lock().qp.overlay_visible);
        }
    }

