            host.dispatch_low_level_key(key(0xc0, true, true, 1));
            host.poll_quick_paste();
            host.qp_web_action(&json!({ "action": "placementReady" }));
            let calls = Arc::new(AtomicUsize::new(0));
            let seen = calls.clone();
            host.set_clipboard_ui_runner(move |job| { seen.fetch_add(1, Ordering::Relaxed); job() });
            let inputs = Arc::new(AtomicUsize::new(0));
            let seen_inputs = inputs.clone();
