    #[test]
    fn execution_alignment_fifo_commit_and_capture_notifications_keep_queue_ownership() {
        use std::sync::{mpsc, atomic::AtomicUsize};
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let id = host.add_text(&json!({ "text": "one commit" })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
        host.arm_fifo_queue(vec![id.clone()]);
        host.qp_begin_session();
        // These notifications are prepared when the copy is observed, before
        // capture/persistence can wait. Neither may cancel a later queue.
        let hub = host.inner.lock().capture.clone();
        let copied = hub.prepare_new_item_notification().unwrap();
        let delayed_copy = hub.prepare_new_item_notification().unwrap();
        let inputs = Arc::new(AtomicUsize::new(0));
        let input_count = inputs.clone();
        host.set_input_runner(move |_| {
            input_count.fetch_add(1, Ordering::Relaxed);
            Ok(()) // Observe dispatch without sending native input.
        });
        let calls = Arc::new(AtomicUsize::new(0));
        let seen = calls.clone();
        let (started_tx, started_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let release_rx = Mutex::new(release_rx);
        host.set_clipboard_ui_runner(move |job| {
            seen.fetch_add(1, Ordering::Relaxed);
            started_tx.send(()).unwrap();
            release_rx.lock().recv_timeout(Duration::from_secs(5)).unwrap();
            job()
        });
        let worker_host = host.clone();
        let worker = std::thread::spawn(move || worker_host.qp_commit(false));
        started_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        host.qp_commit(false);
        assert_eq!(host.inner.lock().fifo_suppress, 1);
        copied();
        assert!(host.inner.lock().fifo.is_none(), "external capture must bypass internal consume suppression");
        host.arm_fifo_queue(vec![id.clone()]);
        let generation = host.inner.lock().fifo_generation;
        delayed_copy();
        assert_eq!(host.inner.lock().fifo_generation, generation, "late notification must not cancel the new queue");
        release_tx.send(()).unwrap();
        worker.join().unwrap();
        assert_eq!(calls.load(Ordering::Relaxed), 1);
        assert_eq!(inputs.load(Ordering::Relaxed), 1, "retired owner-thread job must not dispatch paste");
        assert_eq!(host.fifo_status()["remainingCount"], 1, "completion belongs to previous queue");
        assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 0);
        assert_eq!(host.inner.lock().fifo_suppress, 0);
        // A fresh candidate binds to the new generation and can consume it.
        // The injected owner runner accepts the write without touching Windows.
        host.set_clipboard_ui_runner(|_| Ok(()));
        host.qp_begin_session();
        assert_eq!(host.inner.lock().qp.fifo_generation, Some(generation));
        host.qp_commit(false);
        assert_eq!(host.fifo_status()["remainingCount"], 0);
        assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 1);
        assert_eq!(inputs.load(Ordering::Relaxed), 3);
    }

    #[test]
    fn quick_paste_early_release_commit_drops_host_lock_before_dispatch() {
        use std::sync::mpsc;
        crate::clipboard::force_headless(true);
        for debug in [false, true] {
            let (done_tx, done_rx) = mpsc::channel();
            std::thread::spawn(move || {
                let dir = tempdir().unwrap();
                let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
                let id = host.add_text(&json!({ "text": "fast chord" })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
                host.inner.lock().qp.machine.commit_when_session_opens = true;
                let inner = host.inner.clone();
                host.set_clipboard_ui_runner(move |job| {
                    assert!(inner.try_lock().is_some(), "early commit must release host state before clipboard dispatch");
                    job()
                });
                if debug { host.qp_debug_begin(); } else { host.qp_begin_session(); }
                assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 1);
                done_tx.send(()).unwrap();
            });
            done_rx.recv_timeout(Duration::from_secs(5)).expect("early-release commit must not deadlock");
        }
    }

    #[test]
    fn failed_target_activation_prevents_clipboard_writes_and_usage_across_paste_routes() {
        crate::clipboard::force_headless(true);
        for route in ["history", "plain", "favorite", "quick-paste", "toast-enter", "toast-simulate", "quick-simulate"] {
            let dir = tempdir().unwrap();
            let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
            let id = host.add_text(&json!({ "text": "activation failure fixture" })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
            let favor = host.favor_add_text_items(&json!({ "text": "favorite activation fixture" })).unwrap();
            let favor_id = favor["createdIds"][0].as_str().unwrap();
            host.arm_fifo_queue(vec![id.clone()]);
            host.set_input_runner(|_| Err("target activation rejected".into()));
            host.set_clipboard_ui_runner(|_| panic!("activation must succeed before any clipboard write"));
            let failed = match route {
                "history" => host.paste_item(&json!({ "id": id })).is_err(),
                "plain" => host.paste_plain(&json!({ "ids": [id] })).is_err(),
                "favorite" => host.favor_paste(&json!({ "id": favor_id })).is_err(),
                "quick-paste" => {
                    host.qp_debug_begin();
                    host.qp_commit(true);
                    host.take_toast_push().unwrap()["kind"] == "error"
                }
                "quick-simulate" => {
                    host.qp_debug_begin();
                    host.qp_web_action(&json!({ "action": "simulateText", "itemId": id }))["ok"] == false
                }
                _ => host.toast_web_action(&json!({
                    "action": if route == "toast-enter" { "pasteEnter" } else { "simulateText" },
                    "itemId": id,
                }))["ok"] == false,
            };
            assert!(failed, "{route}");
            assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 0, "{route}");
            assert_eq!(host.fifo_status()["remainingCount"], 1, "{route}");
        }
    }

    #[test]
    fn overlay_simulate_failure_is_visible_and_does_not_record_usage() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        for surface in ["quick-paste", "toast", "armed"] {
            let dir = tempdir().unwrap();
            let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
            let id = host.add_text(&json!({ "text": "simulation failure" })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
            host.arm_fifo_queue(vec![id.clone()]);
            host.qp_debug_begin();
            let calls = Arc::new(AtomicUsize::new(0));
            let seen = calls.clone();
            host.set_input_runner(move |job| {
                if seen.fetch_add(1, Ordering::Relaxed) == 0 { job() }
                else { Err("synthetic input failure".into()) }
            });
            match surface {
                "quick-paste" => assert_eq!(host.qp_web_action(&json!({
                    "action": "simulateText", "itemId": id,
                }))["ok"], false),
                "toast" => assert_eq!(host.toast_web_action(&json!({
                    "action": "simulateText", "itemId": id,
                }))["ok"], false),
                _ => {
                    host.qp_web_action(&json!({ "action": "armedAction", "itemId": id, "armedKind": "simulate" }));
                    host.qp_commit(false);
                }
            }
            assert_eq!(calls.load(Ordering::Relaxed), 2, "{surface}");
            assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, 0);
            assert!(host.inner.lock().qp.last_simulated_text.is_none());
            assert_eq!(host.fifo_status()["remainingCount"], 1);
            let toast = host.take_toast_push().unwrap();
            assert!(toast["message"].as_str().unwrap().contains("synthetic input failure"), "{toast}");
        }
    }

