    #[test]
    fn toast_paste_enter_distinguishes_paste_and_enter_failures() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        for failed_call in [1, 2, 3, 0] {
            let dir = tempdir().unwrap();
            let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
            let id = host.add_text(&json!({ "text": "toast paste enter" })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
            let calls = Arc::new(AtomicUsize::new(0));
            let seen = calls.clone();
            host.set_clipboard_ui_runner(move |job| {
                seen.fetch_add(1, Ordering::Relaxed);
                if failed_call == 1 { Err("synthetic write failure".into()) } else { job() }
            });
            let inputs = Arc::new(AtomicUsize::new(0));
            let seen_inputs = inputs.clone();
            host.set_input_runner(move |job| {
                let call = seen_inputs.fetch_add(1, Ordering::Relaxed) + 1;
                if (failed_call == 2 && call == 3) || (failed_call == 3 && call == 2) {
                    Err("synthetic input failure".into())
                } else { job() }
            });
            let result = host.toast_web_action(&json!({ "action": "pasteEnter", "itemId": id }));
            assert_eq!(result["ok"], failed_call == 0);
            assert_eq!(calls.load(Ordering::Relaxed), 1);
            assert_eq!(inputs.load(Ordering::Relaxed), match failed_call { 1 => 1, 3 => 2, _ => 3 });
            assert_eq!(host.inner.lock().store.lock().get_clip(&id).unwrap().usage_count, if matches!(failed_call, 1 | 3) { 0 } else { 1 });
            if failed_call != 0 {
                assert_eq!(result["reason"], if failed_call == 2 { "enter-failed" } else { "paste-failed" });
                assert_eq!(host.take_toast_push().unwrap()["kind"], "error");
            }
        }
    }

    #[test]
    fn quick_paste_web_messages_arm_simulate_and_wait_for_placement() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.add_text(&json!({ "text": "typed-out" })).unwrap();
        host.qp_begin_session();
        let status = host.qp_debug_status();
        assert_eq!(status["overlayVisible"], true);
        // C# `ScheduleBoundedOverlayReveal` completes immediately for fixed HWND size.
        assert_eq!(status["overlayReady"], true);
        assert_eq!(status["overlayOpacity"], 1.0);
        let detail = host.qp_state_detail();
        let revision = detail["stateRevision"].as_i64().unwrap();
        let item_id = detail["items"][0]["id"].as_str().unwrap().to_string();
        assert!(detail["armedItemId"].is_null());
        assert_eq!(detail["snipasteAvailable"], false);
        assert_eq!(detail["pixPinAvailable"], false);

        let mismatch = host.qp_web_action(&json!({
            "kind": "clipQuickPaste",
            "action": "placementReady",
            "stateRevision": revision + 99
        }));
        assert_eq!(mismatch["ok"], false);
        assert_eq!(host.qp_debug_status()["overlayReady"], true);

        let ready = host.qp_web_action(&json!({
            "kind": "clipQuickPaste",
            "action": "placementReady",
            "stateRevision": revision
        }));
        assert_eq!(ready["ok"], true);
        assert_eq!(host.qp_debug_status()["overlayReady"], true);
        assert_eq!(host.qp_debug_status()["overlayOpacity"], 1.0);

        host.set_clipboard_ui_runner(|_| panic!("text simulation must not occupy the UI clipboard dispatcher"));
        let simulated = host.qp_web_action(&json!({
            "kind": "clipQuickPaste",
            "action": "simulateText",
            "itemId": item_id
        }));
        assert_eq!(simulated["ok"], true);
        assert_eq!(
            host.inner.lock().qp.last_simulated_text.as_deref(),
            Some("typed-out")
        );

        let armed = host.qp_web_action(&json!({
            "kind": "clipQuickPaste",
            "action": "armedAction",
            "itemId": item_id,
            "armedKind": "simulate"
        }));
        assert_eq!(armed["ok"], true);
        let armed_detail = host.qp_state_detail();
        assert_eq!(armed_detail["armedItemId"], item_id);
        assert_eq!(armed_detail["armedKind"], "simulate");
        assert!(armed_detail["pinProvider"].is_null());
        host.qp_commit(false);
        assert_eq!(
            host.inner.lock().qp.last_armed_kind.as_deref(),
            Some("simulate")
        );
        assert_eq!(host.inner.lock().store.lock().get_clip(&item_id).unwrap().usage_count, 2,
            "the direct and armed simulation must both execute successfully");
        assert_eq!(host.qp_debug_status()["overlayVisible"], false);
        assert!(host.qp_state_detail()["armedItemId"].is_null());
    }

