    #[test]
    fn clipboard_ctrl_f_requires_keyboard_engagement_before_activating_search() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        while host.take_chrome_command().is_some() {}
        {
            let mut inner = host.inner.lock();
            inner.has_host_fake_focus = false;
            inner.pointer_in_host = false;
        }
        let key = KeyEvent {
            vk: 0x46,
            down: true,
            alt: false,
            ctrl: true,
            shift: false,
            win: false,
            now_ms: 1,
        };
        // DESIGN.md: ending keyboard ownership gives the foreground app all
        // keys, including Ctrl+F. Visibility alone must not reactivate search.
        assert!(!host.dispatch_low_level_key(key));
        assert!(host.take_chrome_command().is_none());
        assert!(host.inner.lock().no_focus_session_active);
        assert!(!host.inner.lock().has_host_fake_focus);
        assert!(!host.dispatch_low_level_key(KeyEvent { down: false, ..key }));

        // Reopening or clicking the clipboard restores ownership; the same
        // explicit search chord may then hand input to the native search box.
        host.inner.lock().has_host_fake_focus = true;
        assert!(host.dispatch_low_level_key(key));
        assert!(matches!(
            host.take_chrome_command(),
            Some(ChromeCommand::ClipboardKeyboardFocus)
        ));
        assert!(matches!(
            host.take_chrome_command(),
            Some(ChromeCommand::ClipboardActivateSearch)
        ));
        assert!(!host.inner.lock().no_focus_session_active);
        assert!(host.inner.lock().has_host_fake_focus);
    }

    #[test]
    fn cold_start_keys_pass_through_even_after_page_load_until_window_runtime_ready() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        while host.take_chrome_command().is_some() {}
        host.set_window_runtime_ready(false);
        host.set_clipboard_web_view_ready(true);
        assert_eq!(host.health()["windowRuntimeReady"], false);
        // Simulate the observed order: clipboard page loaded, remaining native
        // windows still being created, no consumer for keyboard commands yet.
        for (vk, ctrl, alt) in [(0x31, false, false), (0x28, false, false),
            (0x46, true, false), (0x1B, false, false), (0xC0, false, true)] {
            for down in [true, false] {
                assert!(!host.dispatch_low_level_key(KeyEvent {
                    vk, down, ctrl, alt, shift: false, win: false, now_ms: 1,
                }));
            }
        }
        assert!(host.take_chrome_command().is_none());
        assert!(host.inner.lock().no_focus_session_active);
        assert!(host.inner.lock().window_visible);
        host.set_window_runtime_ready(true);
        assert_eq!(host.health()["windowRuntimeReady"], true);
        assert!(host.dispatch_low_level_key(KeyEvent {
            vk: 0x31, down: true, ctrl: false, alt: false,
            shift: false, win: false, now_ms: 2,
        }));
        assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::RouteDigit { digit: 1, repeat: false })));
        assert!(host.take_chrome_command().is_none());
    }

    #[test]
    fn clipboard_keys_pass_through_until_webview_ready_without_losing_no_focus_session() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        while host.take_chrome_command().is_some() {}
        host.set_window_runtime_ready(true);
        host.set_clipboard_web_view_ready(false);
        {
            let mut inner = host.inner.lock();
            inner.config.enable_no_focus_mode = true;
            inner.no_focus_session_active = true;
            inner.has_host_fake_focus = true;
            inner.is_active = false;
            inner.foreground_is_host_related = false;
            inner.ui.keyboard_focus_host = None;
        }
        let session_state = || {
            let inner = host.inner.lock();
            (inner.window_visible, inner.no_focus_session_active, inner.has_host_fake_focus,
                inner.is_active, inner.foreground_is_host_related, inner.ui.keyboard_focus_host,
                inner.host_no_activate_dirty)
        };
        let before = session_state();
        assert!(host.clipboard_no_activate());
        assert!(!host.hide_snapshot().web_view_ready);
        // Exercise the real hook dispatcher, including its fallback hide policy.
        // Search must not relinquish no-activate when the UI consumer would drop it.
        for (vk, ctrl) in [(0x31, false), (0x28, false), (0x1B, false), (0x46, true)] {
            for down in [true, false] {
                let swallowed = host.dispatch_low_level_key_for_foreground(KeyEvent {
                    vk, down, ctrl, alt: false, shift: false, win: false, now_ms: 1,
                }, 0);
                assert_eq!(session_state(), before,
                    "unready page changed focus: vk={vk:x}, down={down}");
                assert!(!swallowed, "unready page swallowed vk={vk:x}, down={down}");
                assert!(host.take_chrome_command().is_none());
            }
        }
        for command in [ChromeCommand::ClipboardKeyboardFocus, ChromeCommand::ClipboardActivateSearch] {
            assert!(!host.chrome_command_input_allowed(command));
        }
        host.set_clipboard_web_view_ready(true);
        assert_eq!(session_state(), before, "readiness alone must not activate search");
        assert!(host.take_chrome_command().is_none(), "startup input must not replay later");
        assert!(host.dispatch_low_level_key_for_foreground(KeyEvent {
            vk: 0x46, down: true, ctrl: true, alt: false, shift: false, win: false, now_ms: 2,
        }, 0));
        for expected in [ChromeCommand::ClipboardKeyboardFocus, ChromeCommand::ClipboardActivateSearch] {
            let command = host.take_chrome_command().unwrap();
            assert_eq!(command, expected);
            assert!(host.chrome_command_input_allowed(command));
            assert!(host.prepare_chrome_command(command));
        }
        assert!(host.clipboard_keyboard_focus_allowed());
        assert!(!host.clipboard_no_activate());
        assert!(host.take_chrome_command().is_none());
    }

