    #[test]
    fn clipboard_caps_guide_and_search_char_match_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        while host.take_chrome_command().is_some() {}
        let letter = |vk, shift, t| KeyEvent {
            vk,
            down: true,
            alt: false,
            ctrl: false,
            shift,
            win: false,
            now_ms: t,
        };
        assert!(host.dispatch_low_level_key(letter(0x41, false, 1)));
        assert!(matches!(
            host.take_chrome_command(),
            Some(ChromeCommand::ClipboardAppendSearch('a'))
        ));
        assert!(host.dispatch_low_level_key(letter(0x41, true, 2)));
        assert!(matches!(
            host.take_chrome_command(),
            Some(ChromeCommand::ClipboardAppendSearch('A'))
        ));
        assert!(!host.dispatch_low_level_key(KeyEvent {
            vk: 0x14,
            down: true,
            alt: false,
            ctrl: false,
            shift: false,
            win: false,
            now_ms: 3,
        }));
        assert!(host.inner.lock().caps_guide_until_keyup);
        assert!(host.dispatch_low_level_key(letter(0x49, false, 4)));
        assert!(matches!(
            host.take_chrome_command(),
            Some(ChromeCommand::ClipboardNavKey { key: "ArrowUp", shift: false })
        ));
        assert!(!host.dispatch_low_level_key(KeyEvent {
            vk: 0x14,
            down: false,
            alt: false,
            ctrl: false,
            shift: false,
            win: false,
            now_ms: 5,
        }));
        if !caps_lock_physically_down() {
            assert!(!host.inner.lock().caps_guide_until_keyup);
            assert!(host.dispatch_low_level_key(letter(0x49, false, 6)));
            assert!(matches!(
                host.take_chrome_command(),
                Some(ChromeCommand::ClipboardAppendSearch('i'))
            ));
        }
    }

