    #[test]
    fn menu_setting_nodes_route_to_main_without_showing_clipboard() {
        crate::clipboard::force_headless(true);
        let temp_root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../.tmp");
        std::fs::create_dir_all(&temp_root).unwrap();
        let root = tempfile::Builder::new().prefix("menu-settings-").tempdir_in(temp_root).unwrap();
        let host = HostState::open(AppPaths::from_data_root(root.path().to_path_buf()), 29065).unwrap();
        host.set_window_runtime_ready(true);
        host.set_super_menu_hwnd(200);
        let context = crate::menu_api::MenuBuildContext {
            source_window_handle: 200,
            ..Default::default()
        };
        for native in [false, true] {
            for (page, route) in [
                ("menu_global", "/main/settings/menu_global"),
                ("menu_file", "/main/settings/menu_file"),
                ("textAction", "/main/settings/textAction"),
                ("menu", "/main/settings/menu_global"),
                ("menu_favor", "/main/settings/menu_global"),
                ("menu_window", "/main/settings/menu_global"),
                ("textaction", "/main/settings/textAction"),
                ("user", "/main/settings/user"),
            ] {
                host.window_hide();
                host.mark_main_hidden();
                while host.take_chrome_task().is_some() {}
                host.drain_push_events();
                // Use the real per-session registry without enumerating desktop
                // windows or opening a native picker to construct menu roots.
                let node = crate::menu_api::command("设置", "setting", json!({ "page": page }));
                let node_id = node.id.clone();
                let created = host.menus.create_fixture_session(&context, vec![node]);
                let session = created["sessionId"].as_str().unwrap();
                let generation = {
                    let mut inner = host.inner.lock();
                    inner.super_menu.generation = inner.super_menu.generation.wrapping_add(1);
                    inner.super_menu.visible = true;
                    inner.super_menu.session_id = Some(session.to_string());
                    inner.super_menu.snapshot = Some(created.clone());
                    inner.super_menu.generation
                };
                let request = native.then(|| {
                    host.capture_native_super_menu_action(session, generation, 200).unwrap()
                });
                let result = if let Some(request) = &request {
                    host.menu_invoke_native(&node_id, &json!({}), request)
                } else {
                    host.menu_invoke(session, &node_id, &json!({}))
                }.unwrap();
                assert_eq!(result["closeMenu"], true, "{page}, native={native}");
                assert_eq!(result["refresh"], "None");
                assert!(!host.hide_snapshot().visible, "{page} must not show clipboard");
                assert!(host.inner.lock().ui.main_visible);
                assert_eq!(host.take_pending_nav("main").as_deref(), Some(route));
                assert!(host.take_pending_nav("clipboard").is_none());
                let task = host.take_chrome_task().expect("settings presentation");
                assert!(matches!(task.command(), ChromeCommand::ShowMain));
                assert!(host.chrome_task_explicit_presentation(task));
                assert!(host.prepare_chrome_task(task));
                assert!(host.take_chrome_task().is_none(), "no clipboard Show may be queued");
                let navigation: Vec<_> = host.drain_push_events().into_iter()
                    .filter(|(name, _)| name == "navigate").map(|(_, body)| body).collect();
                assert_eq!(navigation, vec![json!({ "route": route, "page": page })]);
                if let Some(request) = &request {
                    assert!(host.native_super_menu_close_reply_is_current(request));
                }
                // The UI closes the accepted original menu after the reply;
                // retiring that session must not cancel the settings task.
                assert!(host.menu_close_session(session));
                assert_eq!(host.super_menu_state_detail()["visible"], false);
                assert!(host.prepare_chrome_task(task));
                if let Some(request) = &request {
                    assert!(!host.native_super_menu_close_reply_is_current(request));
                }
            }
        }
    }

