    #[tokio::test]
    async fn quicker_rpc_action_preserves_parameters_and_never_retries_failed_dispatch() {
        use tokio::io::AsyncWriteExt;
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let shell_calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let calls = shell_calls.clone();
        host.set_shell_open_runner(move |_| { calls.fetch_add(1, Ordering::SeqCst); Ok(()) });
        let (server, mut peer) = tokio::io::duplex(65536);
        let serving = tokio::spawn(crate::quicker_rpc::serve(server, host.quicker_rpc(), "fixture", Arc::new(crate::pipe_rpc::StopSignal::default()), Arc::new(|_| None)));
        let ping = crate::quicker_rpc::read_message(&mut peer).await.unwrap().unwrap();
        let mut response = ping.clone();
        response.type_name = "response".into();
        response.method = None;
        response.payload = Some(json!("pong"));
        peer.write_all(&crate::pipe_rpc::encode_frame(&response).unwrap()).await.unwrap();
        tokio::time::timeout(Duration::from_secs(2), async {
            while host.quicker_rpc.select().is_none() { tokio::time::sleep(Duration::from_millis(5)).await; }
        }).await.unwrap();
        let long_params = "参数😀".repeat(2000);
        for fail in [false, true] {
            let (caller, params) = (host.clone(), long_params.clone());
            let call = tokio::task::spawn_blocking(move || caller.run_quicker_action(" fixture-action ", &params));
            let request = crate::quicker_rpc::read_message(&mut peer).await.unwrap().unwrap();
            assert_eq!(request.method.as_deref(), Some("quicker.invokeAction"));
            assert_eq!(request.payload.as_ref().unwrap()["ActionId"], "fixture-action");
            assert_eq!(request.payload.as_ref().unwrap()["QuickerInParams"], long_params);
            let reply = if fail { crate::pipe_rpc::PipeRpcMessage::error(request.id, "remote_error", "action failed after dispatch") }
                else { let mut reply = response.clone(); reply.id = request.id; reply.payload = None; reply };
            peer.write_all(&crate::pipe_rpc::encode_frame(&reply).unwrap()).await.unwrap();
            assert_eq!(call.await.unwrap().is_err(), fail);
            assert_eq!(shell_calls.load(Ordering::SeqCst), 0);
        }
        // A connected but unresponsive plugin might already have executed the action.
        let caller = host.clone();
        let call = tokio::task::spawn_blocking(move || caller.run_quicker_action("fixture-action", "timeout"));
        let request = crate::quicker_rpc::read_message(&mut peer).await.unwrap().unwrap();
        assert!(call.await.unwrap().unwrap_err().contains("超时"));
        let cancel = crate::quicker_rpc::read_message(&mut peer).await.unwrap().unwrap();
        assert_eq!((cancel.type_name.as_str(), cancel.id), ("cancel", request.id));
        assert_eq!(shell_calls.load(Ordering::SeqCst), 0);
        let caller = host.clone();
        let call = tokio::task::spawn_blocking(move || caller.run_quicker_action("fixture-action", "disconnect"));
        crate::quicker_rpc::read_message(&mut peer).await.unwrap().unwrap();
        drop(peer);
        assert!(call.await.unwrap().unwrap_err().contains("断开"));
        serving.await.unwrap().unwrap();
        assert_eq!(shell_calls.load(Ordering::SeqCst), 0);
        // A fresh call made while offline may still use the existing URI fallback.
        host.run_quicker_action("fixture-action", "offline").unwrap();
        assert_eq!(shell_calls.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn quicker_launch_failure_preserves_menu_and_panel_usage_until_retry() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let folder = host.favor_folder_create(&json!({"title":"action fixture"})).unwrap();
        let added = host.favor_add_text_items(&json!({"parentId":folder["id"], "text":"action fixture"})).unwrap();
        let id = added["createdIds"][0].as_str().unwrap();
        let store = host.inner.lock().store.clone();
        let mut item = store.lock().get_favor(id).unwrap();
        item.kind = ClipKind::ActionClipItem;
        item.body_text = Some("fixture-action".into());
        item.execute_param = "中文 &parameter".into();
        store.lock().save_favor(&item).unwrap();
        let session = host.menu_create_session("favor");
        let node = session["root"]["items"].as_array().unwrap().iter()
            .find(|node| node["payload"]["favorId"] == id).unwrap();
        let invoke_menu = || host.menu_invoke(session["sessionId"].as_str().unwrap(), node["id"].as_str().unwrap(), &json!({}));
        let calls = Arc::new(Mutex::new(Vec::new()));
        let seen = calls.clone();
        host.set_shell_open_runner(move |uri| {
            seen.lock().push(uri.to_string());
            Err("Quicker protocol launch rejected".into())
        });
        assert_eq!(invoke_menu().unwrap_err(), "Quicker protocol launch rejected");
        assert_eq!(host.panel_invoke(&json!({"favorId":folder["id"], "itemId":id})).unwrap_err(), "Quicker protocol launch rejected");
        assert_eq!(*calls.lock(), ["quicker:runaction:fixture-action?中文 &parameter"; 2]);
        assert_eq!(store.lock().get_usage(&crate::store::favor_usage_key(id)).unwrap().usage_count, 0);
        assert!(host.inner.lock().last_quicker_action_uri.is_none());
        host.set_shell_open_runner(|_| Ok(()));
        assert_eq!(invoke_menu().unwrap()["closeMenu"], true);
        assert_eq!(store.lock().get_usage(&crate::store::favor_usage_key(id)).unwrap().usage_count, 1);
        assert_eq!(host.panel_invoke(&json!({"favorId":folder["id"], "itemId":id})).unwrap()["action"], "executed");
        assert_eq!(store.lock().get_usage(&crate::store::favor_usage_key(id)).unwrap().usage_count, 2);
        item.body_text = Some("  ".into());
        store.lock().save_favor(&item).unwrap();
        assert!(host.panel_invoke(&json!({"favorId":folder["id"], "itemId":id})).is_err());
        assert_eq!(store.lock().get_usage(&crate::store::favor_usage_key(id)).unwrap().usage_count, 2);
    }

