    #[test]
    fn shell_open_pending_launch_keeps_window_search_and_next_attempt_responsive() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let file = dir.path().join("fixture.exe");
        std::fs::write(&file, "not launched by this test").unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.file_menu_add(file.to_str().unwrap()).unwrap();
        let session = host.menu_create_session("file");
        let node = session["root"]["items"].as_array().unwrap().iter()
            .find(|node| node["payload"]["path"] == file.to_str().unwrap()).unwrap();
        let session_id = session["sessionId"].as_str().unwrap().to_string();
        let node_id = node["id"].as_str().unwrap().to_string();
        let web = host.create_session();
        host.add_text(&json!({"text":"during shell launch"})).unwrap();
        let (entered_tx, entered_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let release_rx = Mutex::new(release_rx);
        host.set_shell_open_runner(move |_| {
            entered_tx.send(()).unwrap();
            release_rx.lock().recv_timeout(Duration::from_secs(15)).unwrap();
            Err("launcher rejected".into())
        });
        let launching = host.clone();
        let (pending_session, pending_node) = (session_id.clone(), node_id.clone());
        let pending = thread::spawn(move || launching.menu_invoke(&pending_session, &pending_node, &json!({})));
        entered_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        let (ready_tx, ready_rx) = mpsc::channel();
        let responsive = host.clone();
        let reader = thread::spawn(move || {
            let pinned = responsive.apply_window_action("setPinned", true);
            let search = responsive.search_items(&json!({"query":"during shell launch", "webSessionId":web["sessionId"]}));
            responsive.set_shell_open_runner(|_| Ok(()));
            ready_tx.send((pinned, search)).unwrap();
        });
        let result = ready_rx.recv_timeout(Duration::from_secs(5));
        release_tx.send(()).unwrap();
        assert_eq!(pending.join().unwrap().unwrap_err(), "launcher rejected");
        reader.join().unwrap();
        let (pinned, search) = result.expect("shell launch blocked other host operations");
        assert_eq!(pinned["isPinned"], true);
        assert_eq!(search.unwrap()["total"], 1);
        assert_eq!(host.menu_invoke(&session_id, &node_id, &json!({})).unwrap()["closeMenu"], true);
    }

