    #[test]
    fn foreground_process_changed_matches_csharp_payload_and_throttle() {
        crate::hooks::input_globals_test::enter_shared();
        let _serial = crate::active_window::HISTORY_TEST.lock();
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let _ = host.drain_push_events();
        host.on_foreground_hwnd(0x111);
        let first = host.drain_push_events();
        let payload = first
            .iter()
            .find(|(name, _)| name == "foregroundProcessChanged")
            .map(|(_, data)| data)
            .expect("foregroundProcessChanged");
        assert!(payload["ts"].as_i64().unwrap() > 0);
        assert!(payload.get("op").is_none());
        host.on_foreground_hwnd(0x111);
        assert!(
            host.drain_push_events()
                .iter()
                .all(|(name, _)| name != "foregroundProcessChanged")
        );
        host.on_foreground_hwnd(0x222);
        assert!(
            host.drain_push_events()
                .iter()
                .all(|(name, _)| name != "foregroundProcessChanged"),
            "C# throttles Foreground broadcasts to 120ms"
        );
        host.inner.lock().last_foreground_broadcast_ms = 1;
        host.on_foreground_hwnd(0x333);
        assert!(
            host.drain_push_events()
                .iter()
                .any(|(name, data)| name == "foregroundProcessChanged" && data["ts"].as_i64().unwrap() > 0)
        );
    }

    #[test]
    fn capture_dedupe_bumps_create_time_and_skips_deferred_hidden() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let _first = crate::clipboard::install_test_snapshot(ClipboardSnapshot {
            text: Some("same-capture".into()),
            ..ClipboardSnapshot::default()
        });
        let captured = host.handle_clipboard().unwrap();
        let id = captured["id"].as_str().unwrap().to_string();
        let older = host.inner.lock().store.lock().get_clip(&id).unwrap().create_time;
        std::thread::sleep(Duration::from_millis(5));
        let again = host.handle_clipboard().unwrap();
        assert_eq!(again["id"], id);
        let newer = host.inner.lock().store.lock().get_clip(&id).unwrap().create_time;
        assert!(newer > older);
        assert_eq!(host.inner.lock().store.lock().list_clips().unwrap().len(), 1);

        host.add_text(&json!({ "text": "pending-row" })).unwrap();
        let scheduled = host.clear_all(false).unwrap();
        assert!(!scheduled["clearId"].as_str().unwrap().is_empty());
        let _hidden = crate::clipboard::install_test_snapshot(ClipboardSnapshot {
            text: Some("pending-row".into()),
            ..ClipboardSnapshot::default()
        });
        let fresh = host.handle_clipboard().unwrap();
        assert_ne!(fresh["id"].as_str().unwrap(), "pending-row");
        assert_ne!(fresh["id"].as_str().unwrap(), id);
        let listed = host
            .search_items(&json!({
                "webSessionId": host.create_session()["sessionId"],
                "query": "",
                "take": 20
            }))
            .unwrap();
        assert_eq!(listed["total"], 1);
        assert_eq!(listed["items"][0]["id"], fresh["id"]);
    }

