        host.qp_debug_begin();
        {
            let mut inner = host.inner.lock();
            inner.qp.snipaste_available = true;
            inner.qp.pixpin_available = true;
        }
        // A fresh headless provider probe returns false; snapshots retain the
        // values captured for this session instead of doing that probe again.
        let active = host.qp_state_detail();
        assert_eq!(active["snipasteAvailable"], true);
