    #[test]
    fn quick_paste_state_push_burst_and_pass_through_match_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.add_text(&json!({ "text": "qp-burst" })).unwrap();
        host.qp_handle_key(KeyEvent {
            vk: crate::quick_paste::VK_MENU,
            down: true,
            alt: true,
            ctrl: false,
            shift: false,
            win: false,
            now_ms: 1,
        });
        host.qp_handle_key(KeyEvent {
            vk: 0xC0,
            down: true,
            alt: true,
            ctrl: false,
            shift: false,
            win: false,
            now_ms: 2,
        });
        assert_eq!(host.inner.lock().qp.overlay_visible, true);
        assert!(host.inner.lock().qp.overlay_ready);
        assert!(!host.qp_overlay_pass_through());
        assert!(matches!(
            host.take_chrome_command(),
            Some(ChromeCommand::ShowQuickPaste)
        ));
        let first = host.take_qp_state_burst().expect("immediate first burst push");
        assert_eq!(first["visible"], true);
        assert!(host.take_qp_state_burst().is_none());
        std::thread::sleep(crate::quick_paste::STATE_PUSH_BURST_INTERVAL);
        assert!(host.take_qp_state_burst().is_some());
        host.qp_debug_begin();
        assert!(!host.qp_overlay_pass_through());
        host.qp_debug_end();
        assert!(host.qp_overlay_pass_through());
        assert!(host.take_qp_state_burst().is_none());
    }

    #[test]
    fn quick_paste_bounded_reveal_timeout_matches_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        host.add_text(&json!({ "text": "qp-reveal" })).unwrap();
        host.qp_handle_key(KeyEvent {
            vk: crate::quick_paste::VK_MENU,
            down: true,
            alt: true,
            ctrl: false,
            shift: false,
            win: false,
            now_ms: 1,
        });
        host.qp_handle_key(KeyEvent {
            vk: 0xC0,
            down: true,
            alt: true,
            ctrl: false,
            shift: false,
            win: false,
            now_ms: 2,
        });
        assert!(host.inner.lock().qp.overlay_ready);
        assert!(!host.inner.lock().qp.awaiting_reveal);
        {
            let mut inner = host.inner.lock();
            inner.qp.overlay_ready = false;
            inner.qp.overlay_opacity = 0.0;
            inner.qp.awaiting_reveal = true;
            inner.qp.reveal_deadline = Some(Instant::now() + Duration::from_secs(30));
        }
        host.poll_keyboard_work();
        assert!(!host.inner.lock().qp.overlay_ready);
        {
            let mut inner = host.inner.lock();
            inner.qp.reveal_deadline = Some(Instant::now() - Duration::from_millis(1));
        }
        host.poll_keyboard_work();
        assert!(host.inner.lock().qp.overlay_ready);
        assert_eq!(host.inner.lock().qp.overlay_opacity, 1.0);
        assert!(!host.qp_overlay_pass_through());
        assert!(!host.inner.lock().qp.awaiting_reveal);
        let mut saw_show = false;
        while let Some(cmd) = host.take_chrome_command() {
            if matches!(cmd, ChromeCommand::ShowQuickPaste) {
                saw_show = true;
            }
        }
        assert!(saw_show);
    }

