    #[test]
    fn collect_clip_drafts_from_injected_snapshot() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let missing = host.execute_verb("collect clip").unwrap();
        assert_eq!(missing["ok"], true);
        assert!(missing.get("draftId").is_none());
        let fail_toast = host.take_toast_push().expect("collect fail toast");
        assert_eq!(fail_toast["message"], "无法生成待收藏的条目。");
        assert_eq!(fail_toast["kind"], "warning");
        assert_eq!(fail_toast["title"], "collect");
        assert!(host.execute_verb("collect nope").unwrap_err().contains("collect verb parse errors"));
        let _guard = crate::clipboard::install_test_snapshot(ClipboardSnapshot {
            text: Some("from-selection".into()),
            ..ClipboardSnapshot::default()
        });
        let collected = host.execute_verb("collect clip").unwrap();
        assert_eq!(collected["ok"], true);
        let draft_id = collected["draftId"].as_str().unwrap().to_string();
        let draft = host.collect_get(&json!({ "draftId": draft_id })).unwrap();
        assert_eq!(draft["detail"]["bodyText"], "from-selection");
        let clips = host.inner.lock().store.lock().list_clips().unwrap();
        assert!(
            clips.is_empty(),
            "C# collect clip Handle() suppresses history; must not persist_capture"
        );
        assert_eq!(host.execute_verb("collect link").unwrap_err(), crate::browser::UNAVAILABLE);
        assert_eq!(host.collect_drafts.lock().len(), 1, "no empty link draft on failure");
    }

    #[test]
    fn favor_from_html_clip_keeps_cf_html_payload() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let mut rec = ClipRecord::new_text("<b>hi</b>", "chrome");
        rec.kind = ClipKind::HtmlClipItem;
        rec.html_data = Some("<b>hi</b>".into());
        rec.html_source_url = Some("https://example.com".into());
        rec.qq_rich_text = Some("<QQRichEditFormat></QQRichEditFormat>".into());
        let clip_id = rec.id.clone();
        host.inner.lock().store.lock().insert_clip(&rec, true).unwrap();
        assert_eq!(
            host.favorite_from_clip(&json!({ "id": "missing" })).unwrap_err(),
            "Item not found."
        );
        assert_eq!(host.favorite_from_clip(&json!({ "id": clip_id })).unwrap()["ok"], true);
        let favor_id = host
            .inner
            .lock()
            .store
            .lock()
            .list_favors()
            .unwrap()
            .into_iter()
            .find(|item| item.source_clip_id.as_deref() == Some(clip_id.as_str()))
            .expect("favor from clip")
            .id;
        let detail = host.favor_get(&json!({ "id": favor_id })).unwrap();
        assert_eq!(detail["htmlData"], "<b>hi</b>");
        assert_eq!(detail["htmlSourceUrl"], "https://example.com");
        // C# `ApplyTypedFields`: QqRichText only when `item is QQRichTextItem`.
        assert!(detail["qqRichText"].is_null());
        host.favor_copy(&json!({ "id": favor_id })).unwrap();
        let stored = {
            let store = host.inner.lock().store.clone();
            let rec = store.lock().get_favor(&favor_id).unwrap();
            rec
        };
        assert_eq!(stored.html_data.as_deref(), Some("<b>hi</b>"));
    }

    #[test]
    fn favorite_from_clip_copies_image_to_library_and_keeps_source_process() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let blobs = host.inner.lock().paths.blobs.clone();
        let library = host.inner.lock().paths.image_library.clone();
        std::fs::create_dir_all(&blobs).unwrap();
        let src = blobs.join("shot.png");
        std::fs::write(&src, b"fake-png").unwrap();
        let mut rec = ClipRecord::new_text("", "chrome.exe");
        rec.kind = ClipKind::ImageClipItem;
        rec.title = Some("screenshot".into());
        rec.body_text = None;
        rec.image_path = Some(src.to_string_lossy().into_owned());
        rec.content_hash = hash_files(&[src.to_string_lossy().into_owned()]);
        let clip_id = rec.id.clone();
        host.inner.lock().store.lock().insert_clip(&rec, true).unwrap();
        let _ = host.drain_push_events();
        assert_eq!(host.favorite_from_clip(&json!({ "id": clip_id })).unwrap()["ok"], true);
        let favor_events = host.drain_push_events();
        let favor_changed = favor_events
            .iter()
            .find(|(name, _)| name == "favoritesChanged")
            .map(|(_, data)| data)
            .expect("favoritesChanged");
        assert_eq!(favor_changed["op"], "delta");
        assert!(favor_changed["upsertIds"].as_array().unwrap().iter().any(|v| v.as_str().is_some()));
        let favor = host
            .inner
            .lock()
            .store
            .lock()
            .list_favors()
            .unwrap()
            .into_iter()
            .find(|item| item.source_clip_id.as_deref() == Some(clip_id.as_str()))
            .expect("favor from image clip");
        let dest = library.join("shot.png");
        assert!(dest.is_file());
        assert_eq!(
            favor.image_path.as_deref().map(std::path::Path::new),
            Some(dest.as_path())
        );
        assert_eq!(favor.source_process_name, "chrome.exe");
        assert_eq!(favor.name, "screenshot");
        let history = host.inner.lock().store.lock().get_clip(&clip_id).unwrap();
        assert_eq!(
            history.image_path.as_deref().map(std::path::Path::new),
            Some(src.as_path())
        );
        assert!(
            host.image_bytes(&clip_id).is_err(),
            "history file under blobs is not ClipImageStorageRoots"
        );
        let (bytes, mime) = host.favor_image_bytes(&favor.id).unwrap();
        assert_eq!(bytes, b"fake-png");
        assert_eq!(mime, "image/png");
        let temp_png = host.inner.lock().paths.image_temp.join("20260101_000000_000.png");
        std::fs::write(&temp_png, b"temp-shot").unwrap();
        let mut temp_clip = ClipRecord::new_text("", "chrome.exe");
        temp_clip.kind = ClipKind::ImageClipItem;
        temp_clip.image_path = Some(temp_png.to_string_lossy().into_owned());
        let temp_id = temp_clip.id.clone();
        host.inner.lock().store.lock().insert_clip(&temp_clip, true).unwrap();
        assert_eq!(host.image_bytes(&temp_id).unwrap().0, b"temp-shot");
        #[cfg(windows)]
        {
            // canonicalize produces a \\?\ path on Windows. Both history and
            // favorite image routes must read it against the normal data root.
            temp_clip.image_path = Some(std::fs::canonicalize(&temp_png).unwrap().to_string_lossy().into_owned());
            host.inner.lock().store.lock().save_clip(&temp_clip).unwrap();
            assert_eq!(host.image_bytes(&temp_id).unwrap().0, b"temp-shot");
            let mut extended_favor = favor.clone();
            extended_favor.image_path = Some(std::fs::canonicalize(&dest).unwrap().to_string_lossy().into_owned());
            host.inner.lock().store.lock().upsert_favor(&extended_favor).unwrap();
            assert_eq!(host.favor_image_bytes(&favor.id).unwrap().0, b"fake-png");
        }
        let tree = host.favor_tree().unwrap();
        assert_eq!(tree["items"][&favor.id]["sourceProcessName"], "chrome.exe");

        let qq_src = blobs.join("im.png");
        std::fs::write(&qq_src, b"im").unwrap();
        let mut qq = ClipRecord::new_text("[图片]", "QQ.exe");
        qq.kind = ClipKind::QQRichTextItem;
        qq.qq_rich_text = Some(format!(
            r#"<QQRichEditFormat><EditElement type="3" filepath="{}"></EditElement></QQRichEditFormat>"#,
            qq_src.display()
        ));
        let qq_id = qq.id.clone();
        host.inner.lock().store.lock().insert_clip(&qq, true).unwrap();
        host.favorite_from_clip(&json!({ "id": qq_id })).unwrap();
        let qq_favor = host
            .inner
            .lock()
            .store
            .lock()
            .list_favors()
            .unwrap()
            .into_iter()
            .find(|item| item.source_clip_id.as_deref() == Some(qq_id.as_str()))
            .expect("qq favor");
        let qq_dest = library.join("im.png");
        assert!(qq_dest.is_file());
        let envelope = qq_favor.qq_rich_text.as_deref().unwrap();
        assert!(envelope.contains("im.png"));
        assert!(envelope.contains("Image"));
        assert_eq!(qq_favor.source_process_name, "QQ.exe");
    }

