    fn fire_cleanup_sample(host: &HostState) {
        {
            let mut inner = host.inner.lock();
            inner.last_cleanup_at = Instant::now()
                .checked_sub(CLEANUP_SAMPLE + Duration::from_millis(1))
                .expect("cleanup sample age");
            inner.cleanup_pending = true;
        }
        host.poll_history_cleanup();
    }

    #[test]
    fn max_item_size_cleanup_matches_csharp_sample_and_exit_flush() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        for i in 0..15 {
            host.add_text(&json!({ "text": format!("bulk-{i}") })).unwrap();
        }
        host.inner.lock().config.max_item_size = 1;
        assert_eq!(host.config_get()["nonPinnedItemCount"], 15);
        host.flush_cleanup_now();
        assert_eq!(
            host.config_get()["nonPinnedItemCount"],
            15,
            "exit flush skips >10 without AcknowledgePendingBulkCleanup"
        );
        fire_cleanup_sample(&host);
        assert_eq!(
            host.config_get()["nonPinnedItemCount"],
            1,
            "scheduled Sample trim always applies MaxItemSize"
        );

        let dir2 = tempdir().unwrap();
        let host2 = HostState::open(AppPaths::from_data_root(dir2.path().join("BetterClipTauri")), 28965).unwrap();
        for i in 0..15 {
            host2.add_text(&json!({ "text": format!("ack-{i}") })).unwrap();
        }
        host2
            .settings_form_update(&json!({
                "configId": "clip",
                "values": { "MaxItemSize": 1 }
            }))
            .unwrap();
        assert_eq!(host2.config_get()["nonPinnedItemCount"], 15);
        host2.flush_cleanup_now();
        assert_eq!(
            host2.config_get()["nonPinnedItemCount"],
            1,
            "settings lowering acknowledges bulk prune for exit flush"
        );
    }

    #[test]
    fn background_without_primary_path_returns_and_uses_global_fallback() {
        crate::clipboard::force_headless(true);
        let (done, result) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            let dir = tempdir().unwrap();
            let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
            let primary = dir.path().join("primary.png");
            let fallback = dir.path().join("fallback.jpg");
            std::fs::write(&primary, b"primary").unwrap();
            std::fs::write(&fallback, b"fallback").unwrap();
            let mut responses = Vec::new();
            for (configured, global) in [
                (None, String::new()),
                (None, fallback.to_string_lossy().into_owned()),
                (Some(primary.to_string_lossy().into_owned()), fallback.to_string_lossy().into_owned()),
                (Some(dir.path().join("missing.png").to_string_lossy().into_owned()), fallback.to_string_lossy().into_owned()),
            ] {
                {
                    let mut inner = host.inner.lock();
                    inner.config.window_background_image = configured;
                    inner.extras.global.window_background_image_path = global;
                }
                responses.push(host.window_background_bytes());
                // A resource read must leave the host available to the UI.
                assert!(host.inner.try_lock().is_some());
            }
            done.send(responses).unwrap();
        });
        let responses = result.recv_timeout(Duration::from_secs(15))
            .expect("background lookup deadlocked the host");
        worker.join().unwrap();
        assert_eq!(responses, vec![
            None,
            Some((b"fallback".to_vec(), "image/jpeg".into())),
            Some((b"primary".to_vec(), "image/png".into())),
            None,
        ]);
    }

