        assert_eq!(host
            .favor_update(&json!({ "id": folder_id, "title": "renamed" }))
            .unwrap()["title"], "renamed");

        let html_favor = FavorRecord {
            storage_revision: None,
            id: Uuid::new_v4().simple().to_string(),
            parent_id: None,
            is_folder: false,
            name: "html".into(),
            kind: ClipKind::HtmlClipItem,
            body_text: Some("plain".into()),
            file_paths: Vec::new(),
            image_path: None,
            children: Vec::new(),
            create_time: Utc::now(),
            update_time: Utc::now(),
            source_clip_id: None,
            html_data: Some("<i>old</i>".into()),
            html_source_url: None,
            qq_rich_text: None,
            source_process_name: String::new(),
            sub_index: 0,
            icon: String::new(),
            execute_param: String::new(),
        };
        let html_id = html_favor.id.clone();
        host.inner.lock().store.lock().insert_favor(&html_favor).unwrap();
        let cf = crate::cf_html::build_clipboard_html("<b>hello</b>", Some("https://src.example/"));
        let updated = host
            .favor_update(&json!({
                "id": html_id,
                "htmlData": cf.clone(),
                "title": "  Hello  "
            }))
            .unwrap();
        assert_eq!(updated["title"], "Hello");
        assert_eq!(updated["htmlData"], cf);
        assert_eq!(updated["htmlSourceUrl"], "https://src.example/");

        let mut link = html_favor;
