    #[test]
    fn pin_overlay_sequence_stops_on_copy_or_provider_failure() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        for (failed_copy, failed_pin) in [(1, 0), (2, 0), (0, 1), (0, 2), (0, 0)] {
            let dir = tempdir().unwrap();
            let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
            let mut items = Vec::new();
            for name in ["first image", "second image"] {
                let mut item = ClipRecord::new_text(name, "");
                item.kind = ClipKind::ImageClipItem;
                host.inner.lock().store.lock().insert_clip(&item, true).unwrap();
                items.push(item);
            }
            let copies = Arc::new(AtomicUsize::new(0));
            let seen = copies.clone();
            host.set_clipboard_ui_runner(move |_| {
                let call = seen.fetch_add(1, Ordering::Relaxed) + 1;
                if call == failed_copy { Err("copy rejected".into()) } else { Ok(()) }
            });
            let mut pins = 0;
            let result = host.run_pin_overlay_sequence(&items, "test-provider", true, |provider| {
                assert_eq!(provider, "test-provider");
                pins += 1;
                if pins == failed_pin { Err("provider rejected".into()) } else { Ok(()) }
            });
            assert_eq!(result.is_ok(), failed_copy == 0 && failed_pin == 0);
            let successful = if failed_copy > 0 { failed_copy - 1 } else if failed_pin > 0 { failed_pin - 1 } else { 2 };
            assert_eq!(copies.load(Ordering::Relaxed), if failed_copy > 0 { failed_copy } else if failed_pin > 0 { failed_pin } else { 2 });
            assert_eq!(pins, if failed_copy > 0 { failed_copy - 1 } else if failed_pin > 0 { failed_pin } else { 2 });
            for (index, item) in items.iter().enumerate() {
                assert_eq!(host.inner.lock().store.lock().get_clip(&item.id).unwrap().usage_count, i32::from(index < successful));
            }
        }
    }

    #[test]
    fn pin_overlay_sequence_batches_text_and_counts_only_completed_work() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let mut items = Vec::new();
        for text in ["first text", "second text"] {
            let id = host.add_text(&json!({ "text": text })).unwrap()["createdIds"][0].as_str().unwrap().to_string();
            items.push(host.inner.lock().store.lock().get_clip(&id).unwrap());
        }
        let copies = Arc::new(AtomicUsize::new(0));
        let seen = copies.clone();
        host.set_clipboard_ui_runner(move |_| { seen.fetch_add(1, Ordering::Relaxed); Ok(()) });
        for count_usage in [false, true] {
            let mut pins = 0;
            host.run_pin_overlay_sequence(&items, "test-provider", count_usage, |_| { pins += 1; Ok(()) }).unwrap();
            assert_eq!(pins, 1, "text entries share one clipboard/pin operation");
            for item in &items {
                assert_eq!(host.inner.lock().store.lock().get_clip(&item.id).unwrap().usage_count, i32::from(count_usage));
            }
        }
        assert_eq!(copies.load(Ordering::Relaxed), 2);
    }

    #[test]
    fn pin_overlay_reserves_clipboard_until_provider_finishes_without_locking_host() {
        use std::sync::{mpsc, atomic::AtomicUsize};
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let writes = Arc::new(AtomicUsize::new(0));
        let seen = writes.clone();
        host.set_clipboard_ui_runner(move |job| { seen.fetch_add(1, Ordering::SeqCst); job() });
        let (entered, waiting) = mpsc::channel();
        let (release, blocked) = mpsc::channel();
        let pin_host = host.clone();
        let pin = thread::spawn(move || {
            pin_host.run_pin_overlay_sequence(&[ClipRecord::new_text("pin this", "test")], "test", false, |_| {
                entered.send(()).unwrap();
                blocked.recv_timeout(Duration::from_secs(15)).map_err(|error| error.to_string())?;
                Ok(())
            })
        });
        waiting.recv_timeout(Duration::from_secs(15)).unwrap();
        assert!(host.inner.try_lock().is_some(), "provider wait must leave host state available");
        assert!(host.clipboard_operation.try_lock().is_none(), "pin provider has not consumed the clipboard yet");
        let copy_host = host.clone();
        let (copy_started, started) = mpsc::channel();
        let copy = thread::spawn(move || {
            copy_started.send(()).unwrap();
            copy_host.copy_text_like_app_helper("next menu copy")
        });
        started.recv_timeout(Duration::from_secs(15)).unwrap();
        assert_eq!(writes.load(Ordering::SeqCst), 1);
        release.send(()).unwrap();
        pin.join().unwrap().unwrap();
        copy.join().unwrap().unwrap();
        assert_eq!(writes.load(Ordering::SeqCst), 2);
        assert_eq!(host.take_toast_push().unwrap()["message"], "next menu copy");
    }

    #[test]
    fn file_menu_clipboard_actions_use_ui_dispatch_and_propagate_write_and_paste_failure() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let path = dir.path().join("菜单测试.txt");
        std::fs::write(&path, "fixture").unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let menu = host.menu_create_session_with("file", path.to_str().unwrap());
        let session = menu["sessionId"].as_str().unwrap();
        let file = menu["root"]["items"].as_array().unwrap().iter()
            .find(|item| item["payload"]["path"] == path.to_str().unwrap()).unwrap();
        let context = host.menu_nodes_ex(session, file["id"].as_str().unwrap(), "context-menu", None).unwrap();
        let mut nodes = context["items"].as_array().unwrap().clone();
        let more = nodes.iter().find(|item| item["role"] == "file-copy-more").unwrap()["id"].as_str().unwrap();
        let children = host.menu_nodes_ex(session, more, "children", None).unwrap();
        nodes.extend(children["items"].as_array().unwrap().clone());
        let writes = Arc::new(AtomicUsize::new(0));
        let seen = writes.clone();
        host.set_clipboard_ui_runner(move |_| { seen.fetch_add(1, Ordering::SeqCst); Err("write rejected".into()) });
        host.set_input_runner(|_| panic!("failed copy must not send paste"));
        for role in ["file-copy", "file-copy-path", "file-copy-quoted", "file-copy-name", "file-copy-stem", "file-copy-parent", "file-copy-paste"] {
            let node = nodes.iter().find(|item| item["role"] == role).unwrap();
            assert_eq!(host.menu_invoke(session, node["id"].as_str().unwrap(), &json!({})).unwrap_err(), "write rejected", "{role}");
        }
        assert_eq!(writes.load(Ordering::SeqCst), 7);
        host.set_clipboard_ui_runner(|job| job());
        host.set_input_runner(|_| Err("target input rejected".into()));
        let paste = nodes.iter().find(|item| item["role"] == "file-copy-paste").unwrap();
        assert_eq!(host.menu_invoke(session, paste["id"].as_str().unwrap(), &json!({})).unwrap_err(), "target input rejected");
        assert!(host.clipboard_operation.try_lock().is_some());
    }

    #[test]
    fn text_action_clipboard_and_simulated_output_propagate_dispatch_failures() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let copies = Arc::new(AtomicUsize::new(0));
        let seen = copies.clone();
        host.set_clipboard_ui_runner(move |_| { seen.fetch_add(1, Ordering::SeqCst); Err("write rejected".into()) });
        let activations = Arc::new(AtomicUsize::new(0));
        let seen = activations.clone();
        host.set_input_runner(move |job| {
            assert_eq!(seen.fetch_add(1, Ordering::SeqCst), 0, "failed output must not send paste");
            job()
        });
        host.inner.lock().text_actions = vec![json!({"Type": "Send", "Data": {"Text": "中文输出"}})];
        assert_eq!(host.execute_text_action(&json!({"actionId": "0"}), 0).unwrap_err(), "write rejected");
        assert_eq!(copies.load(Ordering::SeqCst), 1);
        assert_eq!(activations.load(Ordering::SeqCst), 1);
        host.set_clipboard_ui_runner(|job| job());
        host.set_input_runner(|_| Err("input rejected".into()));
        assert_eq!(host.execute_text_action(&json!({"actionId": "0"}), 0).unwrap_err(), "input rejected");
        host.inner.lock().text_actions[0]["Simulate"] = json!(true);
        host.set_clipboard_ui_runner(|_| panic!("simulation must not write clipboard"));
        assert_eq!(host.execute_text_action(&json!({"actionId": "0"}), 0).unwrap_err(), "input rejected");
    }

