    #[test]
    fn fifo_preview_returns_clip_dto_array() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let first = host.add_text(&json!({ "text": "fifo-old" })).unwrap();
        let second = host.add_text(&json!({ "text": "fifo-new" })).unwrap();
        let old_id = first["createdIds"][0].as_str().unwrap().to_string();
        let new_id = second["createdIds"][0].as_str().unwrap().to_string();
        let preview = host
            .fifo_preview(&json!({
                "endId": new_id,
                "ids": [new_id],
                "visibleIds": [new_id, old_id]
            }))
            .unwrap();
        assert!(preview.is_array(), "{preview}");
        let ids: Vec<&str> = preview
            .as_array()
            .unwrap()
            .iter()
            .map(|item| item["id"].as_str().unwrap())
            .collect();
        assert_eq!(ids, vec![old_id.as_str(), new_id.as_str()]);
        let multi = host
            .fifo_preview(&json!({ "ids": [new_id, old_id] }))
            .unwrap();
        let multi_ids: Vec<&str> = multi
            .as_array()
            .unwrap()
            .iter()
            .map(|item| item["id"].as_str().unwrap())
            .collect();
        assert_eq!(multi_ids, vec![old_id.as_str(), new_id.as_str()]);
        let armed = host.fifo_arm(&json!({ "ids": [old_id, new_id] })).unwrap();
        assert_eq!(armed["armed"], true);
        assert_eq!(armed["remainingIds"][0], old_id);
        assert_eq!(armed["nextId"], old_id);
        assert_eq!(
            host.fifo_arm(&Value::Null).unwrap_err(),
            "Request body is required."
        );
        assert_eq!(host.fifo_arm(&json!({})).unwrap_err(), "ids is empty.");
        assert_eq!(
            host.fifo_arm(&json!({ "id": new_id })).unwrap_err(),
            "ids is empty."
        );
        assert_eq!(host.fifo_arm(&json!({ "ids": [] })).unwrap_err(), "ids is empty.");
        assert_eq!(
            host.fifo_arm(&json!({ "ids": ["", "  "] })).unwrap_err(),
            "Unable to arm FIFO paste."
        );
    }

