    fn add_text_empty_and_line_by_line_match_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let empty = host.add_text(&json!({ "text": "" })).unwrap();
        assert_eq!(empty["ok"], false);
        assert_eq!(empty["count"], 0);
        assert_eq!(empty["createdIds"].as_array().unwrap().len(), 0);
        let missing = host.add_text(&json!({})).unwrap();
        assert_eq!(missing["ok"], false);
        let split = host
            .add_text(&json!({ "text": "a\r\n  \nb\n\nc", "lineByLine": true }))
            .unwrap();
        assert_eq!(split["ok"], true);
        assert_eq!(split["count"], 4);
        let ids = split["createdIds"].as_array().unwrap();
        let store = host.inner.lock().store.clone();
        let db = store.lock();
        assert_eq!(db.get_clip(ids[0].as_str().unwrap()).unwrap().body_text.as_deref(), Some("a"));
        assert_eq!(db.get_clip(ids[1].as_str().unwrap()).unwrap().body_text.as_deref(), Some("  "));
        assert_eq!(db.get_clip(ids[2].as_str().unwrap()).unwrap().body_text.as_deref(), Some("b"));
        assert_eq!(db.get_clip(ids[3].as_str().unwrap()).unwrap().body_text.as_deref(), Some("c"));
        let burst: Vec<_> = (0..4)
            .map(|i| db.get_clip(ids[i].as_str().unwrap()).unwrap())
            .collect();
        assert!(burst.windows(2).all(|pair| pair[0].create_time == pair[1].create_time));
        assert_eq!(
            burst.iter().map(|item| item.sub_index).collect::<Vec<_>>(),
            vec![0, 1, 2, 3]
        );
    }

    #[test]
    fn manual_duplicate_adds_return_persisted_independent_ids() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let paths = AppPaths::from_data_root(dir.path().join("BetterClipTauri"));
        let host = HostState::open(paths.clone(), 28965).unwrap();
        host.config_update(&json!({ "allowDuplicateCopy": false })).unwrap();
        assert!(!host.inner.lock().config.allow_duplicate_copy);
        let mut ids = Vec::new();
        for request in [
            json!({ "text": "same" }),
            json!({ "text": "same" }),
            json!({ "text": "same\nsame", "lineByLine": true }),
        ] {
            let added = host.add_text(&request).unwrap();
            ids.extend(added["createdIds"].as_array().unwrap().iter().cloned());
        }
        assert_eq!(ids.len(), 4);
        let distinct: std::collections::HashSet<_> = ids.iter().map(Value::to_string).collect();
        assert_eq!(distinct.len(), 4);
        let reopened = HostState::open(paths, 28966).unwrap();
        for id in &ids {
            assert_eq!(reopened.detail(&json!({ "id": id })).unwrap()["bodyText"], "same");
        }
        host.patch_item(&json!({ "id": ids[1], "bodyText": "edited duplicate" })).unwrap();
        host.delete_item(&json!({ "id": ids[0] })).unwrap();
        assert_eq!(host.detail(&json!({ "id": ids[1] })).unwrap()["bodyText"], "edited duplicate");
        assert_eq!(host.detail(&json!({ "id": ids[2] })).unwrap()["bodyText"], "same");
    }

    #[test]
    fn concurrent_window_search_pin_and_edit_complete_without_lock_inversion() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(
            AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965,
        ).unwrap();
        let added = host.add_text(&json!({ "text": "concurrent-ui" })).unwrap();
        let id = added["createdIds"][0].as_str().unwrap().to_string();
        let session = host.create_session()["sessionId"].as_str().unwrap().to_string();
        host.drain_push_events();
        let barrier = Arc::new(std::sync::Barrier::new(7));
        let (tx, rx) = std::sync::mpsc::channel();
        for worker in 0..6 {
            let host = host.clone();
            let id = id.clone();
            let session = session.clone();
            let barrier = barrier.clone();
            let tx = tx.clone();
            thread::spawn(move || {
                barrier.wait();
                let result = (|| -> Result<(), String> {
                    for round in 0..100 {
                        match worker % 3 {
                            0 => { host.search_items(&json!({ "webSessionId": session, "take": 10 }))?; }
                            1 => { host.toggle_pin(&json!({ "id": id }))?; }
                            _ => { host.patch_item(&json!({
                                "id": id, "bodyText": format!("concurrent-ui-{worker}-{round}"),
                            }))?; }
                        }
                        let _ = tx.send((worker, None));
                    }
                    Ok(())
                })();
                let _ = tx.send((worker, Some(result)));
            });
        }
        drop(tx);
        barrier.wait();
        // A busy parallel suite can spend over 15s on 400 durable writes while
        // still making progress. Detect stalled requests, not total throughput.
        let deadline = Instant::now() + Duration::from_secs(60);
        let mut rounds = [0; 6];
        let mut finished = 0;
        while finished < 6 {
            let wait = deadline.saturating_duration_since(Instant::now())
                .min(Duration::from_secs(15));
            let (worker, result) = rx.recv_timeout(wait).unwrap_or_else(|error| {
                panic!("concurrent UI requests stopped progressing: {error:?}; completed rounds: {rounds:?}")
            });
            if let Some(result) = result {
                result.unwrap();
                finished += 1;
            } else {
                rounds[worker] += 1;
            }
        }
        assert_eq!(rounds, [100; 6]);
        let detail = host.detail(&json!({ "id": id })).unwrap();
        assert_eq!(detail["isTop"], false); // two writers, 100 toggles each
        assert!(detail["bodyText"].as_str().unwrap().starts_with("concurrent-ui-"));
        let changes = host.drain_push_events().into_iter()
            .filter(|(name, _)| name == "clipChanged").count();
        assert_eq!(changes, 400);
    }

    #[test]
    fn panel_settings_picker_values_survive_reload_with_canonical_actions() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let paths = AppPaths::from_data_root(dir.path().join("BetterClipTauri"));
        let host = HostState::open(paths.clone(), 28965).unwrap();
        let root = host.favor_folder_create(&json!({ "title": "settings roundtrip" })).unwrap();
        let form = host.settings_form_get(&json!({ "configId": "panel" })).unwrap();
        let field = form["fields"].as_array().unwrap().iter()
            .find(|field| field["key"] == "FileDefaultClickAction").unwrap();
        for option in field["selectionItems"].as_array().unwrap() {
            let wire_value = option["key"].as_str().unwrap();
            let expected = match wire_value { "copy" => "Copy", "paste" => "Paste", "open" => "Open", _ => panic!("unexpected option") };
            while host.take_chrome_command().is_some() {}
            host.settings_form_update(&json!({ "configId": "panel", "values": {
                "FileDefaultClickAction": wire_value, "FolderDefaultClickAction": wire_value,
            } })).unwrap();
            assert!(matches!(host.take_chrome_command(), Some(ChromeCommand::PanelRefresh)));
            // Also accept lowercase values persisted by earlier Rust builds.
            let mut legacy = host.inner.lock().extras.panel.clone();
            legacy.file_default_click_action = wire_value.into();
            legacy.folder_default_click_action = wire_value.into();
            save_json(&paths.configs.join("PanelConfig.json"), &legacy).unwrap();
            for page in [host.panel_page(&json!({ "favorId": root["id"] })).unwrap(),
                HostState::open(paths.clone(), 28965).unwrap().panel_page(&json!({ "favorId": root["id"] })).unwrap()] {
                assert_eq!(page["appearance"]["fileDefaultClickAction"], expected);
                assert_eq!(page["appearance"]["folderDefaultClickAction"], expected);
            }
        }
    }

    #[test]
    fn panel_invocation_reports_failures_and_recovers() {
        use std::sync::atomic::AtomicUsize;
        crate::clipboard::force_headless(true);
        for action in ["Copy", "Paste", "Open"] {
            for failure in ["clipboard", "activation", "paste"] {
                if action == "Copy" && failure != "clipboard" { continue; }
                let dir = tempdir().unwrap();
                let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
                let folder = host.favor_folder_create(&json!({ "title": "panel fixture" })).unwrap();
                let added = host.favor_add_text_items(&json!({
                    "parentId": folder["id"], "items": [{ "text": "panel text" }],
                })).unwrap();
                let id = added["createdIds"][0].as_str().unwrap();
                let params = json!({ "favorId": folder["id"], "itemId": id });
                host.inner.lock().extras.panel.file_default_click_action = action.into();
                let writes = Arc::new(AtomicUsize::new(0));
                let seen = writes.clone();
                host.set_clipboard_ui_runner(move |job| {
                    seen.fetch_add(1, Ordering::Relaxed);
                    if failure == "clipboard" { Err("clipboard rejected".into()) } else { job() }
                });
                let inputs = Arc::new(AtomicUsize::new(0));
                let seen = inputs.clone();
                host.set_input_runner(move |job| {
                    let call = seen.fetch_add(1, Ordering::Relaxed) + 1;
                    if (failure == "activation" && call == 1) || (failure == "paste" && call == 2) {
                        Err(format!("{failure} rejected"))
                    } else { job() }
                });
                let error = host.panel_invoke(&params).expect_err(&format!("{action}/{failure} must fail"));
                assert_eq!(error, format!("{failure} rejected"));
                assert_eq!(writes.load(Ordering::Relaxed), usize::from(failure != "activation"));
                assert_eq!(inputs.load(Ordering::Relaxed), if action == "Copy" { 0 } else if failure == "paste" { 2 } else { 1 });
                let store = host.inner.lock().store.clone();
                assert_eq!(store.lock().get_usage(&crate::store::favor_usage_key(id)).unwrap().usage_count, 0);

                // A failed click must release operation locks and allow the next attempt.
                host.set_clipboard_ui_runner(|job| job());
                host.set_input_runner(|job| job());
                assert_eq!(host.panel_invoke(&params).unwrap()["action"], "executed");
                assert_eq!(store.lock().get_usage(&crate::store::favor_usage_key(id)).unwrap().usage_count, i32::from(action == "Open"));
            }
        }
    }

    #[test]
    fn panel_layout_page_invoke_move_reorder_match_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        assert_eq!(
            host.panel_layout().unwrap_err(),
            "Panel layout not found."
        );
        assert_eq!(
            host.panel_show(&json!({})).unwrap_err(),
            "Panel not found."
        );
        assert_eq!(
            host.panel_page(&json!({ "favorId": "missing" })).unwrap_err(),
            "Panel page not found."
        );

        let root = host.favor_folder_create(&json!({ "title": "RootA" })).unwrap();
        let root_id = root["id"].as_str().unwrap().to_string();
        let nested = host
            .favor_folder_create(&json!({ "title": "Child", "parentId": root_id }))
            .unwrap();
        let nested_id = nested["id"].as_str().unwrap().to_string();
        let other = host.favor_folder_create(&json!({ "title": "RootB" })).unwrap();
        let other_id = other["id"].as_str().unwrap().to_string();
        let leaf = host
            .favor_add_text_items(&json!({
                "parentId": nested_id,
                "items": [{ "text": "alpha" }, { "text": "beta" }]
            }))
            .unwrap();
        let leaf_a = leaf["createdIds"][0].as_str().unwrap().to_string();
        let leaf_b = leaf["createdIds"][1].as_str().unwrap().to_string();

        let layout = host.panel_layout().unwrap();
        assert_eq!(layout["mode"], "multiRoot");
        assert_eq!(layout["defaultFavorItemId"], root_id);
        assert_eq!(host.inner.lock().extras.favor.root_children.len(), 2);

        host.inner.lock().extras.panel.default_panel_favor_id = other_id.clone();
        let layout = host.panel_layout().unwrap();
        assert_eq!(layout["defaultFavorItemId"], other_id);

        let page = host
            .panel_page(&json!({ "favorId": root_id, "folderId": nested_id }))
            .unwrap();
        assert_eq!(page["title"], "Child");
        assert_eq!(page["canGoBack"], true);
        assert_eq!(page["appearance"]["folderDefaultClickAction"], "Open");
        assert_eq!(page["items"].as_array().unwrap().len(), 2);

        let nav = host
            .panel_invoke(&json!({ "favorId": root_id, "itemId": nested_id }))
            .unwrap();
        assert_eq!(nav["action"], "navigate");
        assert_eq!(nav["navigateFolderId"], nested_id);

        host.inner.lock().extras.panel.folder_default_click_action = "Copy".into();
        let copy_error = host
            .panel_invoke(&json!({ "favorId": root_id, "itemId": nested_id }))
            .unwrap_err();
        // Folder copy is unsupported; unlike C#'s ignored bool, report the failure.
        assert_eq!(copy_error, "Item not found.");

        host.inner.lock().extras.panel.file_default_click_action = "Copy".into();
        let file_copy = host
            .panel_invoke(&json!({ "favorId": root_id, "itemId": leaf_a }))
            .unwrap();
        assert_eq!(file_copy["action"], "executed");

        assert_eq!(
            host.panel_invoke(&json!({ "favorId": root_id, "itemId": "missing" }))
                .unwrap_err(),
            "Panel item not found."
        );

        assert_eq!(
            host.panel_reorder(&json!({
                "folderId": crate::panel::DETACHED_ORPHANS_FOLDER_ID,
                "orderedChildIds": [leaf_a]
            }))
            .unwrap_err(),
            "Operation failed."
        );
        assert_eq!(
            host.panel_reorder(&json!({
                "folderId": nested_id,
                "orderedChildIds": []
            }))
            .unwrap_err(),
            "Operation failed."
        );
        host.panel_reorder(&json!({
            "folderId": nested_id,
            "orderedChildIds": [leaf_b, leaf_a]
        }))
        .unwrap();
        let page = host
            .panel_page(&json!({ "favorId": root_id, "folderId": nested_id }))
            .unwrap();
        assert_eq!(page["items"][0]["id"], leaf_b);
        assert_eq!(page["items"][1]["id"], leaf_a);

        host.panel_reorder(&json!({
            "folderId": "root",
            "orderedChildIds": [other_id, root_id]
        }))
        .unwrap();
        assert_eq!(
            host.inner.lock().extras.favor.root_children,
            vec![other_id.clone(), root_id.clone()]
        );

        assert_eq!(
            host.panel_move(&json!({
                "itemId": leaf_a,
                "targetFolderId": "root"
            }))
            .unwrap_err(),
            "Operation failed."
        );
        host.panel_move(&json!({
            "itemId": leaf_a,
            "targetFolderId": other_id,
            "beforeItemId": Value::Null
        }))
        .unwrap();
        let other_page = host
            .panel_page(&json!({ "favorId": other_id, "folderId": other_id }))
            .unwrap();
        assert_eq!(other_page["items"][0]["id"], leaf_a);
        let nested_page = host
            .panel_page(&json!({ "favorId": root_id, "folderId": nested_id }))
            .unwrap();
        assert_eq!(nested_page["items"].as_array().unwrap().len(), 1);
        assert_eq!(nested_page["items"][0]["id"], leaf_b);

        let shown = host
            .panel_show(&json!({ "favorId": root_id, "folderId": nested_id }))
            .unwrap();
        assert_eq!(shown["shown"], true);
        assert_eq!(shown["favorId"], root_id);
        assert_eq!(shown["folderId"], nested_id);
        assert_eq!(host.inner.lock().ui.panel_visible, true);
        assert_eq!(
            host.panel_context_menu(&json!({})).unwrap_err(),
            "favorId is required."
        );
        assert_eq!(
            host.panel_context_menu(&json!({ "favorId": root_id })).unwrap(),
            json!({ "ok": true })
        );
    }

    #[test]
    fn ole_drag_protects_window_routes_escape_to_ole_and_releases_after_error() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let id = host.add_text(&json!({"text":"drag fixture"})).unwrap()["createdIds"][0].as_str().unwrap().to_owned();
        let (entered_tx, entered_rx) = mpsc::channel();
        let (release_tx, release_rx) = mpsc::channel();
        let release_rx = Mutex::new(release_rx);
        host.set_ole_drag_ui_runner(move |_| {
            entered_tx.send(()).unwrap();
            release_rx.lock().recv_timeout(Duration::from_secs(5)).unwrap();
            Err("drop fixture failed".into())
        });
        let worker = host.clone();
        let selected = id.clone();
        let task = thread::spawn(move || worker.begin_ole_drag(&json!({"ids":[selected]})));
        entered_rx.recv_timeout(Duration::from_secs(5)).unwrap();
        let mut snapshot = host.hide_snapshot();
        snapshot.is_pinned = false;
        snapshot.pointer_in_host = false;
        snapshot.expand_grace_until_ms = 0;
        assert!(snapshot.move_interaction_active);
        assert_eq!(evaluate(HostHideTrigger::Poll, &snapshot).window_action, crate::hide_policy::HostDismissAction::None);
        assert!(!host.dispatch_low_level_key(KeyEvent {
            vk:0x1B, down:true, alt:false, ctrl:false, shift:false, win:false, now_ms:1,
        }));
        assert!(host.inner.lock().window_visible);
        assert!(host.begin_ole_drag(&json!({"ids":[id]})).unwrap_err().contains("already in progress"));
        release_tx.send(()).unwrap();
        assert_eq!(task.join().unwrap().unwrap_err(), "drop fixture failed");
        assert!(!host.hide_snapshot().move_interaction_active);
        host.set_ole_drag_ui_runner(|_| Ok(()));
        assert_eq!(host.begin_ole_drag(&json!({"ids":[id]})).unwrap()["started"], true);
    }

    #[test]
    fn ole_drag_empty_ids_and_ui_runner_match_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let empty = host.begin_ole_drag(&json!({ "ids": [] })).unwrap();
        assert_eq!(empty["ok"], true);
        assert_eq!(empty["started"], false);
        let missing_field = host.begin_ole_drag(&json!({})).unwrap();
        assert_eq!(missing_field["ok"], true);
        assert_eq!(missing_field["started"], false);
        let missing_items = host.begin_ole_drag(&json!({ "ids": ["no-such"] })).unwrap();
        assert_eq!(missing_items["started"], false);

        let added = host.add_text(&json!({ "text": "drag-me" })).unwrap();
        let id = added["createdIds"][0].as_str().unwrap().to_string();
        let silent = host.begin_ole_drag(&json!({ "ids": [id] })).unwrap();
        assert_eq!(silent["ok"], true);
        assert_eq!(silent["started"], false);

        let seen = Arc::new(Mutex::new(None::<String>));
        let seen_cb = seen.clone();
        host.set_ole_drag_ui_runner(move |payload| {
            *seen_cb.lock() = Some(payload.text.clone());
            Ok(())
        });
        let started = host.begin_ole_drag(&json!({ "ids": [id] })).unwrap();
        assert_eq!(started["ok"], true);
        assert_eq!(started["started"], true);
        assert_eq!(started["count"], 1);
        assert_eq!(seen.lock().as_deref(), Some("drag-me"));

        host.set_ole_drag_ui_runner(|_| Err("DoDragDrop failed".into()));
        assert_eq!(host.begin_ole_drag(&json!({ "ids": [id] })).unwrap_err(), "DoDragDrop failed");
    }

    #[test]
    fn copy_items_runs_on_ui_runner_like_csharp() {
        crate::clipboard::force_headless(true);
        std::env::set_var("CLIPHOST_TAURI_HEADLESS", "1");
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let added = host.add_text(&json!({ "text": "copy-me" })).unwrap();
        let id = added["createdIds"][0].as_str().unwrap().to_string();
        let ran = Arc::new(AtomicBool::new(false));
        let flag = ran.clone();
        host.set_clipboard_ui_runner(move |job| {
            flag.store(true, Ordering::Relaxed);
            job()
        });
        let copied = host.copy_items(&json!({ "ids": [id] })).unwrap();
        assert_eq!(copied, json!({ "ok": true }));
        assert!(ran.load(Ordering::Relaxed));
    }

    #[test]
    fn favorite_clipboard_operations_use_ui_runner_and_report_failures() {
        crate::clipboard::force_headless(true);
        let dir = tempdir().unwrap();
        let host = HostState::open(AppPaths::from_data_root(dir.path().join("BetterClipTauri")), 28965).unwrap();
        let added = host.favor_add_text_items(&json!({ "text": "中文 🦀" })).unwrap();
        let params = json!({ "id": added["createdIds"][0] });
        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let seen = calls.clone();
        let inner = host.inner.clone();
        host.set_clipboard_ui_runner(move |job| {
            // Never dispatch to the UI while holding locks it may need.
            let host_guard = inner.try_lock().expect("host unlocked before dispatch");
            let db_guard = host_guard.store.try_lock().expect("store unlocked before dispatch");
            drop(db_guard);
            drop(host_guard);
            seen.fetch_add(1, Ordering::Relaxed);
            job()
        });
        assert_eq!(host.favor_copy(&params).unwrap(), json!({ "ok": true }));
        assert_eq!(host.favor_paste(&params).unwrap(), json!({ "ok": true }));
        assert_eq!(calls.load(Ordering::Relaxed), 2);

        host.set_clipboard_ui_runner(|_| Err("clipboard unavailable".into()));
        assert_eq!(host.favor_copy(&params).unwrap_err(), "clipboard unavailable");
        assert_eq!(host.favor_paste(&params).unwrap_err(), "clipboard unavailable");
    }
